(window.GIM_TS=window.GIM_TS||{})["Berakhot.4"]={"from":96,"a":[["\u0003אף \"ברכו\",\u0004 שמותר במקרה זה לומר גם \"ברכו\" \u0003ומכל מקום \"נברך\" עדיף,\u0004 וראיה לדבר ממה ש\u0003אמר רב אדא בר אהבה,\u0004 שכך \u0003אמרי בי\u0004 \u0005[אמרו\u0006 חכמי \u0005בית\u0006 המדרש\u0005]\u0006 של \u0003רב, תנינא\u0004 \u0005[שנינו]:\u0006 \u0003ששה\u0004 שאכלו יחד \u0003נחלקין\u0004 לשתי קבוצות בברכה, משום שכל קבוצה יכולה לזמן לעצמה, \u0003עד עשרה,\u0004 שעשרה מזמנים בהזכרת השם, ואסור להם להתחלק ולבטל זימון זה.","ומעתה נדון בדבר, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שלומר \u0003\"נברך\" עדיף\u0004 — \u0003משום הכי\u0004 \u0005[כך]\u0006 שישה אנשים שאכלו כאחת הריהם \u0003נחלקין, אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שלומר \u0003\"ברכו\" עדיף\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003נחלקין,\u0004 והרי אי אפשר לומר אז \"ברכו\"! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שלומר \u0003\"נברך\",\u0004 שבכך אין המזמן מוציא את עצמו מן הכלל, \u0003עדיף.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","ובענין זה, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 בתוספתא: \u0003בין שאמר \"ברכו\" בין שאמר \"נברך\"\u0004 — \u0003אין תופסין אותו על כך,\u0004 כלומר, אין מקפידים בכך. \u0003ו\u0004רק \u0003הנקדנין,\u0004 כלומר, אנשים המדקדקים בדברים קטנים, \u0003תופסין אותו על כך. ו\u0004בכלל אמרו כי \u0003מ\u0004סגנון \u0003ברכותיו של אדם ניכר אם תלמיד חכם הוא אם לאו\u0004 \u0005[לא].\u0006 \u0003כיצד?\u0004 דוגמא לכך \u0003רבי אומר,\u0004 שאם אמר בזימון \u0003\"ובטובו\"\u0004 (\"ברוך שאכלנו משלו ובטובו חיינו\") — \u0003הרי זה תלמיד חכם,\u0004 ואם אמר \u0003\"ומטובו\"\u0004 — \u0003הרי זה בור,\u0004 שמביטוי זה נשמע שרק מקצת מטובו של ה' ניתן לו והריהו ככופר בחסד ה'.","על כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב דימי\u0004 בשאלה: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בברכה נוסח מעין זה, שכך אמר אמר דוד המלך בתפילתו: \u0003\"\u0004ועתה הואל וברך את בית עבדך להיות לעולם לפניך כי אתה ה' אלהים דברת \u0003ומברכתך יברך את בית עבדך לעולם\"\u0004 (שמואל ב ז, כט), והרי גם דוד אומר \"מברכתך\"! ומשיבים: \u0003בשאלה שאני\u0004 \u0005[שונה]\u0006 הדבר, שאין זה נאה שיתבע אדם את כל שפע הברכה. על כך שואלים: \u0003בשאלה נמי\u0004 \u0005[גם כן]\u0006 מצאנו מילוי כל שפע הברכה, שכן \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"הרחב פיך ואמלאהו\"!\u0004 (תהלים פא, יא), ואם כן ככל שאדם מבקש יותר — ינתן לו יותר. ומשיבים: הפסוק \u0003ההוא, בדברי תורה כתיב\u0004 \u0005[נאמר],\u0006 שבדברי תורה מותר לו לאדם לבקש ביותר.","ועוד בנוסח הזימון, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 האומר בזימון \u0003\"בטובו חיינו\"\u0004 — \u0003הרי זה תלמיד חכם,\u0004 ואילו האומר \u0003\"\u0004בטובו \u0003חיים\"\u0004 — \u0003הרי זה בור,\u0004 משום שהוא מוציא עצמו מן הכלל. \u0003נהרבלאי\u0004 \u0005[חכמי העיר נהרבלא]\u0006 \u0003מתני איפכא\u0004 \u0005[שונים להיפך],\u0006 שלדעתם \"בטובו חיים\" עדיף, מפני שהוא נוסח כללי יותר, בעוד ש\"חיינו\" הוא מצומצם ואישי. אך מסכמים: \u0003ולית הילכתא\u0004 \u0005[ואין הלכה]\u0006 \u0003כנהרבלאי.\u0004","מעין זה \u0003אמר ר' יוחנן:\u0004 האומר בנוסח הזימון \u0003\"נברך שאכלנו משלו\"\u0004 — \u0003הרי זה תלמיד חכם,\u0004 ואילו זה האומר \u0003\"למי שאכלנו משלו\"\u0004 — \u0003הרי זה בור,\u0004 שנראה כאילו הוא מברך את בעל הסעודה.","על כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: והא אמרינן\u0004 \u0005[והרי אנו אומרים]\u0006 \u0003\"למי שעשה לאבותינו ולנו את כל הנסים האלה\",\u0004 והרי שמשתמשים בנוסח הברכה בביטוי \"למי\". \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם מוכחא מילתא\u0004 \u0005[שם מוכח הדבר]\u0006 שהכוונה לקדוש ברוך הוא, שהרי \u0003מאן עביד ניסי\u0004 \u0005[מי עושה נסים]\u0006 — \u0003קודשא בריך הוא\u0004 \u0005[הקדוש ברוך הוא],\u0006 אך לגבי המזון אין זה ברור שכוונת הדברים לקדוש ברוך הוא, ויכולים הם להיראות כהודאה לבעל הבית.","ועוד בנוסח הזימון, \u0003אמר ר' יוחנן:\u0004 האומר בנוסח הזימון \u0003\"ברוך שאכלנו משלו\"\u0004 — \u0003הרי זה תלמיד חכם.\u0004 ואם אמר \u0003\"על המזון שאכלנו\"\u0004 — \u0003הרי זה בור,\u0004 שנראה שהוא מברך את בעל הבית על המזון, שאם לה' הוא מברך משום מה יזכיר רק מזון? (תוספות).","על כך \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: לא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא בשלשה, דליכא\u0004 \u0005[שאין]\u0006 בזימון הזכרת \u0003שם שמים, אבל בעשרה, דאיכא\u0004 \u0005[שיש]\u0006 בנוסח הזימון הזכרת \u0003שם שמים\u0004 — \u0003מוכחא מילתא\u0004 \u0005[מוכח הדבר]\u0006 למי הוא מתכוון, \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003כענין שהוא מברך, כך עונין אחריו: \"ברוך ה' אלהי ישראל אלהי הצבאות יושב הכרובים על המזון שאכלנו\".\u0004","שנינו במשנה בנוסח הזימון: \u0003אחד עשרה\u0004 אוכלים, \u0003ואחד עשרה רבוא\u0004 מזמנים באותו נוסח. על כך מקשים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה],\u0006 שהרי מצד אחד \u0003אמרת\u0004 כי \u0003אחד עשרה ואחד עשרה רבוא, אלמא כי הדדי נינהו\u0004 \u0005[מכאן שאותו דבר הם]\u0006 ותמיד מברכים אותה ברכה \u0003והדר קתני\u0004 \u0005[וחזר ושנה]\u0006 \u0003במאה אומר, באלף אומר, ברבוא אומר,\u0004 הרי שבכל זאת יש שינוי בין מספרים שונים!","\u0003אמר רב יוסף: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה] ,\u0006 כי שני דברים אלה הם שתי שיטות, \u0003הא\u0004 \u0005[זו]\u0006 שיטת \u0003ר' יוסי הגלילי, הא\u0004 \u0005[זו]\u0006 שיטת \u0003ר' עקיבא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יוסי הגלילי אומר: לפי רוב הקהל הם מברכין, שנאמר: \"במקהלות ברכו אלהים\".\u0004","עוד שנינו במשנה ש\u0003אמר ר' עקיבא: מה מצינו בבית הכנסת\u0004 אחד מרובים ואחד מועטים אומר \"ברכו את ה'\". ואף בברכת המזון אין משנים את הנוסח לפי מספר המברכים. על כך שואלים: \u0003ור' עקיבא האי קרא\u0004 \u0005[פסוק זה]\u0006 שהביא \u0003ר' יוסי הגלילי\u0004 כראיה לשיטתו \u0003מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו]?\u0006 ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך אותו ל\u0006ענין זה \u0005ששנוי\u0006 בברייתא\u0005],\u0006 ש\u0003היה ר' מאיר אומר: מנין שאפילו עוברין שבמעי אמן אמרו שירה על הים\u0004 — \u0003שנאמר\u0004 בפרק תהלים המתאר את יציאת מצרים: \u0003\"במקהלות ברכו אלהים ה' ממקור ישראל\",\u0004 ובכלל \"מקהלות\" גם העוברים. וחוזרים ושואלים: \u0003ואידך\u0004 \u0005[והאחר\u0006, ר' יוסי הגלילי\u0005]\u0006 מנין דורש הוא ענין זה של שירת העוברים? ומשיבים: \u0003מ\"מקור\" נפקא\u0004 \u0005[יוצאת]\u0006 דרשה זו, ש\"מקור ישראל\" הוא רמז לרחם.","\u0003אמר רבא: הלכה כר' עקיבא.\u0004 ומסופר כי \u0003רבינא ורב חמא בר בוזי אקלעו לבי ריש גלותא\u0004 \u0005[נקלעו,\u0006 נזדמנו \u0005לבית ראש הגולה]\u0006 לסעודה. בסוף הסעודה \u0003קם\u0004 \u0005[עמד]\u0006 \u0003רב חמא וקא מהדר אבי\u0004 \u0005[והיה מחזר אחר בית,\u0006 אגודה, של\u0005]\u0006 \u0003מאה\u0004 סועדים, על מנת שיוכל לעשות את הזימון המיוחד למאה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא: לא צריכת\u0004 \u0005[צריך אתה]\u0006 לכך, שהרי \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רבא: הלכה כר' עקיבא\u0004 שאין נוסח הזימון משתנה לפי מספר המסובים, כשהם יותר מעשרה.","ועוד מענין סעודה בבית ראש הגולה והנהגתו של רבא בסעודה, \u0003אמר רבא: כי אכלינן ריפתא בי ריש גלותא, מברכינן\u0004 \u0005[כאשר היינו אוכלים לחם בבית ראש הגולה, היינו מברכים]\u0006 \u0003שלשה שלשה.\u0004 ושואלים: \u0003וליברכו\u0004 \u0005[ושיברכו]\u0006 \u0003עשרה עשרה!\u0004 ומשיבים: \u0003שמע ריש גלותא, ואיקפד\u0004 \u0005[ישמע ראש הגולה, ויקפיד],\u0006 שיראה שחבורת חכמים יושבת ומברכת לעצמה לפני שסיים הוא סעודתו. ושואלים: \u0003וניפקו בברכתא דריש גלותא\u0004 \u0005[ויצאו בברכתו של ראש הגולה]!\u0006 ומשיבים: \u0003איידי דאוושו כולי עלמא, לא שמעי\u0004 \u0005[משום שרועשים הכל, אין שומעים]\u0006 ואי אפשר לצאת ידי חובה בזימון זה.","\u0003אמר רבה תוספאה: הני תלתא דכרכי רפתא בהדי הדדי, וקדים חד מינייהו ובריך לדעתיה\u0004 \u0005[אלו שלושה\u0006 אנשים \u0005האוכלים פת ביחד, וקדם אחד מהם וברך\u0006 ברכת המזון \u0005לדעתו,\u0006 לעצמו\u0005]\u0006 — \u0003אינון נפקין\u0004 \u0005[הם יוצאים]\u0006 ידי חובתם \u0003בזמון דידיה\u0004 \u0005[שלו]\u0006 אם זימנו לאחר מכן וצירפו אותו שאכל וברך לזימון שלהם, ואולם \u0003איהו\u0004 \u0005[הוא]\u0006 \u0003לא נפיק\u0004 \u0005[יוצא]\u0006 ידי חובתו \u0003בזמון דידהו\u0004 \u0005[שלהם],\u0006 וטעמו של דבר — \u0003לפי שאין זמון למפרע,\u0004 שלאחר הברכה שוב אין הזימון מועיל.","במשנה הובא שר' עקיבא אומר שאומרים בבית הכנסת \"ברכו את ה'\", ואילו \u0003ר' ישמעאל אומר\u0004 שיש לומר בבית הכנסת \"ברכו את ה' המבורך\", ומסופר: \u0003רפרם בר פפא אקלע לבי כנישתא\u0004 \u0005[נקלע,\u0006 הזדמן, \u0005לבית הכנסת]\u0006 של הישוב \u0003אבי גיבר, קם קרא בספרא\u0004 \u0005[עמד לקרוא בספר\u0006 התורה\u0005]\u0006 \u0003ואמר\u0004 בברכתו \u0003\"ברכו את ה'\", ואשתיק\u0004 \u0005[והשתתק],\u0006 \u0003ולא אמר\u0004 גם \u0003\"המבורך\". אוושו כולי עלמא\u0004 \u0005[רעשו כל הציבור]:\u0006 \u0003\"ברכו את ה' המבורך\"!\u0004 כי רפרם בר פפא נהג על פי הכלל שהלכה כר' עקיבא, והם לא היו רגילים בכך. \u0003אמר\u0004 לו \u0003רבא: פתיא אוכמא\u0004 \u0005[סיר שחור],\u0006 והוא כינוי חיבה לחבר ותיק, תלמיד חכם המתייגע על התורה ועל העבודה, \u0003בהדי פלוגתא\u0004 \u0005[אצל מחלוקת]\u0006 שנחלקו בה תנאים, \u0003למה לך\u0004 להתערב? שאף כי נחלקו בדבר זה ר' עקיבא ור' ישמעאל, הרי שניהם מסכימים לנוסחת ר' ישמעאל הכוללת יותר. \u0003ועוד, הא נהוג עלמא\u0004 \u0005[הרי נוהג העולם]\u0006 \u0003כר' ישמעאל.\u0004","\u0003שלשה\u0004 אנשים \u0003שאכלו כאחת\u0004 (ביחד) — \u0003אינן רשאין ליחלק\u0004 שיברכו ברכת המזון בנפרד, אלא יזמנו כאחד. \u0003וכן\u0004 הוא הדין ב\u0003ארבעה\u0004 שאכלו ביחד, \u0003וכן\u0004 ב\u0003חמשה\u0004 אוכלים. ואולם אם היו \u0003ששה\u0004 שאכלו ביחד — \u0003נחלקין,\u0004 וכל שלושה אוכלים יזמנו לעצמם. וכן הוא הדין בשבעה ובשמונה ובתשעה אוכלים, \u0003עד עשרה. ועשרה\u0004 — \u0003אין נחלקין, עד עשרים.\u0004 שכך הוא הכלל: חבורה שאכלה כאחת אינה רשאית להתחלק אלא אם כן יוכלו החבורות הנשארות לברך כדרך שהיו מברכים קודם.","ועוד הלכה, בענין צירופן של שתי חבורות: \u0003שתי חבורות שהיו אוכלות בבית אחד, בזמן שמקצתן רואין אלו את אלו\u0004 — \u0003הרי אלו מצטרפין לזמון, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אלו מזמנין לעצמן ואלו מזמנין לעצמן.\u0004","ולענין ברכת היין, \u0003אין מברכין על היין עד שיתן לתוכו מים,\u0004 אלו \u0003דברי ר' אליעזר.\u0004 כי יין חי שלא מזגו בו מים, חריף מדי ואינו ראוי לברכה. \u0003ו\u0004אילו \u0003חכמים אומרים:\u0004 מאחר שיין זה אפשר לשתותו, אף \u0003מברכין\u0004 עליו.","שנינו בתחילת המשנה כי שלושה שאכלו כאחת אינם רשאים ליחלק, ושואלים: \u0003מאי קא משמע לן? תנינא חדא זימנא\u0004 \u0005[מה השמיע לנו\u0006 במשנה זו? הרי כבר \u0005שנינו פעם אחת]\u0006 כי \u0003שלשה שאכלו כאחת חייבין לזמן,\u0004","ומשיבים כי בכל זאת יש חידוש במשנתנו, ו\u0003הא קא משמע לן, כי הא\u0004 \u0005[\u0006דבר \u0005זה השמיעה לנו\u0006 המשנה, \u0005כמו\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר ר' אבא\u0004 שכך \u0003אמר שמואל: שלשה שישבו לאכול כאחת, ו\u0004אף על פי ש\u0003עדין לא אכלו\u0004 — \u0003אינן רשאין\u0004 אחר כך \u0003ליחלק\u0004 לשתי קבוצות.","נאמרה עוד \u0003לישנא אחרינא\u0004 \u0005[לשון\u0006 גירסה \u0005אחרת]\u0006 של הדברים הללו: \u0003אמר ר' אבא אמר שמואל, הכי קתני\u0004 \u0005[כך שנינו]:\u0006 \u0003שלשה שישבו לאכול כאחת, אף על פי שכל אחד ואחד אוכל מככרו\u0004 שלו ואינם משותפים בסעודתם, בכל זאת נחשבים הם לחבורה אחת לענין זימון, ולכן \u0003אינן רשאין ליחלק. אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר שדברים אלו שבמשנתנו באו ללמד \u0003כי הא\u0004 \u0005[כמו\u0006 הלכה \u0005זו]\u0006 של \u0003רב הונא,\u0004 שכן \u0003אמר רב הונא: שלשה\u0004 אנשים \u0003שבאו משלש חבורות,\u0004 וישבו לאכול יחד, נעשו אף הם חבורה ו\u0003אינן רשאין ליחלק.\u0004","על הלכה זו \u0003אמר רב חסדא: ו\u0004דין זה \u0003הוא\u0004 נוהג רק כ\u0003שבאו\u0004 כל אחד מן האנשים הללו \u0003משלש חבורות של שלשה בני אדם,\u0004 שכל אחת מחבורות אלה היתה חייבת כשלעצמה בזימון, שאז לא פקעה חובת הזימון מהם.","הגבלה נוספת של הדברים \u0003אמר רבא:\u0004"],["\u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא\u0004 כש\u0003לא אקדימו הנך ואזמון עלייהו בדוכתייהו\u0004 \u0005[הקדימו ההם,\u0006 בני החבורות הקודמות שנשארו במקומם, \u0005וזמנו עליהם במקומם],\u0006 \u0003אבל אזמון עלייהו בדוכתייהו\u0004 \u0005[זימנו עליהם במקומם]\u0006 — \u0003פרח\u0004 חיוב \u0003זימון מינייהו\u0004 \u0005[מהם],\u0006 שהרי חיובם של שלושה אלה בזימון נובע מחובתם לזמן עם בני חבורותיהם הקודמות, אך אם הקדימו ההם וזימנו, ממילא פקעה חובת הזימון של יחידים אלה, ואינם מצטרפים עוד לחבורה.","וכדי להסביר את העקרון הכללי המצוי בפסק הלכה זה \u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה,\u0006 את ההלכה הזאת\u0005]\u0006 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מטה\u0004 שהיתה טמאה \u0003שנגנבה חציה, או שאבדה חציה, או שחלקוה אחין\u0004 ביניהם לאחר שירשו אותה מאביהם, \u0003או\u0004 שחילקוה \u0003שותפין\u0004 ביניהם — \u0003טהורה\u0004 היא, כדין כל כלי טמא שנשבר או נחלק שבכך הוא נטהר מטומאתו. ואולם אם \u0003החזירוה\u0004 וצירפו את חלקיה — \u0003מקבלת טומאה מכאן ולהבא,\u0004 כלומר, מעת צירופה מחדש.","ומדייק רבא: \u0003מכאן ולהבא\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 ואולם \u0003למפרע\u0004 — \u0003לא. אלמא\u0004 \u0005[הרי איפוא],\u0006 יש להסיק כי \u0003כיון דפלגוה\u0004 \u0005[שחילקוה]\u0006 — \u0003פרח לה טומאה מינה\u0004 \u0005[ממנה],\u0006 ואף שחזרו והרכיבוה הריהי כמיטה חדשה, ואין טומאתה הישנה חוזרת אליה. ואם כן, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כיון דאזמון עלייהו\u0004 \u0005[שזימנו עליהם]\u0006 בני חבורתם, \u0003פרח זימון מינייהו\u0004 \u0005[מהם]\u0006 על פי העקרון שיחידה שנתפרקה, גם אם לאחר מכן הורכבה מחדש, הריהי כדבר חדש ולא חזרה לדמותה הקודמת.","במשנה הוסבר מתי מצטרפות \u0003שתי חבורות\u0004 שאכלו בבית אחד, ומביאים תוספת דברים: \u0003תנא\u0004 \u0005[שנינו]:\u0006 \u0003אם יש שמש ביניהם\u0004 והוא משמש את שתי החבורות — ה\u0003שמש מצרפן\u0004 להיות חבורה אחת, אף על פי שאינם רואים אלו את אלו.","במשנה שנינו שדעת ר' אליעזר היא ש\u0003אין מברכין על היין\u0004 עד שיתן לתוכו מים, וחכמים אומרים שמברכים. ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003יין עד שלא נתן לתוכו מים\u0004 — \u0003אין מברכין עליו \"בורא פרי הגפן\" אלא \"בורא פרי העץ\",\u0004 שאין זה אלא כעין מיץ פירות בלבד, ולא יין של ממש. \u0003ו\u0004כיון שאינו נחשב ליין, אף \u0003נוטלין ממנו ל\u0004צורך נטילת \u0003ידים. משנתן לתוכו מים\u0004 — הריהו נחשב יין, ולכן \u0003מברכין עליו \"בורא פרי הגפן\", ואין נוטלין ממנו לידים,\u0004 אלו \u0003דברי ר' אליעזר. וחכמים אומרים: בין כך ובין כך,\u0004 בין שמזגו במים ובין שלא מזגו, הרי הוא יין לכל דבר, ולכן \u0003מברכין עליו \"בורא פרי הגפן\" ואין נוטלין הימנו לידים.\u0004","ודנים מעתה, \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר שמואל: עושה אדם כל צרכיו בפת,\u0004 שמותר להשתמש בה לא רק לאכילה אלא גם לשאר צרכים, בלי לחשוש לבזיון האוכל, \u0003כמאן\u0004 \u0005[כמי]\u0006 משיטות התנאים הללו? ומשיבים: \u0003כר' אליעזר\u0004 המתיר ליטול ידים ביין חי.","הוסיף ו\u0003אמר ר' יוסי בר' חנינא: מודים חכמים לר' אליעזר בכוס של ברכה. שאין מברכין עליו עד שיתן לתוכו מים. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר רב אושעיא: בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהא ה\u0003מצוה מן המובחר.\u0004","ולגופו של דבר שואלים: \u0003ורבנן, למאי חזי\u0004 \u0005[ו\u0006לדעת \u0005חכמים למה ראוי]\u0006 יין חי, שלא נמזג בו מים, שהרי כמעט שאין אפשרות לשתותו? \u0003אמר ר' זירא:\u0004 ראוי הוא \u0003לקורייטי,\u0004 כלומר, לעשות ממנו משקה רפואה העשוי מיין ושמן.","ועוד בענין זה של עשיית צרכי האדם באוכלים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארבעה דברים נאמרו בפת: אין מניחין בשר חי על הפת,\u0004 שלא יטוף הדם מן הבשר על הלחם ויפסול אותו מאכילה. \u0003ואין מעבירין כוס מלא\u0004 יין \u0003על הפת,\u0004 שמא יישפכו הנוזלים ויקלקלו את הפת. \u0003ואין זורקין את הפת. ואין סומכין\u0004 (משעינים) \u0003את הקערה\u0004 בפרוסת לחם. וכל אלה כדי שלא לבזות את הלחם.","מסופר: \u0003אמימר ומר זוטרא ורב אשי כרכו ריפתא בהדי הדדי\u0004 \u0005[אכלו יחד],\u0006 \u0003אייתי לקמייהו תמרי ורמוני\u0004 \u0005[הביאו לפניהם תמרים ורימונים].\u0006 \u0003שקל\u0004 \u0005[לקח]\u0006 \u0003מר זוטרא\u0004 מאותם פירות ו\u0003פתק לקמיה\u0004 \u0005[זרק לפני]\u0006 \u0003רב אשי דסתנא\u0004 \u0005[מנה].\u0006 תמה רב אשי ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003לא סבר לה מר להא דתניא\u0004 \u0005[סבור אדוני את\u0006 הלכה \u0005זו ששנויה\u0006 בברייתא\u0005]\u0006 ש\u0003אין זורקין את האוכלין?\u0004 ענה לו: \u0003ההיא בפת תניא\u0004 \u0005[שנויה],\u0006 ולא במאכל אחר. חזר והקשה לו: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשם שאין זורקין את הפת, כך אין זורקין את האוכלין! אמר ליה\u0004 \u0005[לו]\u0006 מר זוטרא: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 ברייתא\u0005]\u0006 אחרת בה נאמר להיפך: \u0003אף על פי שאין זורקין את הפת, אבל זורקין את האוכלין!\u0004","\u0003אלא\u0004 אלא על כרחך עליך לתרץ ולומר כי \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן שתי הברייתות דנות במקרים שונים, \u0003הא\u0004 \u0005[זה]\u0006 שאמרו שאסור לזרוק שאר דברי מאכל — הרי זה \u0003במידי דממאיס\u0004 \u0005[בדבר שנמאס,\u0006 מתקלקל\u0005]\u0006 בזריקתו, ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמרו שמותר לזרוק שאר דברי מאכל — הרי זה \u0003במידי\u0004 \u0005[בדבר]\u0006 ש\u0003לא ממאיס\u0004 \u0005[נמאס]\u0006 בזריקתו.","בדומה לכך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ממשיכין יין בצנורות לפני חתן ולפני כלה\u0004 לסימן ברכה, \u0003ו\u0004כן \u0003זורקין לפניהם קליות ואגוזים בימות החמה, אבל לא בימות הגשמים,\u0004 שבימות החמה אפשר יהיה להרים את האגוזים ולאכלם אחר כך, ואילו בימות הגשמים ימאסו ויתקלקלו. \u0003אבל לא\u0004 זורקים \u0003גלוסקאות\u0004 (עוגות) \u0003לא בימות החמה ולא בימות הגשמים.\u0004","\u0003אמר רב יהודה:\u0004 מי ש\u0003שכח והכניס אוכלין לתוך פיו בלא ברכה\u0004 — \u0003מסלקן לצד אחד\u0004 בפיו \u0003ומברך.\u0004","ומעירים כי בנושא זה מצויות שלוש ברייתות, \u0003תניא חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]\u0006 שהאוכלים הללו \u0003בולען, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003פולטן, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003מסלקן\u0004 לצד אחד בפיו.","ומסבירים ש\u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכל אחת מהברייתות דנה במקרה אחר. \u0003הא דתניא\u0004 \u0005[זו ששנינו\u0006 בה\u0005]\u0006 \u0003בולען\u0004 מדברת \u0003במשקין,\u0004 שאין דרך אלא לבולעם. \u0003והא דתניא\u0004 \u0005[וזו ששנינו\u0006 בה\u0005]\u0006 \u0003פולטן\u0004 מדברת \u0003במידי\u0004 \u0005[בדבר]\u0006 ש\u0003לא ממאיס\u0004 \u0005[נמאס],\u0006 שאם יוציא אותו מפיו יוכל להכניסו שוב. \u0003והא דתניא\u0004 \u0005[וזו ששנינו\u0006 בה\u0005]\u0006 \u0003מסלקן\u0004 מדובר \u0003במידי דממאיס\u0004 \u0005[בדבר הנמאס]\u0006 שדי שמסלקו לצד."],["ושואלים: \u0003במידי דלא ממאיס נמי, לסלקינהו\u0004 \u0005[בדבר שאינו נמאס גם כן , שיסלקם]\u0006 \u0003לצד אחד וליברך\u0004 \u0005[ויברך]!\u0006 ומשום מה צריך הוא לפולטם? \u0003תרגמא\u0004 \u0005[הסביר אותה]\u0006 \u0003רב יצחק קסקסאה קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוסי בר אבין משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן:\u0004 טעמו של דבר הוא \u0003משום שנאמר \"ימלא פי תהלתך\"\u0004 (תהלים עא, ח), כלומר, שאת תהילת ה' צריך לומר בפה מלא ולא בחצי פה.","\u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרב חסדא: מי שאכל ושתה, ולא ברך, מהו שיחזור ויברך\u0004 ברכה ראשונה? \u0003אמר להו\u0004 \u0005[להם]\u0006 בדרך משל: \u0003מי שאכל שום וריחו נודף, יחזור ויאכל שום אחר כדי שיהא ריחו נודף?!\u0004 כלומר, צריך הוא לברך, וכי אם חטא ולא ברך לפני אכילתו יפטר באכילה בלא ברכה כלל? (תר\"י).","\u0003אמר רבינא: הלכך\u0004 \u0005[משום כך]\u0006 \u0003אפילו גמר סעודתו, יחזור ויברך.\u0004 והביא ראיה לדבר \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בדיני טבילה: \u0003טבל\u0004 הטמא \u0003ועלה\u0004 ממקוה הטהרה, \u0003אומר בעלייתו \"ברוך אשר קדשנו במצותיו וצונו על הטבילה\",\u0004 ומכאן שבדברים מסויימים אפשר לברך גם לאחר מעשה.","את ההשוואה הזאת דוחים: \u0003ולא היא,\u0004 אין לדמות בין המקרים, שכן \u0003התם\u0004 \u0005[שם]\u0006 בטבילה — \u0003מעיקרא גברא לא חזי\u0004 \u0005[מתחילה האיש\u0006 עדיין \u0005אינו ראוי\u0006 לברך, משום טומאתו\u0005],\u0006 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 באכילה — \u0003מעיקרא גברא חזי\u0004 \u0005[מתחילה האיש ראוי\u0006 לברך\u0005],\u0006 \u0003והואיל\u0004 ולא ברך בשעת אכילתו, וסיים כבר את סעודתו, \u0003ואידחי\u0004 \u0005[ונדחה]\u0006 מן הברכה — \u0003אידחי\u0004 \u0005[נדחה]\u0006 לגמרי, ושוב אין לו תקנה לברך.","ואגב דיני יין מביאים עוד, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אספרגוס\u0004 (יין או בכלל משקה חריף שנוהגים לשתותו בבוקר השכם לפני האוכל) — \u0003יפה ללב וטוב לעינים, וכל שכן לבני מעים. ו\u0004בשבחו נאמר כי \u0003הרגיל בו\u0004 — \u0003יפה לכל גופו. ו\u0004אולם צריך להיזהר מפני שתייה מרובה של אספרגוס, שכן \u0003המשתכר הימנו\u0004 — \u0003קשה לכל גופו.\u0004","ודנים בדברים, \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנינו]\u0006 שאספרגוס הריהו \u0003יפה ללב,\u0004 יש להסיק \u0003מכלל\u0004 זה \u0003דבחמרא עסקינן\u0004 \u0005[שב\u0006אספרגוס של \u0005יין אנו עוסקים],\u0006 שידוע שהוא יפה ללב. \u0003וקתני\u0004 \u0005[ושנינו]:\u0006 \u0003וכל שכן\u0004 שאספרגוס זה הריהו יפה \u0003לבני מעים, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ללע\"ט\u0004 (כלומר, ללב, עינים, טחול) — \u0003יפה, לרמ\"ת\u0004 (כלומר, לראש, מעיים, תחתוניות=טחורים) — \u0003קשה,\u0004 הרי שאספרגוס מזיק למעיים!","ועונים: \u0003כי תניא ההיא\u0004 \u0005[כאשר נשנתה אותה\u0006 ברייתא\u0005]\u0006 שהאספרגוס יפה למעיים, הרי זה \u0003ב\u0004יין \u0003מיושן. כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]\u0006 בדיני נדרים, אמר הנודר: \u0003קונם\u0004 (כלומר, אסור עלי כקרבן) \u0003יין שאני שותה,\u0004 משום \u0003שהיין קשה לבני מעים. אמרו לו\u0004 אנשים ששמעוהו אומר כך: \u0003והלא מיושן יפה הוא לבני מעים! ו\u0004אם \u0003שתק\u0004 ולא התווכח בדבר — \u0003אסור\u0004 הוא \u0003ב\u0004שתיית יין \u0003חדש\u0004 מפני שממנו נדר, \u0003ומותר ב\u0004יין \u0003מיושן. שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהיין המיושן יפה למעיים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ששה דברים\u0004 של סגולה \u0003נאמרו באספרגוס: אין שותין אותו אלא כשהוא חי\u0004 ולא נמזגו בו מים, \u0003ומלא, מקבלו\u0004 מן השמש \u0003ב\u0004יד \u0003ימין ושותהו\u0004 כשהוא מוחזק \u0003ב\u0004יד \u0003שמאל. ואין משיחין אחריו, ואין מפסיקין בו\u0004 אלא שותים אותו בבת אחת, \u0003ואין מחזירין אותו אלא למי שנתנו לו ורק אחריו. ואין סומכין אותו אלא במינו,\u0004 כלומר, שאחריו אוכלים מאותו מין שנעשה ממנו משקה זה, כגון תמרים אחר שיכר תמרים וכדומה.","על כך מקשים: \u0003והתניא\u0004 \u0005[והרי שנינו]\u0006 בברייתא ש\u0003אין סומכין אותו אלא בפת!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שסומכים בפת — \u0003בדחמרא\u0004 \u0005[בשל יין],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שסומכים במינו — \u0003בדשכרא\u0004 \u0005[בשל שיכר].\u0006","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]\u0006 שהאספרגוס \u0003ללע\"ט יפה, לרמ\"ת קשה. ו\u0004אולם \u0003תניא אידך: לרמ\"ת יפה, ללע\"ט קשה!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003בדחמרא\u0004 \u0005[בשל יין],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003בדשכרא\u0004 \u0005[בשל שיכר].\u0006","כמו כן אף הסתירה בין הברייתות הבאות, \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003רק אחריו\u0004 — \u0003לוקה\u0004 במחלה. \u0003ו\u0004אולם \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003לא רק אחריו\u0004 — \u0003לוקה\u0004 במחלה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאם לא רק לוקה, הרי זה \u0003בדחמרא\u0004 \u0005[בשל יין],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שלא ירוק, הרי זה \u0003בדשכרא\u0004 \u0005[בשל שיכר].\u0006","\u0003אמר רב אשי: השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמרת\u0004 הלכה זו ששנינו שאם \u0003לא רק אחריו\u0004 הריהו \u0003לוקה,\u0004 למדנו מכאן ש\u0003מימיו,\u0004 כלומר, הרוק המצטבר בפה לאחר שתייתו \u0003נזרקין אפילו\u0004 עומד הוא \u0003בפני המלך.\u0004 משום שיש סכנה בדבר אם יבלע את הרוק.","\u0003אמר ר' ישמעאל בן אלישע: שלשה דברים סח לי סוריאל שר הפנים\u0004 של מעלה: \u0003אל תטול חלוקך בשחרית מיד השמש ותלבש. ואל תטול ידיך ממי שלא נטל ידיו. ואל תחזיר כוס אספרגוס אלא למי שנתנו לך.\u0004 וכל זאת מדוע? — \u0003מפני שתכספית\u0004 \u0005[חבורה של שדים],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003אסתלגנית\u0004 \u0005[חבורה]\u0006 \u0003של מלאכי חבלה מצפין לו לאדם, ואומרים: אימתי יבא אדם לידי אחד מדברים הללו וילכד.\u0004","מעין זה מסופר ש\u0003אמר ר' יהושע בן לוי, שלשה דברים סח לי מלאך המות: אל תטול חלוקך שחרית מיד השמש ותלבש. ואל תטול ידיך ממי שלא נטל ידיו. ואל תעמוד לפני הנשים בשעה שחוזרות מן המת, מפני שאני מרקד ובא לפניהן וחרבי בידי ויש לי רשות לחבל.\u0004","ושואלים: \u0003ואי פגע, מאי תקנתיה\u0004 \u0005[ואם פגש,\u0006 בנשים באותה שעה, \u0005מה תקנתו]?\u0006 ועונים: \u0003לינשוף מדוכתיה\u0004 \u0005[יקפוץ ממקומו]\u0006 \u0003ארבע אמות, אי איכא נהרא\u0004 \u0005[אם יש נהר]\u0006 — \u0003ליעבריה\u0004 \u0005[יעברנו],\u0006 \u0003ואי איכא דרכא אחרינא\u0004 \u0005[ואם יש דרך אחרת]\u0006 — \u0003ליזיל\u0004 \u0005[ילך]\u0006 \u0003בה, ואי איכא גודא\u0004 \u0005[ואם יש קיר]\u0006 — \u0003ליקו אחורא\u0004 \u0005[יעמוד אחריו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003ליהדר אפיה ולימא\u0004 \u0005[יחזיר פניו ויאמר]\u0006 פסוק זה: \u0003\"ויאמר ה' אל השטן יגער ה' בך\u0004 השטן ויגער ה' בך הבוחר בירושלים הלא זה אוד מוצל מאש\u0003\"\u0004 (זכריה ג, ב) \u0003עד דחלפי מיניה\u0004 \u0005[שעוברים,\u0006 מלווי המת, \u0005ממנו].\u0006","\u0003אמר ר' זירא\u0004 שכך \u0003אמר ר' אבהו, ואמרי לה\u0004 \u0005[ו\u0006יש ה\u0005אומרים אותה\u0006 הלכה\u0005]\u0006 כי \u0003במתניתא תנא\u0004 \u0005[בברייתא שנויה]:\u0006 \u0003עשרה דברים נאמרו בכוס של ברכה: טעון הדחה, ושטיפה.\u0004 ושהוא צריך להיות של יין \u0003חי\u0004 (לא מזוג), \u0003ומלא.\u0004 וטעונה הכוס \u0003עיטור, ועיטוף. נוטלו בשתי ידיו, ו\u0004אחר כך \u0003נותנו בימין, ומגביהו מן הקרקע טפח\u0004 לפחות, \u0003ונותן עיניו בו\u0004 כשמברך. \u0003ויש אומרים: אף משגרו\u0004 במתנה \u0003לאנשי ביתו.\u0004","\u0003אמר ר' יוחנן: אנו אין לנו אלא ארבעה\u0004 דברים \u0003בלבד\u0004 שאנו מקיימים מן העשרה שהוזכרו: \u0003הדחה, שטיפה,\u0004 שהיין יהיה \u0003חי, ומלא. תנא\u0004 \u0005[שנה]\u0006 בביאור הדברים: \u0003הדחה\u0004 הריהי \u0003מבפנים, ושטיפה\u0004 — \u0003מבחוץ.\u0004","\u0003אמר ר' יוחנן: כל המברך על כוס מלא\u0004 — \u0003נותנין לו נחלה בלי מצרים,\u0004 ורמז לדבר בכתוב, \u0003ש\u0004כן \u0003נאמר: \"ומלא ברכת ה' ים ודרום ירשה\"\u0004 (דברים לג, כג), שהוא דורש אותי שמי שכוסו מלא — מגיעה אליו ברכת ה' ויורש נחלה מכל צד. ו\u0003ר' יוסי בר חנינא אומר: זוכה ונוחל שני עולמים, העולם הזה והעולם הבא.\u0004","וממשיכים בפירוש עשרת הדברים שנאמרו בכוס של ברכה, \u0003עיטור\u0004 בכוס נהגו בו חכמים באופנים שונים, \u0003רב יהודה\u0004 היה \u0003מעטרהו בתלמידים,\u0004 שבשעת ברכה היה מקיף מסביבו תלמידים לנוי ולכבוד הברכה, ואילו \u0003רב חסדא\u0004 היה \u0003מעטר ליה בנטלי\u0004 \u0005[אותו בכוסות],\u0006 שהיה מקיף את כוס הברכה בכוסות אחרות. \u0003אמר ר' חנן: ו\u0004דוקא \u0003ב\u0004יין \u0003חי. אמר רב ששת: ובברכת הארץ.\u0004","אף ב\u0003עיטוף\u0004 נהגו חכמים באופנים שונים, שכן \u0003רב פפא\u0004 היה \u0003מעטף ויתיב\u0004 \u0005[מתעטף\u0006 בטליתו \u0005ויושב].\u0006 ואילו \u0003רב אסי פריס סודרא על רישיה\u0004 \u0005[היה פורש סודר על ראשו]\u0006 שהוא לבוש של כבוד.","על מה שאמרו שאת כוס הברכה \u0003נוטלו בשתי ידיו, אמר ר' חיננא בר פפא: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 שיש להביא ממנו ראיה כדרך רמז לדבר זה? — שכן נאמר: \u0003\"שאו ידיכם קדש וברכו את ה'\"\u0004 (תהלים קלד, ב).","\u0003ו\u0004על מה שאמרו שלאחר נשיאת שתי הידים \u0003נותנו לימין, אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן:\u0004 כבר \u0003ראשונים שאלו:\u0004 יד \u0003שמאל מהו שתסייע לימין\u0004 בהחזקת הכוס? \u0003אמר רב אשי: הואיל וראשונים איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 שאלה זו\u0005],\u0006 \u0003ולא איפשט להו\u0004 \u0005[נפטרה להם],\u0006"],["\u0003אנן נעבד לחומרא\u0004 \u0005[אנחנו נעשה לחומרה]\u0006 ולא נסייע.","על מה שאמרו \u0003ומגביהו מן הקרקע טפח, אמר רב אחא בר יעקב: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 שיש להביא ממנו ראיה כדרך רמז לדבר זה — שכן נאמר \u0003\"כוס ישועות אשא ובשם ה' אקרא\"\u0004 (תהלים קטז, יג).","\u0003ו\u0004מה שאמרו ש\u0003נותן עיניו בו\u0004 — \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ניסח דעתיה מיניה\u0004 \u0005[יסיח דעתו ממנו].\u0006","\u0003ו\u0004מה שאמרו ש\u0003משגרו לאנשי ביתו במתנה\u0004 — \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003תתברך דביתהו\u0004 \u0005[אשתו].\u0006","ולענין זה מסופר: \u0003עולא אקלע לבי\u0004 \u0005[נקלע,\u0006 הזדמן \u0005לבית]\u0006 \u0003רב נחמן.\u0004 בסעודה \u0003כריך ריפתא, בריך ברכת מזונא, יהב ליה כסא דברכתא\u0004 \u0005[אכל לחם, ברך ברכת המזון, נתן את כוס הברכה]\u0006 \u0003לרב נחמן. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: לישדר מר כסא דברכתא\u0004 \u0005[ישלח אדוני כוס ברכה]\u0006 \u0003לילתא\u0004 אשת רב נחמן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא: אין צורך בדבר, שהרי \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: אין פרי בטנה של אשה מתברך אלא מפרי בטנו של איש, ש\u0004כן \u0003נאמר \"\u0004ואהבך וברכך והרבך \u0003וברך פרי בטנך\"\u0004 (דברים ז, יג), ויש לדייק בלשון הכתוב: \u0003\"\u0004וברך \u0003פרי בטנה\" לא נאמר, אלא\u0004 \"וברך \u0003פרי בטנך\",\u0004 ודי שנתן את הכוס לרב נחמן וממילא תתברך אשתו בבנים.","ו\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003ר' נתן אומר: מנין שאין פרי בטנה של אשה מתברך אלא מפרי בטנו של איש\u0004 — \u0003שנאמר: \"וברך פרי בטנך\", \"פרי בטנה\" לא נאמר, אלא \"פרי בטנך\".\u0004","ומסופר, כי \u0003אדהכי\u0004 \u0005[עד שכך,\u0006 בתוך כך\u0005]\u0006 \u0003שמעה ילתא\u0004 את הדברים הללו, והיא היתה בת ראש הגולה והיתה רגילה שינהגו בה כבוד, \u0003קמה בזיהרא\u0004 \u0005[בחמתה],\u0006 \u0003ועלתה לבי חמרא, ותברא ארבע מאה דני דחמרא\u0004 \u0005[ונכנסה לבית היין, ושברה ארבע מאות חביות יין].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אחר כך \u0003רב נחמן\u0004 לעולא: \u0003נשדר\u0004 \u0005[ישלח]\u0006 \u0003לה מר כסא אחרינא\u0004 \u0005[אדוני כוס אחרת],\u0006 \u0003שלח לה\u0004 עולא לילתא: \u0003כל האי נבגא, דברכתא\u0004 \u0005[החבית הזו, של ברכה]\u0006 \u0003היא,\u0004 ואם לא שתתה מכוס הברכה עצמה, יכולה היא לשתות יין מן החבית הזו, והרי זו כשתיית כוס של ברכה. \u0003שלחה ליה\u0004 \u0005[לו]\u0006 בתשובה: \u0003ממהדורי\u0004 \u0005[מן המחזירים\u0006 בעיירות\u0005],\u0006 רמז לעולא שהיה מסתובב בין בבל לארץ ישראל — יוצאים תמיד \u0003מילי\u0004 \u0005[דברים],\u0006 \u0003ומסמרטוטי\u0004 \u0005[ומן הסמרטוטים]\u0006 — מתרבים \u0003כלמי\u0004 \u0005[כינים].\u0006","\u0003אמר רב אסי: אין מסיחין על כוס של ברכה\u0004 משעה שאחז את הכוס בידיו עד שישתהו. \u0003ו\u0004עוד \u0003אמר רב אסי: אין מברכין על כוס של פורענות.\u0004 ומבררים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003\"כוס של פורענות\"? אמר רב נחמן בר יצחק: כוס שני. תניא נמי הכי\u0004 \u0005[שנינו\u0006 בברייתא \u0005גם כן כך]:\u0006 \u0003השותה כפלים לא יברך, משום שנאמר \"הכון לקראת אלהיך ישראל\"\u0004 (עמוס ד, יב), שצריך אדם להכין עצמו היטב לקראת עמידתו לפני בוראו, \u0003והאי\u0004 \u0005[ו\u0006אילו \u0005זה]\u0006 ששתה שתי כוסות הוא \u0003לא מתקן\u0004 \u0005[מתוקן],\u0006 ששתיית כוסות יין במספר זוגי מסוכנת, מפני המזיקים.","ולסיכום הלכות ברכה מביאים מה ש\u0003אמר ר' אבהו, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שדבר זה \u0003במתניתא תנא\u0004 \u0005[בברייתא שנוי]:\u0006 \u0003האוכל ו\u0004באותה עת הוא \u0003מהלך\u0004 — \u0003מברך\u0004 כשהוא \u0003מעומד, וכשהוא אוכל מעומד\u0004 — \u0003מברך\u0004 כשהוא \u0003מיושב, וכשהוא מיסב\u0004 על המיטה \u0003ואוכל\u0004 — הריהו מזדקף ו\u0003יושב ומברך.\u0004 אולם דברים אלה לא נתקבלו, \u0003והלכתא\u0004 \u0005[וההלכה]\u0006 היא: \u0003בכולהו\u0004 \u0005[בכולם]\u0006 — \u0003יושב ומברך.\u0004","\u0003הדרן עלך שלשה שאכלו\u0004","\u0003אלו דברים ש\u0004יש בהם מחלוקת \u0003בין בית שמאי ובין בית הלל ב\u0004הלכות \u0003סעודה:\u0004 מחלוקת אחת היא בענין סדר הברכות בקידוש, ש\u0003בית שמאי אומרים\u0004 כי כאשר עושה אדם קידוש על יין הריהו \u0003מברך\u0004 בתחילה \u0003על היום, ואחר כך מברך על היין. ובית הלל אומרים: מברך\u0004 תחילה \u0003על היין ואחר כך מברך על היום.\u0004","וכן נחלקו לגבי שתיית היין שלפני הסעודה, ש\u0003בית שמאי אומרים\u0004 שבתחילה \u0003נוטלין\u0004 את ה\u0003ידים ו\u0004רק \u0003אחר כך מוזגין את הכוס. ובית הלל אומרים\u0004 שקודם \u0003מוזגין את הכוס ו\u0004רק \u0003אחר כך נוטלין לידים.\u0004 והדבר תלוי במחלוקת בדיני טומאה וטהרה כפי שיבואר בגמרא להלן.","כמו כן בקשר לדיני טומאה \u0003בית שמאי אומרים\u0004 שאדם לאחר שהיה \u0003מקנח ידיו במפה\u0004 (מגבת) מנטילת ידים, הריהו \u0003מניחה\u0004 את המגבת \u0003על השולחן, ובית הלל אומרים:\u0004 הריהו מניח אותה \u0003על הכסת\u0004 אשר עליה הוא יושב.","וכמו כן \u0003בית שמאי אומרים\u0004 שקודם \u0003מכבדין את הבית,\u0004 כלומר, מנקים את מקום האכילה מן הפירורים המפוזרים בו \u0003ו\u0004רק \u0003אחר כך נוטלין לידים\u0004 במים אחרונים שלאחר המזון. \u0003ובית הלל אומרים\u0004 שתחילה \u0003נוטלין לידים ואחר כך מכבדין את הבית.\u0004 וכשם שנחלקו בסדר הדברים בקידוש כך נחלקו לגבי הבדלה.","שאם האריכו בסעודה עד ליציאת השבת, הרי בכגון זה \u0003בית שמאי אומרים\u0004 שבתחילה יש לברך על ה\u0003נר ו\u0004אחר כך על ה\u0003מזון\u0004 (ברכת המזון), לאחריה \u0003בשמים ו\u0004לבסוף ברכת \u0003הבדלה. ובית הלל אומרים\u0004 שהסדר הוא כזה: \u0003נר ובשמים, מזון והבדלה.\u0004 ואף בברכת הנר עצמה נחלקו.","\u0003בית שמאי אומרים\u0004 שנוסח הברכה הוא \u0003\"שברא מאור האש\", ובית הלל אומרים\u0004 שנוסח הברכה הוא \u0003\"בורא מאורי האש\".\u0004","והלכה פסוקה בענין זה: \u0003אין מברכים לא על הנר ולא על הבשמים של גוים, ולא על הנר ולא על הבשמים של,\u0004 כלומר, שנועדו לכבוד ה\u0003מתים, ולא על הנר ולא על הבשמים של עבודה זרה. ו\u0004עוד כלל קבעו בברכת הנר: \u0003אין מברכין על הנר עד שיאותו\u0004 (יהנו וישתמשו) \u0003לאורו.\u0004","מחלוקת אחרת היא בדבר \u0003מי שאכל, ושכח ולא בירך.\u0004 ש\u0003בית שמאי אומרים\u0004 ש\u0003יחזור למקומו ויברך, ובית הלל אומרים\u0004 שאין צורך בכך \u0003ו\u0004לדעתם \u0003יברך במקום ש\u0004בו \u0003נזכר.\u0004 ואולם לכל הדעות אין אפשרות לברך אלא לאחר זמן מוגבל מסיום האכילה. \u0003ועד מתי מברך?\u0004 — \u0003עד שיתעכל המזון שבמעיו.\u0004","מחלוקת אחרת היא אם \u0003בא להן\u0004 למסובים \u0003יין\u0004 רק \u0003אחר המזון, אם אין שם אלא אותו כוס\u0004 יין בלבד, \u0003בית שמאי אומרים\u0004 שבתחילה \u0003מברך על היין ו\u0004רק \u0003אחר כך מברך על המזון. ובית הלל אומרים\u0004 שבתחילה \u0003מברך על המזון ו\u0004רק \u0003אחר כך מברך על היין.\u0004","\u0003ו\u0004עוד אמרו: \u0003עונין \"אמן\" אחר ישראל המברך\u0004 אף על פי שלא שמעו את כל הברכה, \u0003ו\u0004אולם \u0003אין עונין \"אמן\" אחר כותי\u0004 (שומרוני) \u0003המברך, עד שישמע\u0004 את \u0003כל הברכה כולה.\u0004 שיתכן שבתחלת הברכה הכניס השומרוני דבר שאינו על פי אמונת ישראל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: אלו \u0003דברים ש\u0004יש בהם מחלוקת \u0003בין בית שמאי ובית הלל ב\u0004הלכות \u0003סעודה:\u0004 בענין הקדמת ברכת היום או היין בקידוש, \u0003בית שמאי אומרים\u0004 ש\u0003מברך על היום ואחר כך מברך על היין.\u0004 וטעם הדבר: לפי \u0003שהיום גורם ליין שיבא,\u0004 שאילו לא היה זה יום השבת לא היה שותה יין כעת. ועוד נימוק אמרו בית שמאי: הואיל \u0003וכבר קדש היום ועדיין יין לא בא,\u0004 ומאחר שקדמה קדושת השבת, יש להקדים בהזכרת השבת.","\u0003ובית הלל אומרים: מברך על היין ואחר כך מברך על היום.\u0004 וטעם הדבר: \u0003ש\u0004כן \u0003היין גורם לקדושה שתאמר,\u0004 שאם אין יין אי אפשר לעשות קידוש. \u0003דבר\u0004 (טעם) \u0003אחר: ברכת היין\u0004 היא ברכה \u0003תדירה, וברכת היום אינה תדירה.\u0004 וכלל בידינו שאם עומדים בפנינו שני דברים, דבר \u0003תדיר ושאינו תדיר\u0004 — \u0003תדיר קודם,\u0004 שיש להקדימו לחבירו. ומעירים: \u0003והלכה\u0004 בענין זה \u0003כדברי בית הלל.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהו],\u0006 משום מה צריכים בית הלל לומר עוד \u0003דבר אחר?\u0004 ועונים: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003התם תרתי והכא חדא\u0004 \u0005[שם,\u0006 בדברי בית שמאי, \u0005שנים,\u0006 הם הנימוקים \u0005וכאן\u0006 רק \u0005אחד],\u0006 על כן אמרו \u0003הכא נמי תרתי נינהו\u0004 \u0005[כאן גם כן שנים הם],\u0006 והנימוק השני הוא: \u0003ברכת היין תדירה וברכת היום אינה תדירה,\u0004 ו\u0003תדיר ושאינו תדיר\u0004 — \u0003תדיר קודם.\u0004","שנינו בתוספתא: ש\u0003הלכה כדברי בית הלל.\u0004 ושואלים: \u0003פשיטא, דהא נפקא\u0004 \u0005[שהרי יצאה]\u0006 \u0003בת קול\u0004 ואמרה שהלכה בבית הלל בכל מקרה, ומה צורך יש להודיענו כאן שהלכה כדבריהם?","ומתרצים שני תירוצים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שברייתא זו נשנתה \u0003קודם בת קול,\u0004 שעדיין לא הוכרעה ההלכה בדרך כלל. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שאכן נשנתה תוספתא זו \u0003לאחר בת קול,\u0004"],["\u0003ו\u0004אולם שיטת \u0003ר' יהושע היא\u0004 ש\u0003אמר\u0004 בענין תנורו של עכנאי (ב\"מ נט,ב) לאחר שיצאה בת קול ואמרה שהלכה כר' אליעזר שנחלק עמו בענין זה: \u0003אין משגיחין בבת קול,\u0004 וכשם שלא השגיח בבת קול להכריע במחלוקת שלו עם ר' אליעזר, כך אין משגיחים בבת קול גם בהכרעה לדברי בית הלל.","על עצם הדברים שאמרו כאן שואלים \u0003וסברי\u0004 \u0005[ו\u0006כי \u0005סבורים]\u0006 \u0003בית שמאי\u0004 ש\u0003ברכת היום עדיפא\u0004 \u0005[עדיפה]\u0006 ויש להקדימה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנכנס לביתו במוצאי שבת, מברך על היין ועל המאור ועל הבשמים, ואחר כך אומר הבדלה. ואם אין לו אלא כוס אחד\u0004 במשך יום השבת \u0003מניחו\u0004 לאותו כוס \u0003לאחר המזון\u0004 בסעודה האחרונה של שבת \u0003ומשלשלן כולן,\u0004 את כל הברכות, גם ברכת המזון גם ברכות ההבדלה והיין, \u0003לאחריו.\u0004 הרי שבהבדלה מקדימים את היין לפני עיקר הדברים שהוא ההבדלה!","על כך תוהים: \u0003והא, ממאי?\u0004 \u0005[וזו,\u0006 הברייתא, \u0005ממה]\u0006 שלדעת \u0003בית שמאי היא? דלמא\u0004 דעת \u0003בית הלל היא,\u0004 ואין להקשות מברייתא עלומת שם על בית שמאי?!","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כך, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בתחילה \u0003מאור ו\u0004רק \u0003אחר כך בשמים, ומאן שמעת ליה דאית ליה האי סברא\u0004 \u0005[מי שמעת אותו שיש לו,\u0006 שהוא מקבל, \u0005סברה זו]\u0006 — \u0003בית שמאי, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]\u0006 ש\u0003אמר ר' יהודה: לא נחלקו בית שמאי ובית הלל על\u0004 ברכת \u0003המזון שבתחלה ועל\u0004 ה\u0003הבדלה שהיא בסוף,\u0004 אלא \u0003על מה נחלקו\u0004 — \u0003על המאור ועל הבשמים,\u0004 איזה מהם יש להקדים באמצע, האם את המאור או את הבשמים. ש\u0003בית שמאי אומרים\u0004 שקודם מברך על ה\u0003מאור ו\u0004רק \u0003אחר כך על הבשמים, ובית הלל אומרים\u0004 שקודם מברך על ה\u0003בשמים ו\u0004רק \u0003אחר כך\u0004 על ה\u0003מאור.\u0004 הרי שברייתא זו ששנינו בה שמברך על היין ואחריו על המאור, הריהי בוודאי כשיטת בית שמאי.","ושוב מקשים: \u0003וממאי\u0004 \u0005[וממה,\u0006 מנין\u0005]\u0006 שהברייתא של \u0003בית שמאי היא ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003ר' יהודה, דילמא\u0004 \u0005[שמא]\u0006 שיטת \u0003בית הלל היא ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003ר' מאיר?!\u0004","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, \u0003דקתני הכא במתניתין\u0004 \u0005[ש\u0006כן \u0005שנינו כאן במשנתנו],\u0006 שהיא, ככל סתם משנה, כר' מאיר, ש\u0003בית שמאי אומרים\u0004 שסדר הברכות הוא: בתחילה על ה\u0003נר\u0004 ואחריו על ה\u0003מזון\u0004 ואחר כך על ה\u0003בשמים והבדלה, ובית הלל אומרים\u0004 שהסדר הוא: \u0003נר ובשמים מזון והבדלה, והתם\u0004 \u0005[ושם]\u0006 \u0003בברייתא קתני\u0004 \u0005[שנינו]\u0006 ש\u0003אם אין לו אלא כוס\u0004 יין \u0003אחד,\u0004 הריהו \u0003מניחו לאחר המזון, ומשלשלן\u0004 לברכות \u0003כולן\u0004 ואומרן \u0003לאחריו,\u0004 והרי ששיטת הברייתא היא שהברכות כולן לאחר המזון. ומאחר שדברי הברייתא והמשנה אינם זהים, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי הברייתא שיטת \u0003בית שמאי היא ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003ר' יהודה.\u0004","ואולם לאחר שהוכח כי הברייתא מכוונת לדעת בית שמאי כפי שמסרה ר' יהודה, \u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 הסתירה בשיטת בית שמאי בברייתא ובתוספתא. ועונים: \u0003קא סברי\u0004 \u0005[סבורים הם]\u0006 \u0003בית שמאי\u0004 כי \u0003שאני עיולי יומא מאפוקי יומא\u0004 \u0005[שונה כניסת היום,\u0006 השבת או החג, \u0005מיציאת היום].\u0006 שכן \u0003עיולי יומא\u0004 \u0005[כניסת היום]\u0006 כל \u0003כמה דמקדמינן ליה, עדיף\u0004 \u0005[שמקדימים אותה, עדיפה],\u0006 ואילו \u0003אפוקי יומא\u0004 \u0005[יציאת היום],\u0006 כל \u0003כמה דמאחרינן ליה, עדיף\u0004 \u0005[שמאחרים אותה, עדיפה],\u0006 \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא להוי עלן\u0004 \u0005[יהא עלינו]\u0006 יום השבת \u0003כמשוי,\u0004 ולכן אף שהקדימו בית שמאי את הקידוש לברכת היין, מודים הם שיש להבדיל אחר ברכת היין.","בתוך הדברים דנו בשיטת בית שמאי בברכת המזון על כוס יין. ושואלים: \u0003וסברי\u0004 \u0005[וכי סבורים]\u0006 \u0003בית שמאי\u0004 ש\u0003ברכת המזון טעונה כוס? והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 אם \u0003בא להם\u0004 למסובים בסעודה \u0003יין לאחר המזון, אם אין שם אלא אותו כוס, בית שמאי אומרים\u0004 ש\u0003מברך\u0004 בתחילה \u0003על היין ואחר כך מברך על המזון, מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ש\u0003מברך עילויה ושתי ליה\u0004 \u0005[עליו ושותה אותו]?\u0006 ונמצא שברכת המזון מברך ללא יין! ודוחים: \u0003לא,\u0004 מדובר כאן באופן ש\u0003מברך עילויה ומנח ליה\u0004 \u0005[עליו ומניח אותו],\u0006 ושותה ממנו לאחר ברכת המזון.","ומקשים: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]\u0006 ש\u0003המברך צריך שיטעום!\u0004 ומשיבים: אמנם מדובר כאן באופן \u0003דטעים ליה\u0004 \u0005[ש\u0006הוא \u0005טעם אותו].\u0006 ומקשים: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]\u0006 שאפילו אם רק \u0003טעמו\u0004 לכוס היין — \u0003פגמו\u0004 מלהיות ראויה לכוס של ברכה! ומשיבים שלא טעם מן היין בשתיה, אלא \u0003דטעים ליה בידיה\u0004 \u0005[שטעם אותה בידו]\u0006 או ששפך מעט מן היין לכלי אחר ושתה ממנו.","ומקשים: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]\u0006 ש\u0003כוס של ברכה צריך\u0004 שיהיה בו \u0003שעור, והא קא פחית ליה משיעוריה\u0004 \u0005[והרי הוא פוחת אותו משעורו]!\u0006 ומשיבים: \u0003דנפיש ליה טפי משיעוריה\u0004 \u0005[שמרובה בו יותר משעורו].\u0006","על כך תמהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אם אין שם אלא אותו כוס קתני\u0004 \u0005[שנינו]\u0006 במפורש, ואם מרובה היין מן השיעור, הרי כאן שתי כוסות! ומשיבים: \u0003תרי לא הוי ומחד נפיש\u0004 \u0005[שתים\u0006 אכן \u0005אינם ו\u0006אולם \u0005מאחד\u0006 הוא \u0005מרובה].\u0006","ומקשים עוד, \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא\u0004 בברייתא: \u0003בית שמאי אומרים\u0004 ש\u0003מברך על היין ושותהו ואחר כך מברך ברכת המזון,\u0004 וברור מכאן שלדעת בית שמאי אין צורך ביין לברכת המזון! \u0003אלא\u0004 בהכרח יש לומר כי \u0003תרי תנאי, ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003בית שמאי,\u0004 ששנים מתלמידי בית שמאי נחלקו בדעותיהם בענין זה, והמקורות השונים מבטאים את שתי הדעות.","שנינו במשנה שנחלקו בית שמאי ובית הלל אם יש להקדים נטילת ידים או מזיגת הכוס. ש\u0003בית שמאי אומרים\u0004 שבתחילה נוטלים את הידים ואחר כך מוזגים את הכוס, ובית הלל אומרים שבתחילה מוזגים את הכוס ואחר כך נוטלים את הידים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא בתוספת ביאור, \u0003בית שמאי אומרים:\u0004 בתחילה \u0003נוטלין לידים ואחר כך מוזגין את הכוס, שאם אתה אומר\u0004 ש\u0003מוזגין את הכוס תחלה\u0004 לפני נטילת ידים, הרי ידיו נשארות טמאות, שעל פי \u0003גזרה\u0004 שגזרו חכמים, ידים שלא רחצו אותן הן שניות לטומאה, כאילו נגעו בדבר שנטמא בשרץ, ואז יש לחשוש \u0003שמא יטמאו משקין שאחורי הכוס\u0004 שרגיל הוא שאחורי הכוס רטובים מנוזלים שנטפו מהכוס, ומשקין אלה שייטמאו \u0003מחמת ידיו, ויחזרו\u0004 המשקים הללו \u0003ו\u0004הם \u0003יטמאו את הכוס.\u0004 ולכן אמרו בית שמאי שיש ליטול ידים תחילה, כדי למנוע אפשרות כעין זו.","ושואלים: אם אמנם יש לחשוש לידים טמאות שעל ידן תיטמא הכוס, מדוע יש להזכיר את המשקין שאחורי הכוס? \u0003וליטמו\u0004 \u0005[ושיטמאו]\u0006 ה\u0003ידים\u0004 את ה\u0003כוס\u0004 במישרין!","ומשיבים: \u0003ידים שניות הן\u0004 לטומאה, \u0003ו\u0004כלל בידינו: ש\u0003אין שני עושה\u0004 (מטמא) \u0003שלישי בחולין\u0004 (אך לא בתרומה או בקדשים) \u0003אלא על ידי משקין\u0004 שנגעו בשני ואחר כך נגעו בשלישי שכאשר הם נוגעים בטומאה (ואפילו בשני לטומאה) הריהם נעשים ראשונים לטומאה, ומטמאים את הנוגע בהם.","\u0003ו\u0004אילו \u0003בית הלל אומרים\u0004 ש\u0003מוזגין\u0004 בתחילה \u0003את הכוס ו\u0004רק \u0003אחר כך נוטלין לידים.\u0004 וסברתם: \u0003שאם אתה אומר\u0004 ש\u0003נוטלין לידים תחלה\u0004 הרי הידים לחות מן המים שמחוץ לכוס, ויתכן ש\u0003יטמאו\u0004 ה\u0003משקין\u0004 הללו \u0003שבידים מחמת הכוס,\u0004 העלולה להיות טמאה, \u0003ו\u0004אותם משקים \u0003יחזרו ויטמאו את הידים.\u0004","ושואלים: \u0003וניטמי\u0004 \u0005[ושיטמא]\u0006 ה\u0003כוס\u0004 את ה\u0003ידים\u0004 במישרין, בלא משקים! ומשיבים, שעל פי הכלל בהלכות טומאה ש\u0003אין כלי מטמא אדם,\u0004 ולא יתכן אם שתטמא הכוס את ידי האדם.","ושואלים: ואם אחורי הכוס טמאים הם, אם כן \u0003וניטמי\u0004 \u0005[ושיטמאו]\u0006 את ה\u0003משקין שבתוכו!!\u0004 ומשיבים: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בכלי שנטמאו אחוריו\u0004 בלבד \u0003במשקין עסקינן\u0004 \u0005[עוסקים אנו]\u0006 ולא בטומאה שמדין תורה, שאז \u0003תוכו טהור\u0004 אף ש\u0003גבו\u0004 (חלקו החיצוני) \u0003טמא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כלי שנטמאו אחוריו במשקין\u0004 רק \u0003אחוריו טמאים\u0004"],["ואילו \u0003תוכו ואוגנו\u0004 (שפת הכלי היוצאת כלפי חוץ) \u0003ו\u0004כן \u0003אזנו\u0004 או \u0003ידיו\u0004 (הידית שלו) \u0003טהורין\u0004 הם. ואולם כאשר \u0003נטמא תוכו\u0004 של הכלי — \u0003נטמא כולו.\u0004","גזירות בית הלל ובית שמאי שונות אמנם זו מזו, ואולם שתיהן מתבססות על אפשרויות קיימות, ועל שיקולים ששני הצדדים בעצם מסכימים להם, ולכן מבררים: \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חולקים]?\u0006 מהו שורש מחלוקתם?","ומסבירים: \u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 כי \u0003אסור להשתמש בכלי שנטמאו אחוריו במשקין,\u0004 ואיסור זה מקורו ב\u0003גזרה\u0004 שגזרו חכמים וחשש \u0003משום ניצוצות\u0004 (טיפות נוזלים היוצאות מתוך הכלי אל אחוריו), שמאחר ונטמאים ניצוצות אלה באחורי הכלי, הם מוסיפים ומטמאים את הידים הבאות עמם במגע. \u0003וליכא למגזר\u0004 \u0005[ואין לגזור]\u0006 משום החשש שהביעו בית הלל \u0003שמא יטמאו המשקין שבידים\u0004 הלחות \u0003ב\u0004אחורי ה\u0003כוס,\u0004 שהרי אסור השימוש בכלי כזה.","\u0003ו\u0004אילו \u0003בית הלל סברי\u0004 \u0005[סבורים]\u0006 כי \u0003מותר להשתמש בכלי שנטמאו אחוריו במשקין,\u0004 כי הם \u0003אמרי\u0004 \u0005[אומרים]\u0006 \u0003ניצוצות לא שכיחי\u0004 \u0005[אינם מצויים]\u0006 ואין לגזור בדבר שאינו מצוי, \u0003ו\u0004מפני שמותר להשתמש בכלי זה \u0003איכא למיחש\u0004 \u0005[יש לחשוש]\u0006 \u0003שמא יטמאו\u0004 ה\u0003משקין שבידים\u0004 הרטובות מנטילת ידים \u0003מחמת הכוס.\u0004","\u0003דבר אחר\u0004 אמרו בית הלל: מפני הכלל \u0003תכף לנטילת ידים\u0004 צריכה להיות ה\u0003סעודה,\u0004 עדיף שימזגו את הכוס קודם ואחר כך יטלו את הידים, ומיד יגשו לסעודה.","ושואלים \u0003מאי\u0004 \u0005[מהי]\u0006 הסיבה שבית הלל הוסיפו עוד \u0003\"דבר אחר\",\u0004 כלומר, נימוק נוסף? ומשיבים: \u0003הכי קאמרי להו\u0004 \u0005[כך אמרו להם]\u0006 \u0003בית הלל לבית שמאי:\u0004 אף \u0003לדידכו דאמריתו\u0004 \u0005[לדעתכם שאתם אומרים]\u0006 ש\u0003אסור להשתמש בכלי שאחוריו טמאין\u0004 משום \u0003דגזרינן\u0004 \u0005[שאנו גוזרים]\u0006 \u0003משום\u0004 חשש \u0003ניצוצות, אפילו הכי\u0004 \u0005[כך]\u0006 \u0003הא עדיפא\u0004 \u0005[זו\u0006 שהצענו \u0005עדיפה]\u0006 על הצעתכם, שעל פי שיטתנו אפשר ש\u0003תיכף\u0004 אחר \u0003נטילת ידים\u0004 תהא ה\u0003סעודה.\u0004","שנינו במשנה שנחלקו בית הלל ובית שמאי בענין המקום שעליו יש לשים את המפה שנגבו בה את הידים. ש\u0003בית שמאי אומרים\u0004 שאחר ש\u0003מקנח\u0004 ידו במגבת הריהו מניחה על השולחן, ובית הלל אומרים שמניחה על הכסת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא ביתר ביאור: \u0003בית שמאי אומרים:\u0004 לאחר ש\u0003מקנח ידיו במפה\u0004 (מגבת) הריהו \u0003מניחה על השלחן.\u0004 משום \u0003שאם אתה אומר\u0004 שמניחה \u0003על הכסת\u0004 יש לחשוש ל\u0003גזרה\u0004 שגזרו חכמים \u0003שמא יטמאו\u0004 ה\u0003משקין שבמפה\u0004 הרטובה מנטילת ידים \u0003מחמת הכסת, ויחזרו\u0004 משקים אלו \u0003ויטמאו את הידים\u0004 של הנוגעים מדי פעם במגבת.","ושואלים: \u0003ונטמייה\u0004 \u0005[ושתטמא אותה]\u0006 ה\u0003כסת\u0004 את ה\u0003מפה\u0004 אף בלא משקים! ומשיבים: כלל הוא ש\u0003אין כלי מטמא כלי\u0004 אחר.","ושואלים: \u0003ונטמייה\u0004 \u0005[ושתטמא אותו]\u0006 ה\u0003כסת לגברא גופיה\u0004 \u0005[את האדם עצמו]!\u0006 ומשיבים: גם דבר זה לא יתכן, שכן כלל הוא ש\u0003אין כלי מטמא אדם.\u0004","\u0003ובית הלל אומרים\u0004 שמניחה את המפה דווקא על \u0003הכסת, ש\u0004כן \u0003אם אתה אומר\u0004 שיניחנה \u0003על השלחן,\u0004 יש לחשוש ל\u0003גזרה שמא יטמאו\u0004 ה\u0003משקין שבמפה מחמת השולחן ויחזרו\u0004 משקים אלה \u0003ויטמאו את האוכלין\u0004 המונחים על השולחן.","ושואלים: \u0003ולטמא\u0004 \u0005[ושיטמא]\u0006 ה\u0003שלחן\u0004 במישרין את ה\u0003אוכלין שבתוכו!\u0004 ומסבירים: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בשלחן\u0004 שהוא \u0003שני\u0004 לטומאה בלבד \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ואין שני\u0004 לטומאה מטמא הלאה ו\u0003עושה שלישי\u0004 לטומאה \u0003בחולין אלא על ידי משקין\u0004 שנגעו בשני ומדברי סופרים נעשו בכך ראשון לטומאה ומשנגעו באוכלין עשאום שני לטומאה.","אף כאן שואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 מהו יסוד מחלוקתם? ומשיבים: יסוד הדבר הוא ש\u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 ש\u0003אסור\u0004 בכלל \u0003להשתמש\u0004 לצורך אכילה \u0003בשלחן\u0004 שהוא \u0003שני\u0004 לטומאה, \u0003גזרה משום אוכלי תרומה,\u0004 שהכהנים האוכלים תרומה עלולים לשכוח ולאכול שם ושולחן זה יכול לטמא את התרומה על ידי מגע במישרין, ולכן גזרו שלא ישתמשו בו אף לחולין.","\u0003ובית הלל סברי\u0004 \u0005[סבורים]\u0006 ש\u0003מותר להשתמש בשלחן\u0004 שהוא \u0003שני\u0004 לטומאה, ואין לחשוש, שכן \u0003אוכלי תרומה זריזין הם,\u0004 ובודאי ישימו לב על איזה שולחן הם אוכלים.","\u0003דבר אחר,\u0004 נימוק נוסף אמרו בית הלל: שבכלל \u0003אין נטילת ידים לחולין מן התורה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 הסיבה שבית הלל הוסיפו \u0003דבר אחר?\u0004 ומשיבים: \u0003הכי קאמרי להו\u0004 \u0005[כך אמרו להם]\u0006 \u0003בית הלל לבית שמאי: וכי תימרו מאי שנא גבי\u0004 \u0005[ואם תאמרו, מה שונה אצל,\u0006 בענין\u0005]\u0006 \u0003אוכלין דחיישינן\u0004 \u0005[שאנו חוששים]\u0006 להם שלא יטמאו על ידי המפה שעל השולחן \u0003ומאי שנא גבי\u0004 \u0005[ומה שונה אצל]\u0006 \u0003ידים דלא חיישינן\u0004 \u0005[שאין אנו חוששים]\u0006 שתיטמאנה מחמת המפה המונחת על הכסת? ואומרים \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003הא עדיפא\u0004 \u0005[זו עדיפה],\u0006 שהרי \u0003אין נטילת ידים לחולין מן התורה\u0004 כלל, ו\u0003מוטב שיטמאו\u0004 ה\u0003ידים דלית להו\u0004 \u0005[שאין להן]\u0006 \u0003עיקר מדאורייתא\u0004 \u0005[מן התורה]\u0006 ויאכל בידים השניות לטומאה, \u0003ואל יטמאו\u0004 ה\u0003אוכלים דאית להו\u0004 \u0005[שיש להם]\u0006 שיש לטומאתם \u0003עיקר מדאורייתא\u0004 \u0005[מן התורה].\u0006","שנינו במשנה שנחלקו בית הלל ובית שמאי אם יש להקדים את ניקוי מקום האוכל או את רחיצת הידים לאחר הסעודה ש\u0003בית שמאי אומרים\u0004 שקודם \u0003מכבדין\u0004 את הבית ואחר כך נוטלים את הידים במים אחרונים, ובית הלל אומרים שקודם נוטלים את הידים ורק אחר כך מכבדים את הבית.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא מחלוקת זו ביתר ביאור: \u0003בית שמאי אומרים\u0004 שקודם \u0003מכבדין את הבית ו\u0004רק \u0003אחר כך נוטלין לידים, ש\u0004כן \u0003אם אתה אומר\u0004 כן ש\u0003נוטלים את הידים תחלה\u0004 (קודם), \u0003נמצא אתה מפסיד את האוכלין,\u0004 שהמים ינתזו על פירורי האוכל שנשארו ויקלקלו אותם. \u0003אבל נטילת ידים ל\u0004שיטת \u0003בית שמאי\u0004 שהם יהיו \u0003תחלה לא סבירא להו\u0004 \u0005[אינם סבורים].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003משום\u0004 החשש שמא יימאסו בהם ה\u0003פירורין.\u0004","\u0003ובית הלל אומרים\u0004 ש\u0003אם\u0004 ה\u0003שמש תלמיד חכם הוא,\u0004 הריהו \u0003נוטל\u0004 מעל השולחן בסוף הסעודה את ה\u0003פירורין שיש בהם כזית, ומניח\u0004 רק את ה\u0003פירורין שאין בהן כזית,\u0004 שאינם נחשבים לאוכל, ואין איסור בקלקולם.","\u0003מסייע ליה\u0004 \u0005[לו]\u0006 דבר זה \u0003לר' יוחנן.\u0004 ששנינו ש\u0003אמר ר' יוחנן: פירורין שאין בהם כזית\u0004 — \u0003מותר לאבדן ביד,\u0004 ואין בכך איסור השחתת אוכל.","אף ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים],\u0006 מהו יסוד המחלוקת? ומסבירים: \u0003בית הלל סברי\u0004 \u0005[סבורים[]\u0006 ש\u0003אסור להשתמש בשמש עם הארץ,\u0004 ואין לחשוש שישארו על השולחן פירורים העלולים להתקלקל במים. \u0003ו\u0004אילו \u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 ש\u0003מותר להשתמש בשמש עם הארץ,\u0004 ומוטב שלא יטלו ידים קודם ויקלקלו את האוכל שנשאר.","\u0003אמר ר' יוסי בר חנינא אמר רב הונא: בכוליה פרקין\u0004 \u0005[בכל פרקנו]\u0006 \u0003הלכה כבית הלל, בר מהא\u0004 \u0005[חוץ מזו]\u0006 ש\u0003הלכה\u0004 בה \u0003כבית שמאי, ור' אושעיא מתני איפכא\u0004 \u0005[היה שונה להיפך]\u0006 מן הכתוב במשנתנו, שהיה מחליף את שיטות בית הלל ובית שמאי, \u0003ובהא נמי\u0004 \u0005[ובזו גם כן]\u0006 \u0003הלכה כבית הלל.\u0004","שנינו במשנה ש\u0003בית שמאי אומרים\u0004 שאם האריכו בסעודה עד לצאת השבת הרי שסדר הברכות יהיה: \u0003נר,\u0004 ברכת \u0003מזון,\u0004 בשמים והבדלה, ובית הלל אומרים שסדר הברכות יהיה: נר, בשמים, מזון והבדלה.","ומסופר ש\u0003רב הונא בר יהודה איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רבא. חזייה\u0004 \u0005[ראהו]\u0006 את \u0003רבא דבריך\u0004 \u0005[שבירך]\u0006 על ה\u0003בשמים ברישא\u0004 \u0005[בתחילה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003בית הלל ובית שמאי\u0004 על ה\u0003מאור לא פליגי\u0004 \u0005[אינם חלוקים],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 במשנתנו ש\u0003בית שמאי אומרים\u0004 שהסדר הוא: \u0003נר,\u0004 ברכת \u0003מזון, בשמים והבדלה, ובית הלל אומרים\u0004 שהסדר הוא: \u0003נר ובשמים מזון והבדלה,\u0004 ואם כן לדעת שניהם הנר בתחילה!","\u0003עני\u0004 \u0005[ענה]\u0006 \u0003רבא בתריה\u0004 \u0005[אחריו]:\u0006 אכן דברים אלה כתובים במשנה, אך \u0003זו דברי ר' מאיר, אבל ר' יהודה אומר\u0004 בברייתא ש\u0003לא נחלקו בית הלל ובית שמאי על המזון שהוא בתחילה, ועל הבדלה שהיא בסוף,\u0004 אלא \u0003על מה נחלקו\u0004 — \u0003על המאור ועל הבשמים, שבית שמאי אומרים\u0004 שמברך תחילה \u0003על המאור ואחר כך\u0004 על ה\u0003בשמים, ובית הלל אומרים\u0004 שמברך תחילה על ה\u0003בשמים ואחר כך\u0004 על ה\u0003מאור.\u0004","\u0003ואמר ר' יוחנן\u0004 במפורש ש\u0003נהגו העם\u0004 בענין זה \u0003כבית הלל אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' יהודה,\u0004 ולכן יש להקדים את ברכת הבשמים.","במשנה הובאה מחלוקת בית הלל ובית שמאי מהו נוסח הברכה שעל האש בהבדלה, ש\u0003בית שמאי אומרים\u0004 שנוסח הברכה הוא \u0003\"שברא\u0004 מאור האש \u0003\",\u0004 ובית הלל אומרים שנוסח הברכה הוא \"בורא מאורי האש\".","על כך אומר רבא: \u0003ב\u0004מלה \u0003\"ברא\" כולי עלמא לא פליגי דברא משמע\u0004 \u0005[הכל אינם חלוקים שמשמעה ברא\u0006 בעבר\u0005].\u0006 \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חולקים],\u0006 הרי זה \u0003ב\u0004יחס למלה \u0003\"בורא\", שבית שמאי סברי\u0004 \u0005[סבורים]\u0006 שמשמעות \u0003בורא\u0004 היא שהוא \u0003עתיד למברא\u0004 \u0005[לברוא],\u0006 \u0003ובית הלל סברי\u0004 \u0005[סבורים]\u0006 כי \u0003\"בורא\" נמי\u0004 \u0005[גם כן]\u0006 \u0003דברא משמע\u0004 \u0005[שברא משמעו].\u0006","על כך \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף:\u0004 כיצד נאמר שנחלקו בפירוש המלה \"בורא\", שברורה משמעותה לחלוטין כגון \u0003\"יוצר אור ובורא חושך\"\u0004 (עמוס ד, יג), או \u0003\"יוצר הרים ובורא רוח\",\u0004 או \u0003\"בורא השמים ונוטיהם\"\u0004 (ישעיהו מב, ה), שכל אלה מתארים בריאה בעבר. \u0003אלא אמר רב יוסף: ב\u0004פירוש המילים \u0003\"ברא\" ו\"בורא\" כולי עלמא לא פליגי דברא משמע\u0004 \u0005[הכל אינם חלוקים שברא משמען],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים]\u0006 הרי זה האם יש לומר בנוסח הברכה \u0003\"מאור\u0004 האש \u0003\"\u0004או \u0003\"מאורי\u0004 האש \u0003\",\u0004 ש\u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 כי \u0003חדא נהורא איכא בנורא\u0004 \u0005[אור אחד יש באש],\u0006 \u0003ובית הלל סברי\u0004 \u0005[סבורים]\u0006 כי \u0003טובא נהורי איכא בנורא\u0004 \u0005[הרבה אורות יש באש],\u0006 משום שיש בשלהבת צבעים שונים אדומים ירוקים ולבנים. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003אמרו להם בית הלל לבית שמאי: הרבה מאורות יש באור\u0004 \u0005[באש].\u0006","שנינו במשנה ש\u0003אין מברכין\u0004 על הנר ועל הבשמים של גויים. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003נר\u0004 של גויים אסור לברך עליו בהבדלה \u0003משום\u0004 ש\u0003לא שבת\u0004 הנר, אלא בער בשבת, ולכן אין לברך עליו מחדש במוצאי שבת. \u0003אלא בשמים\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 מברכים עליהם?","\u0003אמר רב יהודה אמר רב: הכא\u0004 \u0005[כאן]\u0006 \u0003במסבת גוים עסקינן\u0004 \u0005[אנו עוסקים],\u0006 ואסרו בשמים של מסיבה זו מפני \u0003שסתם מסבת גויים לעבודה זרה היא\u0004","ושואלים: \u0003הא מדקתני סיפא\u0004 \u0005[הרי ממה ששנינו בסוף\u0006 המשנה\u0005]\u0006 ש\u0003אין מברכין לא על הנר ולא על בשמים של עבודה זרה, מכלל\u0004 הדבר אתה למד \u0003דרישא לאו\u0004 \u0005[שראשה\u0006 של המשנה \u0005לא]\u0006 \u0003בעבודה זרה עסקינן\u0004 \u0005[אנו עוסקים],\u0006 אלא ודאי יש לכך נימוק אחר!","\u0003אמר ר' חנינא מסורא:\u0004 אין זו ראיה, שאפשר לשלב את שתי ההלכות בדרך לימוד אחרת ולומר כי בדרך \u0003\"מה טעם\" קאמר\u0004 \u0005[אמר],\u0006 שמסביר בקטע השני את טעמו של הראשון. וכך יש להבין: \u0003מה טעם אין מברכין על נר ולא על בשמים של גוים\u0004 — \u0003מפני שסתם מסבת גוים לעבודה זרה\u0004 היא, ועל נר ובשמים של עבודה זרה אסור לברך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003אור ששבת\u0004 — \u0003מברכין עליו\u0004 בהבדלה שמוצאי שבת, \u0003ושלא שבת\u0004 — \u0003אין מברכין עליו.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הכוונה \u0003\"שבת\" ומאי\u0004 \u0005[מה]\u0006 הכוונה \u0003\"לא שבת\"?\u0004"],["\u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 ש\"לא שבת\" פירושו ש\u0003לא שבת מחמת מלאכה\u0004 ו\u0003אפילו ממלאכה דהתירא\u0004 \u0005[של היתר],\u0006 \u0003והתניא\u0004 \u0005[הרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003אור של חיה\u0004 (יולדת), או \u0003של חולה\u0004 שיש בו סכנה, שמותר לחלל עבורם את השבת, ואותו אור בער בשבת לצורכם — \u0003מברכין עליו\u0004 בהבדלה של מוצאי שבת!","\u0003אלא אמר רב נחמן בר יצחק: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שבת\"\u0004 — \u0003ששבת מחמת מלאכת עבירה,\u0004 וכאשר היה בוער בהיתר כל השבת כולה, וכגון לצורך יולדת או חולה, מברכים עליו. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003עששית\u0004 (פנס) \u0003שהיתה דולקת והולכת כל היום כולו\u0004 בשבת, \u0003מברכין עליה למוצאי שבת.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003גוי שהדליק\u0004 נר \u0003מ\u0004נר שהיה בידי \u0003ישראל,\u0004 או \u0003ישראל שהדליק\u0004 נר \u0003מגוי — מברכין עליו\u0004 במוצאי שבת. אבל \u0003גוי\u0004 שהדליק נר \u0003מגוי\u0004 — \u0003אין מברכין עליו.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 נר שהדליק \u0003גוי מגוי\u0004 ש\u0003לא\u0004 מברכים עליו — \u0003משום\u0004 ש\u0003לא שבת, אי הכי\u0004 \u0005[אם כך],\u0006 \u0003ישראל\u0004 המדליק נר \u0003מ\u0004נר של \u0003גוי נמי הא\u0004 \u0005[גם כן הרי]\u0006 אותו נר \u0003לא שבת\u0004 ביום השבת!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003הך איסורא אזל ליה, והא אחרינא הוא, ובידא דישראל קא מתילדא\u0004 \u0005[זו\u0006 השלהבת של \u0005איסור הלכה לה, וזו אחרת היא, ובידי הישראלי נולדת],\u0006 ששלהבת איננה דבר אחד קבוע, אלא בכל רגע נולדת שלהבת אחרת שדיניה אחרים — אם כן \u0003אלא הא דתניא\u0004 \u0005[\u0006הלכה \u0005זו ששנינו]\u0006 בתוספתא במסכת שבת: \u0003המוציא שלהבת\u0004 בשבת מרשות היחיד \u0003לרשות הרבים\u0004 — \u0003חייב\u0004 כמוציא מרשות לרשות. ואם כן, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב?\u0004 שהרי אם השלהבת משתנה בכל רגע, \u0003מה שעקר\u0004 מן המקום ברשות היחיד \u0003לא הניח\u0004 ברשות הרבים, \u0003ו\u0004כן \u0003מה שהניח לא עקר,\u0004 ואין המוציא דבר בשבת חייב אלא אם כן עקרו מרשות אחת והניחו לאותו דבר עצמו ברשות אחרת! הרי שהשלהבת על אף השינויים המתהווים בה נחשבת כמהות אחת!","\u0003אלא לעולם\u0004 יש להניח \u0003דאיסורא\u0004 \u0005[שהאיסור],\u0006 כלומר, השלהבת הראשונה שנדלקה באיסור, \u0003נמי איתיה\u0004 \u0005[גם כן ישנו],\u0006 \u0003וכי קא\u0004 \u0005[וכאשר הוא]\u0006 \u0003מברך\u0004 — \u0003אתוספתא דהתירא קא\u0004 \u0005[על התוספת של ההיתר\u0006 שנתחדשה בשלהבת \u0005הוא]\u0006 \u0003מברך,\u0004 ולכן, \u0003אי הכי\u0004 \u0005[אם כך],\u0006 כלומר, גם אם הדליק \u0003גוי מגוי נמי\u0004 \u0005[גם כן]\u0006 נחשוב שהשלהבת היא בעיקרה חדשה, ויברך על התוספת!","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, גם כן כך],\u0006 שמעצם הדברים אין מקום לאסור, אלא \u0003גזירה\u0004 היא שגזרו חכמים \u0003משום גוי ראשון\u0004 (שלא הדליק מגוי אחר) \u0003ועמוד ראשון,\u0004 כלומר, להט ראשון של השלהבת. ולכן אסרו בכל המקרים הדומים אפילו במקצת, גם כשהדליק גוי מגוי.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מי שהיה מהלך חוץ לכרך וראה\u0004 שם \u0003אור\u0004 (אש), ורוצה לברך עליו בהבדלה \u0003אם רוב גוים\u0004 בעיר — \u0003אינו מברך\u0004 על האור, ואם \u0003רוב ישראל\u0004 — \u0003מברך.\u0004","ומעירים: \u0003הא גופא קשיא\u0004 \u0005[\u0006ברייתא \u0005זו עצמה קשה],\u0006 שהיא סותרת את עצמה, שכן \u0003אמרת\u0004 בה ש\u0003אם\u0004 יש בעיר \u0003רוב גוים\u0004 — \u0003אינו מברך,\u0004 ומשמע \u0003הא\u0004 \u0005[הרי]\u0006 אם היו שם \u0003מחצה על מחצה\u0004 גוים — הריהו \u0003מברך, והדר תני\u0004 \u0005[וחזר ושנה]\u0006 ש\u0003אם\u0004 היו בעיר \u0003רוב ישראל\u0004 — הריהו \u0003מברך,\u0004 ומשמע \u0003הא\u0004 \u0005[הרי]\u0006 אם היו שם \u0003מחצה על מחצה\u0004 גוים — \u0003אינו מברך,\u0004 והדברים אם כן סותרים!","ומשיבים: \u0003בדין הוא\u0004 שהיה צריך לשנות ש\u0003אפילו\u0004 כאשר יש בעיר \u0003מחצה על מחצה ישראל\u0004 הריהו \u0003מברך\u0004 על אש זו, אלא \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה בתחילה]\u0006 בלשון \u0003\"רוב גוים\", תנא סיפא\u0004 \u0005[שנה בסוף]\u0006 \u0003\"רוב ישראל\",\u0004 משגרת לשון.","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מי ש\u0003היה מהלך,\u0004 במוצאי שבת, \u0003חוץ לכרך וראה תינוק ואבוקה\u0004 של אש \u0003בידו, בודק אחריו; אם ישראל הוא\u0004 — \u0003מברך\u0004 אם רוצה על אש זו בהבדלה, ואם גוי הוא התינוק — \u0003אינו מברך\u0004 עליה.","ושואלים: \u0003מאי איריא\u0004 \u0005[מדוע שנה]\u0006 דווקא ב\u0003תינוק? אפילו גדול נמי\u0004 \u0005[גם כן]\u0006 יש לבדוק אם ישראל הוא או גוי, שהלא יש בכך הבדל לגבי ברכה!","\u0003אמר רב יהודה אמר רב: הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004מקרה שהיה זה במוצאי שבת \u0003סמוך לשקיעת החמה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ולכן אם היה זה \u0003גדול,\u0004 הרי \u0003מוכחא מילתא\u0004 \u0005[מוכח הדבר]\u0006 ש\u0003ודאי גוי הוא,\u0004 שכן ישראל לא היה ממהר כל כך להחזיק נר בידו. אבל אם היה זה \u0003תינוק אימר\u0004 \u0005[אמור]\u0006 אולי ש\u0003ישראל הוא, אקרי ונקיט\u0004 \u0005[\u0006ו\u0005קרה שהחזיק]\u0006 את האש.","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מי ש\u0003היה מהלך,\u0004 במוצאי שבת, \u0003חוץ לכרך וראה אור, אם\u0004 אש זו \u0003עבה לפחות כפי הכבשן\u0004 — \u0003מברך עליו,\u0004 משום שאש כעין זו נעשתה גם כדי להשתמש באורה. \u0003ואם לאו\u0004 \u0005[לא]\u0006 שאינה עבה כל כך \u0003אינו מברך עליו.\u0004","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003אור של כבשן מברכין עליו\u0004 בהבדלה, \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 אור של כבשן \u0003אין מברכין עליו,\u0004 והרי זו לכאורה סתירה בין הברייתות!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שאפשר לומר כי \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 שאסרה לברך, מדברת \u0003בתחילה,\u0004 כאשר אך הדליקו את הכבשן ואש זו מיועדת רק לחמם את המצוי בכבשן, ואילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 שהתירה לברך מדברת \u0003לבסוף,\u0004 כאשר אין צורך עוד באש לעצמה אלא הכבשן ממשיך ללהוט, ומשתמשים באורו גם לצרכים אחרים.","וסתירה נוספת בין ברייתות בנושא דומה: \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003אור של תנור ושל כירים מברכין עליו\u0004 בהבדלה, \u0003ו\u0004לעומת זאת \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אין מברכין עליו!\u0004","ומשיבים: גם כאן \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שאפשר לומר באותה דרך כי \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 שאסרה לברך, מדברת \u0003בתחילה,\u0004 כאשר אך הדליקו את התנור או הכירים, ואש זו מיועדת רק לחמם את המצוי בהם, ואילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 שהתירה לברך מדברת \u0003לבסוף,\u0004 כאשר אין צורך עוד באש לעצמה אלא האש שבהם ממשיכה ללהוט, ומשתמשים בה גם לצרכים אחרים.","וסתירה נוספת: \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003אור של בית הכנסת ושל בית המדרש מברכין עליו\u0004 בהבדלה, \u0003ו\u0004לעומת זאת \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אין מברכין עליו!\u0004","ומשיבים: גם כאן גם כאן \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שאפשר לומר כי \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 שאסרה לברך, מדברת באופן \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003אדם חשוב\u0004 בבית הכנסת, ומדליקים את האור כדי לכבד אותו בהדלקת אורות, ולא לשימוש, \u0003ו\u0004אילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 המתירה עוסקת באופן \u0003דליכא\u0004 \u0005[שאין]\u0006 שם \u0003אדם חשוב\u0004 והאור נועד לשימוש.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי \u0003הא והא\u0004 \u0005[זו וזו]\u0006 שתי הברייתות מדברות באופן \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003אדם חשוב\u0004 בבית הכנסת, \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 שאת הסתירה בין הברייתות ניתן ליישב כך: \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 המתירה מדברת באופן \u0003דאיכא חזנא\u0004 \u0005[שיש שמש]\u0006 בבית הכנסת והוא משתמש באור, ואילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 האוסרת מדברת באופן \u0003דליכא חזנא\u0004 \u0005[שאין שמש]\u0006 בבית הכנסת והאור הוא רק לכבוד.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי \u0003הא והא\u0004 \u0005[זו וזו]\u0006 שתי הברייתות מדברות באופן \u0003דאיכא חזנא\u0004 \u0005[שיש שמש]\u0006 בבית הכנסת, \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 שאת הסתירה בין הברייתות ניתן ליישב כך: \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 האוסרת מדברת באופן \u0003דאיכא סהרא\u0004 \u0005[שיש ירח],\u0006 שלא הדליק השמש נרות כדי להאיר, שהלא יכול הוא להשתמש באור הירח, \u0003והא\u0004 \u0005[ו\u0006ברייתא \u0005זו]\u0006 המתירה מדברת באופן \u0003דליכא סהרא\u0004 \u0005[שאין ירח]\u0006 והשמש מדליק את האור כדי להשתמש בו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003היו יושבין בבית המדרש והביאו אור לפניהם\u0004 במוצאי שבת, \u0003בית שמאי אומרים: כל אחד ואחד\u0004 מהם \u0003מברך לעצמו. ובית הלל אומרים: אחד מברך לכולן,\u0004 והאחרים עונים אמן. וטעם הדבר — \u0003משום שנאמר: \"ברוב עם הדרת מלך\"\u0004 (משלי יד, כח), ויש תוספת כבוד כשהכל נאספים לשמוע את הברכה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ל\u0003בית הלל\u0004 שהם \u0003מפרשי טעמא\u0004 \u0005[מפרשים\u0006 את \u0005טעם]\u0006 דבריהם, \u0003אלא בית שמאי מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסרו לברך בציבור? ומשיבים: \u0003קסברי\u0004 \u0005[סברוים הם]\u0006 שיש לאסור \u0003מפני ביטול בית המדרש,\u0004 שעל ידי הציפיה למברך ייבטלו לרגעים אחדים מן הלימוד.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 עד כמה יש להקפיד על כך. ששנינו: בני \u0003בית רבן גמליאל לא היו אומרים \"מרפא\"\u0004 כאשר היה מישהו מתעטש \u0003בבית המדרש, מפני ביטול בית המדרש.\u0004","שנינו במשנה ש\u0003אין מברכין לא על הנר ולא על הבשמים של מתים.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003נר\u0004 של מת — \u0003לכבוד הוא דעבידא\u0004 \u0005[שנעשה]\u0006 ולא לשימוש, \u0003ובשמים לעבורי ריחא\u0004 כדי \u0005[להעביר את הריח\u0006 הרע\u0005]\u0006 \u0003הוא דעבידי\u0004 \u0005[שנעשו]\u0006 ולא לשם ריחם הטוב.","ו\u0003אמר רב יהודה אמר רב: כל\u0004 מאור \u0003שמוציאין לפניו,\u0004 לפני המת, ובאותו מספר \u0003ביום ובלילה\u0004 — \u0003אין מברכין עליו,\u0004 שמוכח שנרות אלה נעשו לכבוד בלבד. \u0003וכל\u0004 מאור \u0003שאין מוציאין לפניו אלא בלילה\u0004 — \u0003מברכין עליו,\u0004 שהרי רואים אנו שנועדו להארה.","וכעין זה \u0003אמר רב הונא: בשמים של בית הכסא, ושמן\u0004 ריחני שנעשה \u0003להעביר את הזוהמא\u0004 — \u0003אין מברכין עליו\u0004 כיון שלא נועד לבישום.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 שב\u0003כל היכא דלאו לריחא עבידא\u0004 \u0005[מקום שלא לריח נעשה]\u0006 \u0003לא מברכין עלויה\u0004 \u0005[עליו]?\u0006 \u0003מתיבי\u0004 \u0005[\u0006ו\u0005מקשים על כך]\u0006 ממה ששנינו בתוספתא: \u0003הנכנס לחנותו של בשם והריח ריח, ואפילו ישב שם כל היום כולו אינו מברך אלא פעם אחת.\u0004 ואולם אם \u0003נכנס ויצא, נכנס ויצא\u0004 — \u0003מברך על כל פעם ופעם. והא הכא דלאו לריחא\u0004 \u0005[והרי כאן שלא לריח]\u0006 \u0003הוא דעבידא\u0004 \u0005[שנעשה],\u0006 שהלא הריח בחנות הבושם לא נועד לבישום החנות, \u0003וקמברך\u0004 \u0005[ו\u0006בכל זאת \u0005הוא מברך]!\u0006","ומשיבים: \u0003אין, לריחא נמי הוא דעבידא, כי היכי דנירחו אינשי וניתו ונזבון מיניה\u0004 \u0005[כן, לריח גם כן הוא שנעשה, כדי שיריחו אנשים ויבואו ויקנו ממנו],\u0006 ואם כן ריח זה מכוון גם על מנת לבשם את החנות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: מי ש\u0003היה מהלך חוץ לכרך והריח ריח, אם רוב\u0004 בני העיר \u0003גוים\u0004 — \u0003אינו מברך,\u0004 ו\u0003אם רוב ישראל\u0004 — \u0003מברך. ר' יוסי אומר: אפילו\u0004 היו שם \u0003רוב ישראל\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אינו מברך, לפי שבנות ישראל מקטרות לכשפים\u0004 ובוודאי נעשו הבשמים לשם כישוף ולא לשם הרחה, על כך תמהים:","\u0003אטו כולהו\u0004 \u0005[האם כולן]\u0006 \u0003לכשפים מקטרן\u0004 \u0005[\u0006הן \u0005מקטרות]?!\u0006 אלא יש להסביר כי \u0003הוה ליה מיעוטא\u0004 \u0005[הרי מיעוט]\u0006 מקטרות \u0003לכשפים, ומיעוטא נמי\u0004 \u0005[ומיעוט\u0006 אחר \u0005גם כן]\u0006 שורפות בשמים כדי \u0003לגמר\u0004 (לבשם בקטורת) \u0003את הכלים\u0004 (הבגדים). — \u0003אשתכח רובא דלאו לריחא עביד\u0004 \u0005[נמצא\u0006 יחד \u0005רוב שלא לריח נעשה],\u0006 \u0003ו\u0004על \u0003כל רובא דלאו לריחא עביד\u0004 \u0005[רוב שלא לריח נעשה]\u0006 \u0003לא\u0004 \u0005[אינו]\u0006 \u0003מברך.\u0004","וכן \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: המהלך בערב שבת בטבריא\u0004 או \u0003במוצאי שבת בציפורי, והריח ריח\u0004 קטורת \u0003אינו מברך, מפני שחזקתו\u0004 (יש לשער) ש\u0003אינו עשוי אלא\u0004 כדי \u0003לגמר את הכלים.\u0004","ואגב מובא מה ש\u0003תנו רבנן\u0004 \u0005שנו חכמים\u0006 בברייתא: מי ש\u0003היה מהלך בשוק\u0004 של \u0003עבודה זרה\u0004 ו\u0003נתרצה להריח\u0004 בקטורת העולה שם — \u0003הרי זה חוטא.\u0004 שאף שהריח בא מאליו, אינו צריך להתכוון להריח בו."],["שנינו במשנה ש\u0003אין מברכין על הנר עד שיאותו\u0004 \u0005[יהנו]\u0006 לאורו.","\u0003אמר רב יהודה אמר רב: לא \"יאותו\" יאותו ממש,\u0004 כלומר, אין צורך ליהנות ממש מן האור, \u0003אלא כל שאילו עומד\u0004 מישהו \u0003בקרוב\u0004 לנר \u0003ו\u0004יכול שיהא \u0003משתמש לאורה,\u0004 בכגון זה יכול גם אחר הרואה אותה לברך עליה \u0003ואפילו\u0004 שהוא עצמו עומד \u0003בריחוק מקום. וכן אמר רב אשי:\u0004 הלכה זו שיכול לברך על אור הנר — אפילו \u0003בריחוק מקום שנינו.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בתוספתא: \u0003היתה לו נר טמונה בחיקו,\u0004 או שהיה הנר נתון \u0003ב\u0004תוך \u0003פנס\u0004 אטום, \u0003או שראה שלהבת ולא נשתמש לאורה, או\u0004 ש\u0003נשתמש לאורה,\u0004 אף על פי ש\u0003לא ראה את\u0004 ה\u0003שלהבת\u0004 — \u0003אינו מברך עד שיראה שלהבת ו\u0004גם \u0003ישתמש לאורה.\u0004","ובתחילה מבררים את עצם הדברים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מקרה שיהא \u0003משתמש לאורה ולא ראה שלהבת משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 אפשרות — \u0003דקיימא\u0004 \u0005[שנמצאת]\u0006 השלהבת \u0003בקרן זוית\u0004 והיא מאירה על סביבותיה, והוא עומד מאחורי הפינה. ואולם מקרה ש\u0003ראה שלהבת ולא נשתמש לאורה היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]\u0006 אפשרות? \u0003לאו דמרחקא\u0004 \u0005[האם לא\u0006 באופן \u0005שמרוחקת]\u0006 היא? הרי שיש להשתמש בשלהבת עצמה, ולא די שהשלהבת ראויה לכך!","ודוחים: \u0003לא,\u0004 מדובר כאן \u0003כגון דעמיא ואזלא\u0004 \u0005[שעממה\u0006 השלהבת \u0005והלכה],\u0006 כבתה לה, וזהו האופן שרואה שלהבת אך אינו יכול להשתמש בה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003גחלים לוחשות\u0004 — \u0003מברכין עליהן,\u0004 על האור, גחלים \u0003אוממות\u0004 — \u0003אין מברכין עליהן.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק]\u0006 הן הגחלים ה\u0003לוחשות? אמר רב חסדא: כל שאילו\u0004 היה \u0003מכניס לתוכן קיסם ודולקת מאיליה\u0004 בלי שיצטרכו ללבותו.","אגב דברי הברייתא מביאים את מה ש\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]\u0006 שאלה זו: האם יש לגרוס \u0003\"אוממות\" או \"עוממות\"?\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ש\u0003אמר רב חסדא בר אבדימי:\u0004 הגרסה היא \"עוממות\", וכלשון הכתוב: \u0003\"ארזים לא עממהו בגן אלהים\"\u0004 (יחזקאל לא, ח).","ולבעיה אם צריך ליהנות מאורה של שלהבת כדי לברך עליה, \u0003רבא אמר: \"יאותו\"\u0004 ששנינו פירושו יאותו \u0003ממש.\u0004","ושואלים: \u0003וכמה,\u0004 הוא שיעור הקירבה כדי הנאה משלהבת אש? \u0003אמר עולא: כדי שיכיר,\u0004 כלומר, יוכל להכיר בין שני מטבעות דומים, וכגון \u0003בין איסר לפונדיון. חזקיה אמר:\u0004 המידה היא \u0003כדי שיכיר בין מלוזמא\u0004 (משקולת) \u0003של טבריא למלוזמא של ציפורי\u0004 שהיה ביניהן הבדל קל.","מסופר כי \u0003רב יהודה\u0004 היה \u0003מברך\u0004 במוצאי שבת \u0003אדבי\u0004 \u0005[על\u0006 האור \u0005של בית]\u0006 \u0003אדא דיילא\u0004 \u0005[השמש],\u0006 ו\u0003רבא\u0004 היה \u0003מברך אדבי\u0004 \u0005[על\u0006 האור \u0005של בית]\u0006 \u0003גוריא בר חמא. אביי\u0004 היה \u0003מברך אדבי\u0004 \u0005[על\u0006 האור \u0005של בית]\u0006 \u0003בר אבוה.\u0004","כלל \u0003אמר רב יהודה אמר רב: אין מחזרין על האור\u0004 במוצאי שבת \u0003כדרך שמחזרין על המצות.\u0004 שאם לא נמצא לו נר לברך עליו, אין זה מעכב את ההבדלה. ו\u0003אמר ר' זירא: מריש הוה מהדרנא\u0004 \u0005[מתחילה הייתי מחזר]\u0006 אחרי הנר, \u0003כיון דשמענא להא\u0004 \u0005[ששמעתי\u0006 הלכה \u0005זו]\u0006 ש\u0003רב יהודה אמר\u0004 בשם \u0003רב, אנא נמי לא מהדרנא\u0004 \u0005[אני גם כן איני מחזר]\u0006 אחר נר, \u0003אלא אי מקלע\u0004 \u0005[אם מזדמן]\u0006 \u0003לי\u0004 נר \u0003ממילא\u0004 — \u0003מבריכנא\u0004 \u0005[מברך אני]\u0006 עליו.","במשנה הובאה המחלוקת אם \u0003מי שאכל\u0004 ושכח לברך צריך לחזור למקומו לברך. שבית הלל מתירים לברך במקום שנזכר, ובית שמאי מחייבים לחזור ולברך במקום שאכל. \u0003אמר רב זביד ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב דימי בר אבא: מחלוקת\u0004 זו היא רק \u0003ב\u0004מקרה ש\u0003שכח, אבל\u0004 אם קם ממקום האכילה \u0003במזיד\u0004 ולא ברך במקומו, \u0003דברי הכל\u0004 — \u0003יחזור למקומו ויברך.\u0004","ושואלים: \u0003פשיטא\u0004 \u0005פשוט,\u0006 מובן מאליו הוא, שהרי \u0003\"ושכח\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 ולא דובר במזיד.","ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003הוא הדין אפילו\u0004 לא ברך במקומו \u0003במזיד\u0004 שגם אז מתירים לו בית הלל לברך במקומו, \u0003והאי דקתני\u0004 \u0005[וזה ששנינו]\u0006 \u0003\"ושכח\"\u0004 — \u0003להודיעך כוחן\u0004 של \u0003בית שמאי\u0004 שאף במקרה זה מחייבים הם לחזור. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב זביד שבכך אין כלל מחלוקת.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמרו להם בית הלל לבית שמאי: לדבריכם, מי שאכל בראש הבירה\u0004 שבהר הבית \u0003ושכח\u0004 לברך \u0003וירד ולא ברך,\u0004 האם \u0003יחזור לראש הבירה ויברך?! אמרו להן בית שמאי לבית הלל:\u0004 ומדוע לא? ו\u0003לדבריכם מי ששכח ארנקי בראש הבירה לא יעלה ויטלנה? ואם לכבוד עצמו הוא\u0004 עולה \u0003כל שכן\u0004 שצריך לעלות \u0003לכבוד שמים.\u0004","מסופר: \u0003הנהו תרי תלמידי\u0004 \u0005[אותם שני תלמידים],\u0006 \u0003חד עביד\u0004 \u0005[אחד\u0006 מהם \u0005עשה],\u0006 כלומר, שכח לברך \u0003בשוגג,\u0004 ונהג \u0003כבית שמאי ואשכח ארנקא דדהבא\u0004 \u0005[וחזר ומצא ארנק זהב]\u0006 \u0003וחד עביד\u0004 \u0005[אחד\u0006 מהם \u0005עשה]\u0006 כן \u0003במזיד כבית הלל, ואכליה אריא\u0004 \u0005[ואכל אותו אריה].\u0006","ועוד מסופר: \u0003רבה בר בר חנה הוה קאזיל בשיירתא\u0004 \u0005[היה הולך בשיירה],\u0006 \u0003אכל ואשתלי\u0004 \u0005[ושכח]\u0006 \u0003ולא בריך\u0004 \u0005[ברך].\u0006 \u0003אמר\u0004 בליבו: \u0003היכי אעביד\u0004 \u0005[איך אעשה]?\u0006 \u0003אי אמינא להו\u0004 \u0005[אם אומר להם]\u0006 \u0003\"אנשאי\u0004 \u0005[שכחתי]\u0006 \u0003לברך\", אמרו\u0004 \u0005[יאמרו]\u0006 \u0003לי: בריך\u0004 \u0005[ברך],\u0006 \u0003כל היכא דמברכת\u0004 \u0005[מקום שאתה מברך]\u0006 — \u0003לרחמנא מברכת\u0004 \u0005[לה' אתה מברך].\u0006 \u0003מוטב דאמינא להו\u0004 \u0005[שאומר להם]:\u0006 \u0003אנשאי\u0004 \u0005[שכחתי]\u0006 \u0003יונה דדהבא\u0004 \u0005[של זהב].\u0006 ואז ימתינו לי עד שאחזור. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנטרו\u0004 \u0005[שמרו,\u0006 המתינו\u0005]\u0006 \u0003לי,\u0004 לפי \u0003דאנשאי\u0004 \u0005[ששכחתי]\u0006 \u0003יונה דדהבא\u0004 \u0005[של זהב].\u0006 \u0003אזל ובריך ואשכח\u0004 \u0005[הלך וברך, ומצא]\u0006 \u0003יונה דדהבא\u0004 \u0005[של זהב].\u0006","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 ה\u0003יונה?\u0004 מדוע אמר דווקא ששכח יונה? ומשיבים: \u0003דמתילי\u0004 \u0005[שמשולים]\u0006 \u0003כנסת ישראל ליונה. דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"כנפי יונה נחפה בכסף ואברותיה בירקרק חרוץ\"\u0004 (תהלים סח, יד), והסבר המשל: \u0003מה יונה אינה ניצולת\u0004 מאויביה \u0003אלא בכנפיה, אף ישראל אינן ניצולין אלא ב\u0004זכות ה\u0003מצות.\u0004","שנינו במשנה: \u0003עד אימתי הוא\u0004 יכול לברך מסיום האכילה? — כל עוד לא התעכל המזון במעיו.","ושואלים: \u0003כמה\u0004 הוא \u0003שיעור עכול? אמר ר' יוחנן: כל זמן ש\u0004עדיין \u0003אינו רעב\u0004 מחדש. \u0003וריש לקיש אמר: כל זמן שיצמא,\u0004 כלומר, שעדיין הוא צמא \u0003מחמת אכילתו.\u0004","\u0003אמר רב יימר בר שלמיא למר זוטרא ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב יימר בר שיזבי\u0004 שהקשה \u0003למר זוטרא: מי\u0004 \u0005[האם]\u0006 \u0003אמר ריש לקיש הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אמי אמר ריש לקיש: כמה\u0004 הוא \u0003שיעור עכול?\u0004 — די זמן \u0003כדי\u0004 שאפשר יהיה \u0003להלך\u0004 בו \u0003ארבע מילין!\u0004","ומתרצים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003כאן\u0004 שאמרנו שהשיעור הוא כדי מהלך ארבע מילין, הרי זה \u0003ב\u0004אופן שאכל \u0003אכילה מרובה, וכאן\u0004 שאמרנו שהשיעור הוא כל זמן שהוא צמא, הרי זה \u0003ב\u0004אופן שאכל \u0003אכילה מועטת.\u0004","מחלוקת אחרת היא אם \u0003בא להן\u0004 למסובים \u0003יין\u0004 רק \u0003אחר המזון, אם אין שם אלא אותו כוס\u0004 יין בלבד, \u0003בית שמאי אומרים\u0004 שבתחילה \u0003מברך על היין ו\u0004רק \u0003אחר כך מברך על המזון. ובית הלל אומרים\u0004 שבתחילה \u0003מברך על המזון ו\u0004רק \u0003אחר כך מברך על היין. ו\u0004עוד אמרו: \u0003עונין אמן אחרי ישראל המברך\u0004 אף על פי שלא שמעו את כל הברכה, \u0003ו\u0004אולם \u0003אין עונין אמן אחרי כותי\u0004 (שומרוני) שברך \u0003עד שישמע\u0004 את \u0003כל הברכה כולה.\u0004 שיתכן שבתחלת הברכה הכניס השומרוני דבר שאינו על פי אמונת ישראל.","שנינו במשנה מחלוקת תנאים בענין מקרה ש\u0003בא להם\u0004 למסובים \u0003יין\u0004 לאחר המזון. ועוד שנינו במשנה שעונים \"אמן\" אחר אדם מישראל שברך אף שלא שמע את כל הברכה. ושואלים: \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 ש\u0003ישראל אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא שמע כולה\u0004 \u0005[את כל]\u0006 ה\u0003ברכה עונה\u0004 אמן? \u0003וכי\u0004 \u0005[וכאשר]\u0006 הוא \u0003לא שמע היכי נפיק\u0004 \u0005[איך יצא]\u0006 ידי חובתו?","\u0003אמר חייא בר רב:\u0004 אין מדובר כאן ברוצה לצאת ידי חובה, אלא \u0003ב\u0004מי \u0003שלא אכל עמהם\u0004 ובא לענות אמן, \u0003וכן אמר רב נחמן אמר רבה בר אבוה בשלא אכל עמהן\u0004. ומסופר \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לחייא בריה\u0004 \u0005[בנו]:\u0006 \u0003ברי\u0004 \u0005[בני],\u0006 \u0003חטוף ובריך\u0004 \u0005[וברך],\u0006 כלומר, כשיש לך הזדמנות לברך — מהר לנצל אותה. \u0003וכן אמר רב הונא לרבה בריה\u0004 \u0005[בנו]\u0006 \u0003חטוף ובריך\u0004.","ושואלים: \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 שה\u0003מברך עדיף ממאן דעני\u0004 \u0005[ממי שעונה]\u0006 \u0003\"אמן\"? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' יוסי אומר: גדול\u0004 שכרו של \u0003העונה \"אמן\" יותר מן\u0004 השכר של \u0003המברך.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' נהוראי השמים\u0004 (ביטוי של התפעלות, כעין שבועה בקדוש ברוך הוא), \u0003כן הוא.\u0004 ו\u0003תדע\u0004 ראיה לדבר — \u0003שהרי גוליירין\u0004 (עוזריהם של אנשי הצבא) \u0003יורדין ומתגרין במלחמה\u0004 ופותחים את הקרב, \u0003ו\u0004אחר כך ה\u0003גבורים יורדין ומנצחין.\u0004 וה\"אמן\" שאחר הברכה משול לאותם גיבורים הבאים למלחמה לאחר הגוליירין, והרי שעניית \"אמן\" חשובה יותר!","ומשיבים: \u0003תנאי\u0004 \u0005[מחלוקת תנאים]\u0006 \u0003היא\u0004 בדבר. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד המברך ואחד העונה \"אמן\" במשמע\u0004 של ברכה, \u0003אלא שממהרין ל\u0004היות \u0003מברך יותר מן העונה \"אמן\".\u0004","\u0003בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003שמואל מרב: מהו\u0004 הדין לענין \u0003לענות \"אמן\" אחר תינוקות של בית רבן? אמר ליה\u0004 \u0005[לו]\u0006 ענה לו: \u0003אחר הכל עונים \"אמן\"\u0004 אם שומעים ברכה מהם, \u0003חוץ מתינוקות של בית רבן, הואיל ולהתלמד עשויים,\u0004 וברכות אלה לצורך לימוד הם ולא להודאה. \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא ש\u0003לא עידן מפטרייהו\u0004 \u0005[בעת שהם נפטרים]\u0006 בברכה זו, \u0003אבל בעידן מפטרייהו\u0004 \u0005[בעת שהם נפטרים]\u0006 בברכה זו — \u0003עונין\u0004 אמן אחריה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003שמן\u0004 שסכים בו את הידים אחר המזון לנקותן \u0003מעכב את הברכה\u0004 אם לא השתמשו בו, אלו \u0003דברי ר' זילאי. ר' זיואי אומר:\u0004 שמן זה \u0003אינו מעכב. רב אחא אומר: שמן טוב מעכב\u0004 את הברכה ויש להמתין עד שיסוכו בו את הידים. \u0003ר' זוהמאי אומר: כשם שמזוהם פסול לעבודה, כך ידים מזוהמות פסולות לברכה.\u0004","על כך \u0003אמר רב נחמן בר יצחק: אנא\u0004 \u0005[אני]\u0006 \u0003לא\u0004 את \u0003זילאי ולא\u0004 את \u0003זיואי ולא\u0004 את \u0003זוהמאי ידענא\u0004 \u0005[יודע אני]\u0006 \u0003אלא מתניתא ידענא\u0004 \u0005[ברייתא יודע אני].\u0006 ש\u0003אמר ר' יהודה אמר רב ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי \u0003במתניתא תנא\u0004 \u0005[בברייתא\u0006 היא \u0005שנויה]:\u0006 נאמר\"והתקדשתם והייתם קדושים כי אני ה' אלהיכם\" (ויקרא כ, כז) ואמרו: \u0003\"והתקדשתם\" אלו מים ראשונים\u0004 של נטילת ידים, \u0003\"והייתם קדושים\" אלו מים אחרונים\u0004 שלאחר המזון, \u0003\"כי קדוש\"\u0004 — \u0003זה\u0004 רמז ל\u0003שמן\u0004 שסכים בו את הידים, \u0003\"אני ה' אלהיכם\"\u0004 — \u0003זו ברכה.\u0004","\u0003הדרן עלך אלו דברים\u0004"],["במשנה זו מרוכזים כל הדברים אשר אחר כך יפורטו בפרק זה. ויש בה קובץ של ברכות והלכות שאין להן מסגרת זמן קבועה והן נאמרות בהזדמנויות שונות. \u0003הרואה מקום שנעשו בו נסים לישראל, אומר: \"ברוך... שעשה נסים לאבותינו במקום הזה\".\u0004 הרואה \u0003מקום שנעקרה ממנו עבודה זרה, אומר: \"ברוך... שעקר עבודה זרה מארצנו\".\u0004","על מאורעות הטבע הבולטים כמו \u0003על הזיקין ועל הזועות\u0004 (אשר ידונו בטיבם בגמרא), \u0003ועל הרעמים, ועל הרוחות\u0004 (רוחות הסערה), \u0003ועל הברקים\u0004 שיש בהם התגלות של כוח הבורא \u0003אומר\u0004 הרואה אותם: \u0003\"ברוך... שכחו וגבורתו מלא עולם\".\u0004 ואילו \u0003על ההרים, ועל הגבעות, ועל הימים, ועל הנהרות, ועל המדברות\u0004 היוצאים מגדר הרגיל (רמב\"ם) \u0003אומר: \"ברוך... עושה בראשית\". ר' יהודה\u0004 לשיטתו, שלדעתו יש לקבוע לכל מין פרטי ברכה לעצמו, ולכן הוא \u0003אומר: הרואה את הים הגדול\u0004 מברך ברכה מיוחדת, וכך הוא \u0003אומר: \"ברוך שעשה את הים הגדול\".\u0004 וברכה זו, כשאר ברכות הראיה מאותו סוג מברך רק \u0003בזמן שרואהו לפרקים,\u0004 ולא בקביעות.","\u0003על הגשמים ו\u0004כן \u0003על\u0004 שאר \u0003בשורות טובות אומר\u0004 ברכה מיוחדת: \u0003\"ברוך הטוב והמטיב\"\u0004 אף \u0003על בשורות רעות אומר\u0004 ברכה מיוחדת: \u0003\"ברוך דיין האמת\".\u0004 כמו כן כאשר \u0003בנה\u0004 אדם \u0003בית חדש, ו\u0004כן זה ש\u0003קנה כלים חדשים,\u0004 הריהו \u0003אומר: \"ברוך... שהחיינו וקיימנו והגיענו לזמן הזה\".\u0004 כלל אמרו: \u0003מברך\u0004 אדם \u0003על הרעה מעין\u0004 הברכה שמברך \u0003על הטובה.\u0004 כלומר, על רעה שיש בה לעתיד צד של טוב מברך כפי המצב הקיים. \u0003ו\u0004כן \u0003על הטובה מעין על הרעה.\u0004","\u0003ו\u0004עוד אמרו ש\u0003הצועק לשעבר,\u0004 כלומר, המתפלל על דבר שהיה בעבר ומנסה לתקן אותו בתפילתו — \u0003הרי זו תפלת שוא.\u0004 וכגון מי ש\u0003היתה אשתו מעוברת, ואומר \"יהי רצון שתלד אשתי\u0004 בן \u0003זכר\"\u0004 — \u0003הרי זו תפלת שוא.\u0004 או אם \u0003היה בא בדרך ושמע קול צוחה בעיר, ואומר \"יהי רצון שלא תהא\u0004 צוחה זו \u0003בתוך ביתי\"\u0004 — \u0003הרי זו תפלת שוא,\u0004 שהרי כבר אירע המאורע.","עוד אמרו חכמים: \u0003הנכנס לכרך\u0004 (וכאשר יבואר בגמרא מדובר במקום שיש סכנה בכניסה לכרך) \u0003מתפלל שתים,\u0004 שתי תפילות, \u0003אחת בכניסתו,\u0004 שיכנס בשלום, \u0003ואחת ביציאתו,\u0004 שיצא בשלום. \u0003בן עזאי אומר:\u0004 מתפלל \u0003ארבע\u0004 תפילות, \u0003שתים בכניסתו, ושתים ביציאתו.\u0004 שיכנס בשלום ויצא בשלום, וכן \u0003נותן הודאה על שעבר וצועק על העתיד.\u0004","ומכאן להכללה: \u0003חייב אדם לברך על הרעה כשם שמברך על הטובה, שנאמר: \"ואהבת את ה' אלהיך בכל לבבך\u0004 ובכל נפשך ובכל מאודך\u0003\"\u0004 (דברים ו, ה), וכך פירשוהו: \u0003\"בכל לבבך\"\u0004 — \u0003בשני יצריך, ביצר טוב וביצר הרע,\u0004 שצריך לשעבד את שניהם לאהבת ה'. \u0003\"ובכל נפשך\"\u0004 — \u0003אפילו הוא,\u0004 הקדוש ברוך הוא, \u0003נוטל את נפשך. \"ובכל מאדך\"\u0004 — \u0003בכל ממונך,\u0004 שכן הכסף נקרא \"מאד\" במקרא. \u0003דבר אחר\u0004 ניתן לפרש כי משמעות \u0003\"בכל מאדך\"\u0004 היא — \u0003בכל מדה ומדה שהוא מודד לך,\u0004 בין שהיא מידה טובה ובין שהיא מידת פורענות, \u0003הוי מודה לו.\u0004","ומכאן להלכות הקשורות בבית המקדש, \u0003לא יקל אדם את ראשו\u0004 בכל נוהג של זלזול \u0003כנגד שער המזרח\u0004 של הר הבית \u0003שהוא מכוון כנגד בית קדשי הקדשים. ו\u0004משום כבוד המקדש \u0003לא יכנס\u0004 אדם \u0003להר הבית במקלו, ובמנעלו, ובפונדתו\u0004 (חגורה חלולה ששמים בה את הכסף), \u0003ו\u0004אפילו \u0003באבק שעל רגליו. ולא יעשנו קפנדריא\u0004 שלא יעבור דרכו כדי לקצר את הדרך. \u0003ורקיקה\u0004 (יריקה) — \u0003מקל וחומר\u0004 שאסורה בהר הבית.","ומסופר: \u0003כל חותמי ברכות שבמקדש\u0004 במקום לענות \"אמן\" \u0003היו אומרים\u0004 \"ברוך אתה ה' אלהי ישראל מן העולם ו\u0003עד העולם\u0004 (האל הקדוש\", ...חונן הדעת\", וכן הלאה). ואולם \u0003משקלקלו הצדוקים ואמרו\u0004 ש\u0003אין עולם אלא אחד,\u0004 ואין עולם הבא, \u0003התקינו שיהו אומרים\u0004 בסיום כל ברכה \u0003\"מן העולם ועד העולם\".\u0004","\u0003ו\u0004עוד תקנה \u0003התקינו\u0004 חכמים: \u0003שיהא אדם שואל את שלום חברו בשם,\u0004 שמזכיר בברכה את שם ה' כדרך \u0003שנאמר: \"והנה בעז בא מבית לחם ויאמר לקוצרים ה' עמכם ויאמרו לו יברכך ה'\"\u0004 (רות ב, ד). \u0003ו\u0004עוד \u0003אומר\u0004 הכתוב: \u0003\"\u0004וירא אליו מלאך ה' ויאמר אליו \u0003ה' עמך גבור החיל\"\u0004 (שופטים ו, יב), \u0003ואומר\u0004 הכתוב: \"ו \u0003אל תבוז כי זקנה אמך\"\u0004 (משלי כג, כב), הרי שאין לזלזל במנהגים עתיקים. \u0003ו\u0004אם תאמר כי הזכרת שם ה' סתם אסורה — הרי על זה \u0003אומר\u0004 הכתוב: \u0003\"עת לעשות לה' הפרו תורתך\"\u0004 (תהלים קיט, קכו), שלפעמים כדי לקיים רצון ה' יש אף לבטל דברי תורה, ולשאול בשלום חבירו זהו מרצון ה'. \u0003ר' נתן אומר\u0004 שיש להבין את הפסוק באופן אחר: \u0003\"הפרו תורתך\" משום \"עת לעשות לה'\",\u0004 שבזמנים מסויימים יש לבטל דברי התורה כדי לעשות על ידי כך לחיזוקה.","בענין חובת הברכה על הנס שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 נלמדים? \u0003אמר ר' יוחנן,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויאמר יתרו ברוך ה' אשר הציל\u0004 אתכם מיד מצרים ומיד פרעה אשר הציל את העם מתחת יד מצרים\" (שמות יח, י), הרי שמברכים על הנס.","ושואלים: \u0003אניסא\u0004 \u0005[על נס]\u0006 של \u0003רבים מברכינן\u0004 \u0005[מברכים אנו]\u0006 ואילו \u0003אניסא\u0004 \u0005[על נס]\u0006 של \u0003יחיד לא מברכינן\u0004 \u0005[מברכים אנו]?!\u0006 \u0003והא ההוא גברא דהוה קא אזיל \u0005[והרי אותו אדם שהיה הולך]\u0006 בעבר ימינא\u0004 \u0005[בצד ימין]\u0006 של נהר פרת, \u0003נפל עליה אריא, אתעביד ליה ניסא, ואיתצל מיניה\u0004 \u0005[והתנפל עליו אריה, נעשה לו נס וניצל ממנו].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבא. אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003כל אימת\u0004 \u0005[זמן]\u0006 \u0003דמטית להתם\u0004 — \u0003בריך\u0004 \u0005[שתבוא לשם,\u0006 לאותו מקום שאירע בו הנס, \u0005ברך]\u0006 \u0003\"ברוך שעשה לי נס במקום הזה\".\u0004","וכן, \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא הוה קאזיל בפקתא\u0004 \u0005[היה מהלך בבקעה]\u0006 של \u0003ערבות וצחא למיא\u0004 \u0005[ו\u0006היה \u0005צמא למים].\u0006 \u0003אתעביד ליה ניסא, איברי ליה עינא דמיא, ואישתי\u0004 \u0005[נעשה לו נס,\u0006 ו\u0005נברא לו מעין מים, ושתה].\u0006","\u0003ותו, זמנא חדא הוה קאזיל ברסתקא\u0004 \u0005[ועוד, פעם אחת היה מהלך בשוק]\u0006 של \u0003מחוזא ונפל עליה גמלא פריצא\u0004 \u0005[והתנפל עליו גמל משוגע].\u0006 \u0003איתפרקא ליה אשיתא, על לגוה\u0004 \u0005[נבקע לו הכותל,\u0006 ו\u0005נכנס לתוכו,\u0006 וניצל\u0005].\u0006 ומאז, \u0003כי מטא\u0004 \u0005[כאשר היה מגיע]\u0006 \u0003לערבות, בריך\u0004 \u0005[היה מברך]\u0006 \u0003\"ברוך... שעשה לי נס בערבות ובגמל\".\u0004 וכן \u0003כי מטא לרסתקא\u0004 \u0005[כאשר היה מגיע לשוק]\u0006 של \u0003מחוזא בריך\u0004 \u0005[היה מברך]\u0006 \u0003\"ברוך... שעשה לי נס בגמל ובערבות\",\u0004 הרי שאף על נס של יחיד יש לברך! \u0003אמרי\u0004 \u0005[אומרים]\u0006 כהסבר לדבר: \u0003אניסא\u0004 \u0005[על נס]\u0006 של \u0003רבים\u0004 — \u0003כולי עלמא מיחייבי לברוכי\u0004 \u0005[הכל חייבים לברך],\u0006 ואולם \u0003אניסא\u0004 \u0005[על נס]\u0006 של \u0003יחיד\u0004 — \u0003איהו חייב לברוכי\u0004 \u0005[הוא מחוייב לברך].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא רשימה של מקומות שיש לברך על נסים שנעשו בהם: \u0003הרואה מעברות הים,\u0004 המקום בו עברו ישראל את ים סוף, או \u0003מעברות הירדן,\u0004 המקום בו עברו את הירדן, או \u0003מעברות נחלי ארנון,\u0004 וכן \u0003אבני\u0004 ה\u0003אלגביש במורד בית חורון, ו\u0004כן את ה\u0003אבן שבקש לזרוק עוג מלך הבשן על ישראל, ו\u0004כן את ה\u0003אבן שישב עליה משה בשעה שעשה יהושע מלחמה בעמלק, ו\u0004כן את \u0003אשתו של לוט, ו\u0004את \u0003חומת יריחו שנבלעה במקומה\u0004 — \u0003על כולן,\u0004 כל אותם ניסים, \u0003צריך שיתן הודאה ושבח לפני המקום.\u0004","ומבררים את הדברים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003מעברות הים\u0004 שהנס שבהם מפורש בתורה, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויבאו בני ישראל בתוך הים ביבשה\u0004 והמים להם חומה מימינם ומשמאלם\u0003\"\u0004 (שמות יד, כב), וכן בנס \u0003מעברות הירדן, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויעמדו הכהנים נשאי הארון ברית ה' בחרבה בתוך הירדן הכן וכל ישראל עברים בחרבה עד אשר תמו כל הגוי לעבור את הירדן\"\u0004 (יהושע ג, יז).","\u0003אלא\u0004 הנס שאירע ב\u0003מעברות נחלי ארנון מנלן\u0004 \u0005[מנין לנו]?\u0006 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"על כן יאמר בספר מלחמת ה' את והב בסופה\u0004 ואת הנחלים ארנון ואשד הנחלים אשר נטה לשבת ער ונשען בגבול מואב\u0003\"\u0004 (במדבר כא, יד–טו). \u0003תנא\u0004 \u0005[שנינו]\u0006 בענין הכתוב \u0003\"את והב בסופה\": שני מצורעים היו,\u0004 שאחד מהם נקרא \"את\" והשני נקרא \"הב\", \u0003דהוו\u0004 \u0005[שהיו]\u0006 \u0003מהלכין בסוף מחנה ישראל. כי הוו קא חלפי\u0004 \u0005[כאשר היו עוברים]\u0006 \u0003ישראל אתו אמוראי\u0004 \u0005[באו האמוריים]\u0006"],["\u0003עבדי להון נקירותא וטשו בהון\u0004 \u0005[עשו להם מערות והתחבאו בהן].\u0006 \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003כי חלפי\u0004 \u0005[כאשר יעברו]\u0006 \u0003ישראל הכא\u0004 \u0005[כאן]\u0006 — \u0003נקטלינון\u0004 \u0005[נהרגם],\u0006 \u0003ולא הוו ידעי\u0004 \u0005[היו יודעים]\u0006 ש\u0003ארון\u0004 הברית \u0003הוה מסגי קמייהו\u0004 \u0005[היה הולך לפני]\u0006 \u0003ישראל והוה ממיך להו טורי מקמייהו\u0004 \u0005[והיה מיישר להם\u0006 את ה\u0005הרים לפניהם].\u0006 \u0003כיון דאתא\u0004 \u0005[שבא]\u0006 ה\u0003ארון, אדבקו טורי בהדי הדדי, וקטלינון, ונחת דמייהו\u0004 \u0005[נדבקו ההרים זה לזה, והרגום, וירד דמם]\u0006 \u0003לנחלי ארנון. כי אתו\u0004 \u0005[כאשר באו]\u0006 \u0003את והב\u0004 המצורעים האמוריים, \u0003חזו דמא דקא נפיק מביני טורי\u0004 \u0005[ראו\u0006 את \u0005הדם היוצא מבין ההרים].\u0006 \u0003אתו ואמרי להו\u0004 \u0005[באו ואמרו להם]\u0006 \u0003לישראל\u0004 דבר זה. \u0003ו\u0004על כן \u0003אמרו\u0004 ישראל \u0003שירה. היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"ואשד הנחלים אשר נטה לשבת ער ונשען לגבול מואב\"\u0004 (במדבר כא, טו). כלומר, שפך (\"אשד\") הנחלים הנמצא במקום בו נטה ונתפשט ההר שהיה בעבר העמק לעבר ההר הנמצא בער, היא מואב.","בין הדברים אותם שנה התנא כניסים אשר במקום בו אירעו צריך לברך עליהם נמנו גם \u0003אבני אלגביש.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הם אותם \u0003אבני אלגביש?\u0004","\u0003תנא\u0004 \u0005[שנוי]\u0006 במדרש: הם ה\u0003אבנים שעמדו\u0004 באויר ולא ירדו \u0003על גב\u0004 (בגלל) \u0003איש, וירדו על גב איש.\u0004 ומפרשים: \u0003עמדו על גב איש\u0004 — \u0003זה משה\u0004 שנקרא בכתוב \"איש\", \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בו: \u0003\"והאיש משה ענו מאד\"\u0004 (שם יב, ג), \u0003וכתיב\u0004 \u0005[ו\u0006עוד \u0005נאמר]:\u0006 \u0003\"\u0004ויצא משה מעם פרעה את העיר ויפרוש כפיו אל ה' \u0003ויחדלו הקלות והברד ומטר לא נתך ארצה\"\u0004 (שמות ט, לג), הרי שעמדו אבני הברד בשל משה. והאבנים \u0003ירדו על גב איש\u0004 — \u0003זה יהושע\u0004 שאף הוא נקרא \"איש\", \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בו: \u0003\"קח לך את יהושע בן נון איש אשר רוח בו\"\u0004 (במדבר כז, יח), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שכאשר עלה יהושע ואנשיו למלחמה על חיל מלכי האמורי אמר לו ה' שלא ירא מהם כי הוא נותנם בידו, וכך אכן היה, שמתו באבנים, וכפי שנאמר: \u0003\"ויהי בנוסם מפני בני ישראל הם במורד בית חורן וה' השליך עליהם אבנים גדלות\u0004 מן השמים עד עזקה וימותו רבים אשר מתו באבני הברד מאשר הרגו בני ישראל בחרב\" (יהושע י, יא).","על ה\u0003אבן שבקש עוג מלך הבשן לזרוק על ישראל\u0004 אין מקרא כתוב, אלא \u0003גמרא גמירי לה\u0004 \u0005[מסורת מסורה היא].\u0006 ומסופר שכך \u0003אמר עוג: מחנה ישראל כמה הוי\u0004 \u0005[הוא]\u0006 — \u0003תלתא פרסי\u0004 \u0005[שלוש פרסאות],\u0006 \u0003איזיל ואיעקר טורא בר תלתא פרסי ואישדי עלייהו, ואיקטלינהו\u0004 \u0005[אלך ואעקור הר בן שלוש פרסות ואשליך עליהם, ואהרגם].\u0006 \u0003אזל\u0004 \u0005[הלך]\u0006 ו\u0003עקר טורא בר תלתא פרסי ואייתי על רישיה\u0004 \u0005[הר בן שלוש פרסות ושם על ראשו],\u0006 \u0003ואייתי קודשא בריך הוא עליה קמצי\u0004 \u0005[והביא הקדוש ברוך הוא עליו חגבים]\u0006 \u0003ונקבוה\u0004 לכיפת ההר, \u0003ונחית בצואריה\u0004 \u0005[ונפל\u0006 ההר \u0005על צווארו].\u0006","\u0003הוה בעי למשלפה\u0004 \u0005[היה\u0006 עוג \u0005רוצה לשלוף אותו]\u0006 מעל ראשו, \u0003משכי שיניה להאי גיסא ולהאי גיסא\u0004 \u0005[נמשכו שיניו לצד זה ולצד זה\u0006 של ראשו\u0005]\u0006 \u0003ולא מצי למשלפה\u0004 \u0005[יכול\u0006 היה \u0005לשולפו].\u0006 \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"שני רשעים שברת\"\u0004 (תהלים ג, ח). \u0003וכ\u0004פי שדרש \u0003ר' שמעון בן לקיש.\u0004 ש\u0003אמר ר' שמעון בן לקיש: מאי דכתיב\u0004 \u0005[מהי\u0006 משמעות זה \u0005שנאמר]\u0006 \u0003\"שני רשעים שברת\"\u0004 — \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"שברת\" אלא \"שרבבת\".\u0004","וסוף המעשה: \u0003משה כמה הוה\u0004 \u0005[היה\u0006 גובהו\u0005]\u0006 — \u0003עשר אמות, שקיל נרגא בר\u0004 \u0005[לקח גרזן בן]\u0006 \u0003עשר אמין\u0004 \u0005[אמות],\u0006 \u0003שוור\u0004 \u0005[קפץ]\u0006 \u0003עשר אמין\u0004 \u0005[אמות],\u0006 \u0003ומחייה בקרסוליה וקטליה\u0004 \u0005[והכהו בקרסולו והרגו].\u0006","\u0003ו\u0004על ה\u0003אבן שישב עליה משה\u0004 היא זו — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וידי משה כבדים ויקחו אבן וישימו תחתיו וישב עליה\"\u0004 (שמות יז,יב).","\u0003ו\u0004על \u0003אשתו של לוט\u0004 — \u0003שנאמר: \"ותבט אשתו מאחריו ותהי נציב מלח\"\u0004 (בראשית יט, כו). \u0003וחומת יריחו שנבלעה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותפל החומה תחתיה\"\u0004 (יהושע ו, כ).","ושואלים: \u0003בשלמא כולהו\u0004 — \u0003ניסא\u0004 \u0005[נניח לכולם\u0006 — \u0005ש\u0006הם \u0005נס],\u0006 \u0003אלא אשתו של לוט\u0004 הלא \u0003פורענותא\u0004 \u0005[פורענות]\u0006 \u0003הוא!\u0004 ומדוע יש לברך על הנס? ומשיבים: \u0003דאמר\u0004 \u0005[שאומר]\u0006 הרואה \u0003\"ברוך... דיין האמת\".\u0004","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 בברייתא שעל כולם \u0003\"הודאה ושבח\" קתני\u0004 \u0005[שנינו]\u0006 שהוא אומר! ומשיבים: יש לתקן את הלשון ו\u0003תני\u0004 \u0005[שנה]\u0006 בדרך זו: \u0003על לוט ועל אשתו מברכים שתים; על אשתו אומר \"ברוך... דיין האמת\", ועל לוט אומר \"ברוך... זוכר את הצדיקים\".\u0004 ש\u0003אמר ר' יוחנן:\u0004 ממעשה לוט אפשר ללמוד ש\u0003אפילו בשעת כעסו של הקדוש ברוך הוא,\u0004 הוא \u0003זוכר את הצדיקים, שנאמר: \"ויהי בשחת אלהים את ערי הככר ויזכר אלהים את אברהם וישלח את לוט מתוך ההפכה\"\u0004 (בראשית יט, כט).","\u0003ו\u0004עוד הוזכר שמברכים על \u0003חומת יריחו שנבלעה\u0004 במקומה. על כך שואלים \u0003ו\u0004האם \u0003חומת יריחו נבלעה? והא\u0004 \u0005[והרי]\u0006 נאמר שהחומה \u0003נפלה,\u0004 וכפי \u0003שנאמר: \"ויהי כשמע העם את קול השופר ויריעו העם תרועה גדולה ותפל החומה תחתיה\"\u0004 (יהושע ו, כ)! ומסבירים: \u0003כיון דפותיה ורומה כי הדדי נינהו\u0004 \u0005[שרוחבה וגובהה שווים זה לזה היו],\u0006 \u0003משום הכי אבלעה בלועי\u0004 \u0005[כך נבלעה],\u0006 שאילו היתה נופלת בלבד לא היתה בכך תועלת, שהרי רוחבה היה כגובהה.","\u0003אמר רב יהודה אמר רב: ארבעה צריכין להודות\u0004 לה' בקרבן תודה ובברכה מיוחדת ואלו הם: \u0003יורדי הים, הולכי מדברות, ומי שהיה חולה ונתרפא, ומי שהיה חבוש בבית האסורים ויצא.\u0004 וכולם נכתבו בפסוקי מזמור תהלים.","ומפרטים: \u0003יורדי הים מנלן\u0004 \u0005[מנין לנו]?\u0006 — \u0003\"יורדי הים באניות\u0004 עושי מלאכה במים רבים \u0003המה ראו מעשי ה'\"\u0004 (תהלים קז, כג–כד). \u0003ואומר\u0004 עוד: \u0003\"\u0004ויאמר \u0003ויעמד רוח סערה\u0004 ותרומם גליו. \u0003יעלו שמים ירדו תהומות\u0004 נפשם ברעה תתמוגג\" (שם פסוק כה), \u0003ו\u0004בהמשך \u0003אומר\u0004 הכתוב: \u0003\"יחוגו וינועו כשכור\u0004 וכל חכמתם תתבלע\" (שם כז), \u0003ו\u0004מיד אחרי כל זה הוא \u0003אומר: \"ויצעקו אל ה' בצר להם וממצוקתיהם יוציאם\"\u0004 (שם כח), \u0003ו\u0004אז הוא \u0003אומר: \"יקם סערה לדממה\u0004 ויחשו גליהם\u0003\"\u0004 (שם כט), \u0003ואומר: \"וישמחו כי ישתקו\u0004 וינחם אל מחוז חפצם\" (שם ל), \u0003ואומר\u0004 כי לאחר שהצילם והביאם למחוז חפצם \u0003\"יודו לה' חסדו ונפלאותיו לבני אדם\"\u0004 (שם לא).","ולגבי \u0003הולכי מדברות\u0004 שואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 באותו פרק: \u0003\"תעו במדבר בישימון דרך עיר מושב לא מצאו\"\u0004 (שם ד), ואז \u0003\"ויצעקו אל ה'\u0004 בצר להם ממצוקותיהם יצילם. \u0003וידריכם בדרך ישרה\"\u0004 (שם ו–ז), ואחרי שהדריכם בדרך ישרה אומר הכתוב: \u0003\"יודו לה' חסדו\"\u0004 (שם ז).","ו\u0003מי שחלה ונתרפא\u0004 שהוא צריך להודות למדים ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אוילים מדרך פשעם ומעונתיהם יתענו. כל אכל תתעב נפשם\u0004 ויגיעו עד שערי מות\" (שם יז–יח), ואז \u0003\"ויזעקו אל ה' בצר להם\u0004 ממצוקותיהם יושיעם\" (שם יט), ואז \u0003\"ישלח דברו וירפאם\u0004 וימלט משחיתותם\" (שם כ) ואחרי שרפאם \u0003\"יודו לה' חסדו\"\u0004 (שם כא).","ו\u0003מי שהיה חבוש בבית האסורין מנלן\u0004 \u0005[מנין לנו]?\u0006 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ישבי חשך וצלמות\u0004 אסירי עני וברזל\u0003. כי המרו אמרי אל\u0004 ועצת עליון נאצו\" (שם י–יא). \u0003ואומר\u0004 שם: \u0003\"ויכנע בעמל לבם\u0004 כשלו ואין עוזר\" (שם יב) \u0003ו\u0004אז הוא \u0003אומר: \"ויזעקו אל ה' בצר להם\u0004 ממצוקותיהם יושיעם\" (שם יג), \u0003ו\u0004אז הוא \u0003אומר: \"יוציאם מחשך וצלמות\u0004 ומוסרותיהם ינתק\" (שם יד), \u0003ו\u0004אחרי שהוציאם מאותו חושך וצלמות הוא \u0003אמר: \"יודו לה' חסדו\".\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מברך\u0004 זה שנעשו לו חסדי שמים אלו? \u0003אמר רב יהודה:\u0004 יש לברך \u0003\"ברוך גומל חסדים טובים\". אביי אמר: וצריך\u0004 המודה בברכה \u0003לאודויי קמי\u0004 \u0005[להודות בפני]\u0006 \u0003עשרה\u0004 אנשים, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 באותו פרק: \u0003\"וירוממוהו בקהל עם\u0004 ובמושב זקנים יהללוהו\" (שם לב), ו\"קהל\" — מיעוטו \u0003עשרה. מר זוטרא אמר: ותרין מינייהו רבנן\u0004 \u0005[ושנים מהם\u0006 צריכים להיות \u0005חכמים],\u0006 \u0003ש\u0004כן \u0003נאמר\u0004 שם: \u0003\"ובמושב זקנים יהללוהו\"\u0004 והם החכמים, ומיעוט רבים — שנים.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: ואימא כולהו רבנן\u0004 \u0005[ואמור\u0006 אולי שיהיו \u0005כולם חכמים]?!\u0006 ודוחים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"בקהל זקנים\"?\u0004 הלא \u0003\"בקהל עם\" כתיב\u0004 \u0005[נאמר],\u0006 וביניהם הזקנים—החכמים. ועדיין יש להקשות: \u0003ואימא\u0004 \u0005[ואמור]\u0006 אולי אנשים \u0003בי\u0004 \u0005[בסך]\u0006 \u0003עשרה\u0004 יהיו \u0003שאר עמא\u0004 \u0005[העם],\u0006 \u0003ותרי רבנן\u0004 \u0005[ו\u0006עוד \u0005שני חכמים]!\u0006 לכך לא נמצאה תשובה מספקת, והדבר נשאר \u0003קשיא\u0004 \u0005[קשה]\u0006 אף שלא נדחתה ההלכה.","ומסופר: \u0003רב יהודה חלש ואתפח\u0004 \u0005[חלה והתרפא].\u0006 \u0003על לגביה\u0004 \u0005[נכנסו אצלו]\u0006 \u0003רב חנא בגדתאה\u0004 \u0005[מבגדד]\u0006 \u0003ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003\"בריך רחמנא דיהבך ניהלן ולא יהבך לעפרא\"\u0004 \u0005[ברוך ה' שנתן אותך לנו ולא נתן אותך לעפר].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003פטרתון יתי מלאודויי\u0004 \u0005[פטרתם אותי מלהודות],\u0006 שעל ידי כך יצא ידי חובת הברכה.","על כך שואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר אביי\u0004 כי \u0003בעי אודויי באפי\u0004 \u0005[צריך להודות בפני]\u0006 \u0003עשרה!\u0004 ומשיבים: \u0003דהוו\u0004 \u0005[שהיו]\u0006 שם אנשים \u0003בי\u0004 \u0005[בסך]\u0006 \u0003עשרה.\u0004 ומקשים עוד: \u0003והא איהו לא קא\u0004 \u0005[והרי הוא\u0006 עצמו \u0005איננו]\u0006 \u0003מודה\u0004 ורק האחרים הודו! ומשיבים: \u0003לא צריך,\u0004 מדובר היה באופן \u0003דעני בתרייהו\u0004 \u0005[שענה אחריהם]\u0006 \u0003\"אמן\",\u0004 והעונה \"אמן\" אחר ברכה, הרי זה כאילו הוא עצמו בירך.","ואגב דברי רב יהודה שצרף מקרים אחדים ליחידה אחת, מביאים מאמרים דומים שלו. \u0003אמר רב יהודה: שלשה צריכים שימור\u0004 מפני המזיקים, \u0003ואלו הן\u0004 — \u0003חולה, חתן, וכלה. במתניתא תנא\u0004 \u0005[בברייתא שנו]:\u0006 \u0003חולה, חיה\u0004 (יולדת), \u0003חתן, וכלה. ויש אומרים: אף אבל. ויש אומרים: אף תלמידי חכמים בלילה.\u0004 שאנשים שמחשבתם נתונה לדברים אחרים או שמצבם הגופני אינו כתיקנו יש להשגיח עליהם.","\u0003ו\u0004עוד \u0003אמר רב יהודה: שלשה דברים המאריך בהם מאריכין ימיו ושנותיו של אדם.\u0004 ואלו הם: \u0003המאריך בתפלתו, והמאריך על שלחנו\u0004 באכילה, \u0003והמאריך בבית הכסא.\u0004","ושואלים: \u0003ו\u0004כי \u0003המאריך בתפלתו מעליותא\u0004 \u0005[מעלה]\u0006 \u0003היא? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חייא בר אבא אמר ר' יוחנן:\u0004"],["\u0003כל המאריך בתפלתו ומעיין בה,\u0004 שמצפה שתתקבל בקשתו — \u0003סוף\u0004 שהוא \u0003בא לידי כאב לב,\u0004 וכפי \u0003שנאמר \"תוחלת ממשכה מחלה לב\"\u0004 (משלי יג, יב). \u0003ו\u0004בדומה לכך \u0003אמר ר' יצחק: שלשה דברים מזכירים עונותיו של אדם, ואלו הן:\u0004 אם הוא יושב או עומד ליד \u0003קיר נטוי\u0004 העומד להתמוטט ומסכן את עצמו, \u0003ועיון תפלה,\u0004 שמאחר שהוא מצפה שתתקבל מיד בקשתו, בודקים בדינו אם אמנם ראוי הוא לכך, \u0003ומוסר דין על חבירו לשמים,\u0004 שמתפלל שבשמים יעשו דין באדם אחר, הוא שגורם שיבדקו וישוו את מעשי עצמו עם מעשי אותו אדם. והרי אם כן שהארכה בתפילה הריהי פגם!","ומתרצים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שהארכה בתפילה אינה טובה, הרי זה באופן ש\u0003מעיין בה\u0004 בתפילה, \u0003והא\u0004 \u0005[וזה]\u0006 שאמר רב יהודה שהארכה בתפילה מאריכה ימיו ושנותיו של אדם הרי זה באופן ש\u0003לא מעיין בה. והיכי עביד\u0004 \u0005[ואיך\u0006 הוא \u0005עושה]\u0006 שיאריך בתפילתו? — על ידי \u0003דמפיש ברחמי\u0004 \u0005[ש\u0006הוא \u0005מרבה בתחנונים].\u0006","\u0003ו\u0004את מעלת \u0003המאריך על שלחנו\u0004 שאמר רב יהודה, מסבירים: \u0003דלמא אתי עניא, ויהיב ליה\u0004 \u0005[שמא יבוא עני בתוך\u0006 הסעודה, \u0005ויתן לו]\u0006 מיד. בלא שיצטרך העני להמתין. וכבר אמרו בשבחו של אדם הנוהג כראוי בסעודתו, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"המזבח עץ שלוש אמות גבה\u0004 ואורכו שתים אמות ומקצועותיו לו ואורכו וקירותיו עץ\" (יחזקאל מא, כב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בהמשך אותו פסוק \u0003\"וידבר אלי זה השלחן אשר לפני ה'\"\u0004 ולכאורה לשון הפסוק תמוהה, שכן \u0003פתח במזבח וסיים בשלחן!\u0004 אלא \u0003ר' יוחנן ור' אלעזר דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 כהסבר לדבר: \u0003כל זמן שבית המקדש\u0004 היה \u0003קיים\u0004 — היה ה\u0003מזבח מכפר על ישראל, ועכשיו\u0004 כשחרב, \u0003שלחנו של אדם מכפר עליו.\u0004","\u0003ו\u0004על מה שאמר רב יהודה בשבח \u0003המאריך בבית הכסא\u0004 שואלים: וכי \u0003מעליותא\u0004 \u0005[מעלה]\u0006 \u0003הוא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עשרה דברים מביאין את האדם לידי תחתוניות\u0004 (טחורים), והם: \u0003האוכל עלי קנים\u0004 של סוף, \u0003ועלי גפנים, ולולבי\u0004 (קנוקנות) \u0003גפנים, ו\u0004כן \u0003מוריגי בהמה,\u0004 שהוא חלק בבשר הבהמה שאינו חלק ויש בו בליטות, \u0003ו\u0004כן \u0003שדרו של דג, ודג מליח שאינו מבושל כל צרכו, ו\u0004כן \u0003השותה שמרי יין, והמקנח\u0004 עצמו \u0003בסיד ובחרסית\u0004 (חומר שממנו עושים חרסים). \u0003ו\u0004כן \u0003המקנח\u0004 עצמו \u0003בצרור שקנח בו חברו, ויש אומרים: אף התולה עצמו\u0004 (המתאמץ) \u0003בבית הכסא יותר מדאי.\u0004 והרי שהארכה בבית הכסא אף עלולה להזיק!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו בברייתא שהדבר עלול להזיק, הרי זה באופן שהוא \u0003מאריך ותלי\u0004 \u0005[ותולה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב יהודה שמעלה היא, הרי זה באופן שהוא \u0003מאריך ו\u0004אולם \u0003לא תלי\u0004 \u0005[תולה].\u0006","ומסופר על תועלת הדבר, \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמרה ליה ההיא\u0004 \u0005[לו אותה]\u0006 \u0003מטרוניתא לר' יהודה בר' אלעאי: פניך דומים למגדלי חזירים ולמלוי ברבית,\u0004 שמאחר שאינם יגיעים הרבה בעבודתם ופרנסתם בשפע משמינים הם ופניהם מלאים וטובים. \u0003אמר לה: הימנותא, לדידי תרוייהו אסירן\u0004 \u0005[באמונה, לי אסורים שניהם],\u0006 \u0003אלא\u0004 משום מה פני טובים — מפני ש\u0003עשרים וארבעה בית הכסא איכא מאושפיזאי לבי מדרשא\u0004 \u0005[יש מבית מלוני עד בית המדרש],\u0006 \u0003דכי אזילנא, בדיקנא נפשאי בכולהו\u0004 \u0005[שכאשר אני הולך אני בודק את עצמי בכולם].\u0006","\u0003ו\u0004עוד \u0003אמר רב יהודה: שלשה דברים מקצרים ימיו ושנותיו של אדם: מי שנותנין לו\u0004 ומזמינים אותו ל\u0003ספר תורה לקרות\u0004 בו \u0003ואינו קורא,\u0004 או שנותנים לו \u0003כוס של ברכה לברך ואינו מברך, והמנהיג עצמו ברבנות\u0004 (שררה).","ומפרטים את מקור הדברים: \u0003ספר תורה לקרות\u0004 בו \u0003ואינו קורא, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 על התורה: \u0003\"כי הוא חייך וארך ימיך\"\u0004 (דברים ל, כ). \u0003כוס של ברכה לברך ואינו מברך\u0004 — \u0003כעין דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואברכה מברכיך\"\u0004 (בראשית יב, ג), שהמברך — מתברך. ומי שאינו מברך — אינו זוכה לברכה. \u0003ו\u0004לגבי \u0003המנהיג עצמו ברבנות\u0004 — כפי ש\u0003אמר ר' חמא בר' חנינא: מפני מה מת יוסף קודם לאחיו,\u0004 וכפי שרואים בסדר הדברים בפסוק \"וימת יוסף וכל אחיו וכל הדור ההוא\" (שמות א, ו) — \u0003מפני שהנהיג\u0004 את \u0003עצמו ברבנות,\u0004 והם שלא שמשו בהנהגה האריכו ימים אחריו.","\u0003ואמר רב יהודה אמר רב, שלשה צריכים\u0004 אנשים לבקשת \u0003רחמים\u0004 כדי שיבואו: \u0003מלך טוב, שנה טובה וחלום טוב.\u0004 ששלושה אלה נתונים ביד ה', וצריך להתפלל שיבואו בדרך טובה. ומקור לדברים: \u0003מלך טוב\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"פלגי מים לב מלך ביד ה'\u0004 על כל אשר יחפוץ יטנו\" (משלי כא, א). על \u0003שנה טובה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"תמיד עיני ה' אלהיך בה מראשית השנה ועד אחרית שנה\"\u0004 (דברים יא, יב). ועל \u0003חלום טוב\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004ה' עליהם יחיו ולכל בהן חיי רוחי \u0003ותחלימני והחיני\"\u0004 \u0005(ישעיהו לח, טז)\u0006 המתפרש \"תחלימני\" — מלשון חלום.","מעין זה \u0003אמר ר' יוחנן: שלשה דברים מכריז עליהם הקדוש ברוך הוא בעצמו ואלו הן\u0004: \u0003רעב, ושובע, ופרנס\u0004 (מנהיג) \u0003טוב.\u0004 ומקור לדברים: על ה\u0003רעב\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"כי קרא ה' לרעב\u0004 וגם בא אל הארץ שבע שנים\u0003\"\u0004 (מלכים ב' ח, א). ועל ה\u0003שובע\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וקראתי אל הדגן והרביתי אתו\u0004 ולא אתן עליכם רעב\" (יחזקאל לו, כט). ולגבי \u0003פרנס טוב\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וידבר ה' אל משה לאמר. ראה קראתי בשם בצלאל\u0004 בן אורי בן חור למטה יהודה\" (שמות לא, א — ב).","ובענין מינויו של בצלאל \u0003אמר ר' יצחק: אין מעמידין פרנס על הצבור אלא אם כן נמלכים בצבור\u0004 שיתנו את הסכמתם למינוי. וכפי \u0003שנאמר:\u0004 \"ויאמר משה אל בני ישראל \u0003ראו קרא ה' בשם בצלאל\u0004 בן אורי בן חור למטה יהודה\" (שמות לה, ל), ש\u0003אמר לו הקדוש ברוך הוא למשה: משה, הגון עליך בצלאל?\u0004 האם סבור אתה שראוי הוא לכך? \u0003אמר לו\u0004 משה: \u0003רבונו של עולם, אם לפניך הוא הגון\u0004 — \u0003לפני לא כל שכן! אמר לו\u0004 הקדוש ברוך הוא: \u0003אף על פי כן, לך אמור להם\u0004 לישראל ושאל את דעתם. \u0003הלך\u0004 משה \u0003ואמר להם לישראל: הגון עליכם בצלאל? אמרו לו: אם לפני הקדוש ברוך הוא ולפניך הוא הגון, לפנינו לא כל שכן!\u0004","\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: בצלאל על שם חכמתו נקרא\u0004 בשם זה. \u0003שבשעה שאמר לו הקדוש ברוך הוא למשה: לך אמור לו לבצלאל \"עשה לי משכן ארון וכלים\".\u0004 (עיין שמות לא, ז–יא), \u0003הלך משה והפך\u0004 את סדר הדברים \u0003ואמר לו\u0004 לבצלאל: \u0003\"עשה ארון וכלים ומשכן\"\u0004 (עיין שמות פרק כה וכו). \u0003אמר לו\u0004 בצלאל למשה: \u0003משה רבינו, מנהגו של עולם שאדם בונה בית ואחר כך מכניס לתוכו כלים, ואתה אומר\u0004 לי \u0003\"עשה לי ארון וכלים ומשכן\",\u0004 ואם אעשה כפי סדר הדברים שאתה אומר, \u0003כלים שאני עושה, להיכן אכניסם? שמא כך אמר לך הקדוש ברוך הוא,\u0004 להיפך, \u0003\"עשה משכן ארון וכלים\"?!\u0004 (עיין שמות פרק לו). \u0003אמר לו\u0004 משה: \u0003שמא בצל אל היית וידעת\u0004 את שאמר הקדוש ברוך הוא במדוייק? שהרי אתה מכוון לדברים כמו שנאמרו מפי ה', כאילו היית מצוי שם.","ועוד בשבח בצלאל \u0003אמר רב יהודה אמר רב: יודע היה בצלאל לצרף\u0004 ה\u0003אותיות שנבראו בהן שמים וארץ.\u0004 ומנין למד אתה זאת? — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בענין סיפור שבחו של בצלאל \u0003\"ואמלא אתו רוח אלהים בחכמה ובתבונה ובדעת\u0004 ובכל מלאכה\" (שמות לא, ג), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בענין בריאת השמים והארץ: \u0003\"ה' בחכמה יסד ארץ כונן שמים בתבונה\"\u0004 (משלי ג, יט), וכתיב \u0005[ונאמר]\u0006 שם בהמשך הדברים: \u0003\"בדעתו תהומות נבקעו\u0004 ושחקים ירעפו טל\" (שם פסוק כ), הרי שהדברים שבהם נבראו השמים והארץ, החכמה התבונה והדעת, מצויים היו בבצלאל.","אגב פסוקים מביאים את מה ש\u0003אמר ר' יוחנן: אין הקדוש ברוך הוא נותן חכמה אלא למי שיש בו חכמה\u0004 מכבר. וראיה לדבר ממה \u0003שנאמר: \"יהב חכמתא לחכימין ומנדעא לידעי בינה\"\u0004 \u0005[נותן חכמה לחכמים ודעת ליודעי בינה]\u0006 (דניאל ב, כא). \u0003שמע\u0004 את הדברים הללו \u0003רב תחליפא בר מערבא\u0004 (בן ארץ ישראל) \u0003ואמרה קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אבהו. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אתון מהתם מתניתו לה, אנן מהכא מתנינן לה\u0004 \u0005[אתם משם אתם שונים,\u0006 למדים, \u0005אותה,\u0006 את הראיה לרעיון זה, \u0005אנחנו מכאן אנו שונים,\u0006 למדים, \u0005אותה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בשבח בוני המשכן: \u0003\"ובלב כל חכם לב נתתי חכמה\"\u0004 (שמות לא, ו).","אגב מה שנאמר שיש להתפלל על חלום טוב, מביאים מאמרים נוספים שעניינם חלומות ופתרונם. \u0003אמר רב חסדא: כל חלום\u0004 יראה האדם, \u0003ולא טוות\u0004 \u0005[תענית],\u0006 כלומר, כל חלום טוב יותר מחלום של שעת תענית שהוא גרוע. \u0003ואמר רב חסדא: חלמא\u0004 \u0005[חלום]\u0006 ש\u0003לא מפשר\u0004 \u0005[נפתר]\u0006 הריהו \u0003כאגרתא\u0004 \u0005[כאגרת]\u0006 ש\u0003לא מקריא\u0004 \u0005[נקראה].\u0006 שכל עוד לא נפתר אינו יכול להתקיים, ופתרון החלום הוא היוצר את משמעותו. \u0003ו\u0004עוד \u0003אמר רב חסדא: לא חלמא טבא מקיים כוליה\u0004 \u0005[חלום טוב מתקיים כולו]\u0006 \u0003ולא חלמא בישא מקיים כוליה\u0004 \u0005[חלום רע מתקיים כולו].\u0006 \u0003ו\u0004עוד \u0003אמר רב חסדא: חלמא בישא\u0004 \u0005[חלום רע]\u0006 \u0003עדיף מחלמא טבא\u0004 \u0005[מחלום טוב],\u0006 שעל ידי החלום הרע מצטער ובא לידי תשובה. \u0003ו\u0004עוד \u0003אמר רב חסדא: חלמא בישא\u0004 \u0005[חלום רע]\u0006 — \u0003עציבותיה מסתייה\u0004 \u0005[עצבותו מספיקה לו],\u0006 \u0003חלמא טבא\u0004 \u0005[חלום טוב]\u0006 — \u0003חדוייה מסתייה\u0004 \u0005[שמחתו מספיקה לו],\u0006 שההתרגשות (לעצב או לשמחה) מן החלום גורמת שלא יהיה מימוש אחר לחלום. וכן \u0003אמר רב יוסף: חלמא טבא\u0004 \u0005[חלום טוב],\u0006 \u0003אפילו לדידי\u0004 \u0005[אצלי],\u0006 \u0003בדיחותיה מפכחא ליה\u0004 \u0005[שמחתו מפכחת,\u0006 מבטלת, \u0005אותו].\u0006 שאפילו הוא, שהיה עיוור וחולה, נהנה מן החלום הטוב עד שאינו מגיע עוד להתגשמות. \u0003ואמר רב חסדא: חלמא בישא\u0004 \u0005[חלום רע]\u0006 \u0003קשה מנגדא\u0004 \u0005[ממלקות],\u0006 \u0003שנאמר: \"והאלהים עשה שיראו מלפניו\"\u0004 (קהלת ג, יד), \u0003ואמר רבה בר בר חנה אמר ר' יוחנן\u0004 כהסבר לפסוק: \u0003זה חלום רע\u0004 המפיל אימה על האדם.","על הפסוק \u0003\"הנביא אשר אתו חלום יספר חלום ואשר דברי אתו ידבר דברי אמת מה לתבן את הבר נאם ה'\"\u0004 (ירמיהו כג, כח), שואלים: \u0003וכי מה ענין בר ותבן אצל חלום? אלא אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: כשם שאי אפשר לבר\u0004 שיהא \u0003בלא תבן, כך אי אפשר לחלום בלא דברים בטלים,\u0004 שאף חלום שעתיד להתקיים — מקצתו דברים בטלים.","ובדומה לכך \u0003אמר ר' ברכיה: חלום, אף על פי שמקצתו מתקיים\u0004 — \u0003כולו אינו מתקיים. מנא לן\u0004 \u0005[מנין לנו\u0006 דבר זה\u0005]?\u0006 — \u0003מ\u0004סיפור חלומותיו של \u0003יוסף, דכתיב\u0004 \u0005[שנאמר]\u0006 \"ויאמר הנה חלמתי חלום עוד \u0003והנה השמש והירח\u0004"],["ואחד עשר כוכבים משתחווים לי\" (בראשית לז, ט), \u0003וההיא שעתא אמיה לא הות\u0004 \u0005[ובאותה שעה אמו לא היתה]\u0006 כבר בחיים, ולפי משמעות החלום הירח מסמל את אמו של יוסף, הרי שאף חלום זה שנתקיים, היה בו דבר שלא התקיים.","ומכאן \u0003אמר ר' לוי: לעולם יצפה אדם ל\u0004התגשמותו של \u0003חלום טוב עד עשרים ושתים שנה. מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? — \u0003מיוסף, דכתיב\u0004 \u0005[שנאמר]\u0006 בסיפור חלומו של יוסף: \u0003\"אלה תלדות יעקב יוסף בן שבע עשרה שנה\u0004 היה רועה את אחיו בצאן\" (שם, ב) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויוסף בן שלשים שנה בעמדו לפני פרעה\u0004 מלך מצרים\" (שם מא, מו), \u0003מן שבסרי\u0004 \u0005[שבע עשרה]\u0006 ו\u0003עד תלתין\u0004 \u0005[שלושים]\u0006 \u0003כמה\u0004 שנים \u0003הוי\u0004 \u0005[הם]?\u0006 — \u0003תלת סרי\u0004 \u0005[שלוש עשרה],\u0006 \u0003ושב דשבעא ותרתי דכפנא\u0004 — \u0003הא עשרים ותרתי\u0004 \u0005[ו\u0006עוד \u0005שבע\u0006 שנים \u0005של שובע ושתים של רעב\u0006 — \u0005הרי עשרים ושתים]\u0006 ורק אז נתקיים החלום שבאו אחיו והשתחוו לו.","\u0003אמר רב הונא: לאדם טוב אין מראין לו חלום טוב, ולאדם רע אין מראין לו חלום רע,\u0004 אלא הטוב נענש על מקצת חטאותיו בחלומות רעים, והרע מקבל שכר על זכויותיו בחלומות טובים.","\u0003תניא נמי הכי\u0004 \u0005[שנינו\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כל שנותיו של דוד לא ראה\u0004 דוד \u0003חלום טוב, וכל שנותיו של אחיתופל לא ראה\u0004 אחיתופל \u0003חלום רע.\u0004","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 על הבוטח בה' \u0003\"לא תאנה אליך רעה\u0004 ונגע לא יקרב באהלך\" (תהלים צא, י). \u0003ואמר רב חסדא אמר רב ירמיה בר אבא\u0004 כפירוש לפסוק: הכוונה היא \u0003שלא יבהילוך לא חלומות רעים ולא הרהורים רעים.\u0004 ופירוש \u0003\"ונגע לא יקרב באהלך\"\u0004 — \u0003שלא תמצא אשתך\u0004 שהיא \u0003ספק נדה בשעה שאתה בא מן הדרך.\u0004 והרי שאין זה אפשרי שיהיו כל ימיו של צדיק בחלומות רעים! \u0003אלא\u0004 יש לומר כי \u0003איהו לא חזי ליה, אחריני חזו ליה\u0004 \u0005[הוא לא ראה\u0006 חלומות, אבל \u0005אחרים ראו לו]\u0006 חלומות רעים שחלמו עליו.","ושואלים: \u0003וכי לא חזא איהו, מעליותא הוא\u0004 \u0005[וכאשר לא ראה הוא,\u0006 חלום, האם \u0005מעלה היא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' זעירא: כל הלן שבעה ימים בלא\u0004 שיחלום \u0003חלום\u0004 — \u0003נקרא \"רע\",\u0004 שמראה הדבר שאף בדרך עקיפין זו אין הקדוש ברוך הוא מתגלה אליו. ורמז לדבר ממה \u0003שנאמר: \"ושבע ילין בל יפקד רע\"\u0004 (משלי יט, כג), ואמרו חכמים: \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"שבע\" אלא \"שבע\",\u0004 ונדרש: מי ששבע פעמים ילין ולא יפקד בחלום — הריהו רע. \u0003אלא\u0004 יש ודאי לומר כי ראה דוד חלומות, ו\u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003דחזא\u0004 \u0005[שראה]\u0006 דוד \u0003ו\u0004אולם \u0003לא ידע מאי חזא\u0004 \u0005[מה ראה].\u0006","\u0003אמר רב הונא בר אמי אמר ר' פדת אמר ר' יוחנן: הרואה חלום ונפשו עגומה\u0004 ממנו, \u0003ילך ויפתרנו בפני שלשה.\u0004 על כך תמהים: \u0003\"יפתרנו\"?! והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא\u0004 כי \u0003חלמא\u0004 \u0005[חלום]\u0006 ש\u0003לא מפשר\u0004 \u0005[נפתר]\u0006 הריהו \u0003כאגרתא\u0004 \u0005[כאיגרת]\u0006 ש\u0003לא מקריא\u0004 \u0005[נקראה],\u0006 ואם חושש מפני החלום מדוע יקרב את התגשמותו? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003יטיבנו בפני שלשה.\u0004 וכך יעשה: \u0003ליתי תלתא ולימא להו\u0004 \u0005[יביא שלושה\u0006 אנשים \u0005ויאמר להם]:\u0006 \u0003\"חלמא טבא חזאי\"\u0004 \u0005[חלום טוב ראיתי].\u0006 \u0003ולימרו ליה הנך\u0004 \u0005[ויאמרו לו אלו]:\u0006 \u0003\"טבא\u0004 \u0005[טוב]\u0006 \u0003הוא וטבא ליהוי\u0004 \u0005[וטוב יהיה],\u0006 \u0003רחמנא לשוייה לטב\u0004 \u0005[הקדוש ברוך הוא יעשה אותו לטוב].\u0006 \u0003שבע זימנין לגזרו עלך מן שמיא דלהוי טבא, ויהוי טבא\"\u0004 \u0005[שבע פעמים יגזרו עליך מן השמים שיהיה טוב, ויהיה טוב].\u0006 \u0003ולימרו\u0004 \u0005[ו\u0006אחר כך \u0005יאמרו]\u0006 \u0003שלש\u0004 פסוקים של \u0003הפוכות,\u0004 שמוזכרת בהם הפיכה מרע לטוב, \u0003ושלש\u0004 של \u0003פדויות ושלש\u0004 של הזכרת \u0003שלומות.\u0004","ומפרטים: \u0003שלש הפוכות\u0004 — \u0003\"הפכת מספדי למחול לי פתחת שקי ותאזרני שמחה\"\u0004 (תהלים ל, יב), וכן \u0003\"אז תשמח בתולה במחול... ובחרים וזקנים יחדו והפכתי אבלם לששון\u0004 ונחמתים ושמחתים מיגונם\" (ירמיהו לא, יב), וכן \u0003\"ולא אבה ה' אלהיך לשמע אל בלעם ויהפך\u0004 ה' אלהיך לך את הקללה לברכה\" (דברים כג, ו).","\u0003ושלש פדויות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"פדה בשלום נפשי מקרב לי\u0004 כי ברבים היו עמדי\" (תהלים נה, יט), וכן \u0003\"ופדויי ה' ישבון\u0004 ובאו ציון ברנה ושמחת עולם על ראשם ששון ושמחה ישיגו ונסו יגון ואנחה\" (ישעיהו לה, י), וכן \u0003\"ויאמר העם אל שאול היונתן ימות אשר עשה הישועה\u0004 הגדולה הזאת בישראל... ויפדו העם את יונתן ולא מת\" (שמואל א' יד, מה).","ו\u0003שלש שלומות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בורא ניב שפתים שלום שלום לרחוק ולקרוב אמר ה' ורפאתיו\"\u0004 (ישעיהו נז, יט). וכן \u0003\"ורוח לבשה את עמשי\u0004 ראש השלישים לך דויד ועמך בן ישי שלום שלום לך ושלום לעזרך כי עזרך אלהיך\" (דברי הימים א' יב, יט). וכן \u0003\"ואמרתם כה לחי ואתה שלום וביתך שלום\u0004 וכל אשר לך שלום\" (שמואל א' כה, ו).","מסופר כי \u0003אמימר ומר זוטרא ורב אשי הוו יתבי בהדי הדדי\u0004 \u0005[היו יושבים יחד].\u0006 \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003כל חד וחד מינן לימא מלתא דלא שמיע ליה לחבריה\u0004 \u0005[כל אחד ואחד מאתנו יאמר דבר שלא שמע אותו חבירו].\u0006 \u0003פתח חד מינייהו\u0004 \u0005[אחד מהם]\u0006 \u0003ואמר: האי מאן דחזא חלמא ולא ידע מאי חזא, ליקום קמי כהני בעידנא דפרסי ידייהו ולימא הכי\u0004 \u0005[מי שראה חלום ואינו יודע מה ראה, יעמוד לפני הכהנים בזמן שנושאים כפיהם\u0006 בברכת כהנים \u0005ויאמר כך]:\u0006 \u0003\"רבונו של עולם, אני שלך וחלומותי שלך, חלום חלמתי ואיני יודע מה הוא. בין שחלמתי אני לעצמי ובין שחלמו לי חבירי ובין שחלמתי על אחרים, אם טובים הם\u0004 — \u0003חזקם ואמצם כחלומותיו של יוסף. ואם צריכים\u0004 הם ל\u0003רפואה\u0004 — \u0003רפאם כמי מרה על ידי משה רבינו, וכמרים מצרעתה, וכחזקיה מחליו, וכמי יריחו על ידי אלישע. וכשם שהפכת קללת בלעם הרשע לברכה, כן הפוך כל חלומותי עלי לטובה\". ומסיים בהדי כהני דעני צבורא\u0004 \u0005[יחד עם הכהנים שעונה הציבור]\u0006 \u0003\"אמן\"\u0004 אחר הדברים, הן ברכת הכהנים והן בקשתו הפרטית. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שאינו מספיק לומר כל נוסח זה, \u0003לימא הכי\u0004 \u0005[יאמר כך]:\u0006 \u0003\"אדיר במרום, שוכן בגבורה, אתה שלום ושמך שלום. יהי רצון מלפניך שתשים עלינו שלום\".\u0004","\u0003פתח אידך\u0004 \u0005[האחר]\u0006 \u0003ואמר: האי מאן דעייל למתא ודחיל מעינא בישא\u0004 \u0005[מי שנכנס לעיר וירא מעין הרע],\u0006 \u0003לנקוט זקפא דידא דימיניה בידא דשמאליה וזקפא דידא דשמאליה בידא דימיניה, ולימא הכי\u0004 \u0005[יחזיק בוהן ידו הימנית בידו השמאלית ובוהן ידו השמאלית בידו הימנית, ויאמר כך]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003פלוני בר\u0004 \u0005[בן]\u0006 \u0003פלוני מזרעא\u0004 \u0005[מזרע]\u0006 של \u0003יוסף קאתינא\u0004 \u0005[אני בא],\u0006 ש\u0003לא שלטא ביה עינא בישא\u0004 \u0005[שלטה בו עין רעה],\u0006 \u0003ש\u0004על יוסף \u0003נאמר: \"בן פרת יוסף בן פרת עלי עין\u0004 בנות צעדה עלי שור\" (בראשית מט, כב), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"עלי עין\" אלא \"עולי עין\",\u0004 שהוא למעלה מן העין, ואין העין יכולה לשלוט בו. \u0003ר' יוסי בר' חנינא אמר: מהכא\u0004 \u0005[מכאן]\u0006 נלמד הדבר, ממה שנאמר בברכת בני יוסף \u0003\"וידגו לרב בקרב הארץ\"\u0004 (שם מח, טז), ומשמעות הדבר: \u0003מה דגים שבים\u0004 ה\u0003מים מכסים עליהם\u0004 ואינם נראים \u0003ואין עין רעה שולטת בהם, אף זרעו של יוסף אין עין רעה שולטת בהם. ואי דחיל מעינא בישא דיליה\u0004 \u0005[ואם הוא חושש מהעין הרעה של עצמו]\u0006 שתזיק לאחרים, \u0003ליחזי אטרפא דנחיריה דשמאליה\u0004 \u0005[יסתכל בצד נחירו השמאלי].\u0006","\u0003פתח אידך\u0004 \u0005[האחר]\u0006 \u0003ואמר: האי מאן דחליש\u0004 \u0005[מי שחולה],\u0006 \u0003יומא קמא לא לגלי, כי היכי דלא לתרע מזליה\u0004 \u0005[ביום הראשון אל יגלה, כדי שלא יורע מזלו],\u0006 \u0003מכאן ואילך לגלי\u0004 \u0005[יגלה].\u0006 \u0003כי הא\u0004 \u0005[כמו\u0006 דבר \u0005זה]\u0006 שהיה ב\u0003רבא, כי הוה חליש\u0004 \u0005[\u0006ש\u0005כאשר היה חולה],\u0006 \u0003יומא קמא\u0004 \u0005[ביום הראשון]\u0006 \u0003לא מגלי\u0004 \u0005[\u0006היה \u0005מגלה]\u0006 \u0003מכאן ואילך אמר ליה לשמעיה\u0004 \u0005[לו לשמשו]:\u0006 \u0003פוק אכריז\u0004 \u0005[צא\u0006 ו\u0005הכרז]:\u0006 \u0003\"רבא חלש\"\u0004 \u0005[חלה].\u0006 \u0003מאן דרחים לי\u0004 \u0005[מי שאוהב אותי]\u0006 — \u0003לבעי\u0004 \u0005[יבקש]\u0006 \u0003עלי רחמי\u0004 \u0005[רחמים],\u0006 \u0003ומאן דסני לי\u0004 \u0005[ומי ששונא אותי]\u0006 — \u0003לחדי לי\u0004 \u0005[ישמח עלי].\u0006 \u0003וכתיב\u0004 \u0005[ו\u0006הרי \u0005נאמר]\u0006 \u0003\"בנפל אויבך אל תשמח ובכשלו אל יגל לבך פן יראה ה' ורע בעיניו והשיב מעליו אפו\"\u0004 (משלי כד, יז–יח), כך שגם שמחתם לאיד של אויבי תסייע להחלמתי.","מסופר: \u0003שמואל כי הוה חזי חלמא בישא\u0004 \u0005[כאשר היה רואה חלום רע]\u0006 \u0003אמר\u0004 \u0005[היה אומר]:\u0006 \u0003\"וחלמות השוא ידברו\"\u0004 (זכריה י, ב). \u0003כי הוה חזי חלמא טבא\u0004 \u0005[כאשר היה רואה חלום טוב]\u0006 \u0003אמר: וכי החלומות השוא ידברו? והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"בחלום אדבר בו\"\u0004 (במדבר יב, ו)!","ואכן, \u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה את הסתירה\u0005]\u0006 בין הכתובים הללו: מצד אחד \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"בחלום אדבר בו\",\u0004 ומצד אחר \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"וחלמות השוא ידברו\"!\u0004 ומתרץ: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שיש שני סוגי חלומות \u0003כאן\u0004 הפסוק \"בחלום אדבר בו\" שממנו משמע שיש ממש בחלומות, מדבר בחלומות הבאים \u0003על ידי מלאך, וכאן\u0004 הפסוק \"וחלומות השוא ידברו\", שממנו משמע שאין בחלומות ולא כלום, מדבר בחלום הבא \u0003על ידי שד.\u0004","בשלשלת ארוכה של מוסרי המאמר מסופר כי \u0003אמר ר' ביזנא בר זבדא אמר ר' עקיבא אמר ר' פנדא אמר רב נחום אמר ר' בירים משום\u0004 (בשם) \u0003זקן אחד, ומנו\u0004 \u0005[ומי הוא]\u0006 — \u0003ר' בנאה: עשרים וארבעה פותרי חלומות היו בירושלים, פעם אחת חלמתי חלום והלכתי אצל כולם\u0004 לפתור חלום שראיתי, \u0003ומה שפתר לי זה לא פתר לי זה, ו\u0004אף על פי כן \u0003כולם,\u0004 כל הפתרונות \u0003נתקיימו בי. לקיים מה שנאמר: כל החלומות הולכים אחר הפה\u0004 של הפותר.","ושואלים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003\"כל החלומות הולכים אחר הפה\" קרא\u0004 \u0005[מקרא]\u0006 \u0003הוא\u0004 שהוא מצטט ומאמת אותו? ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 \u0003וכ\u0004דברי \u0003ר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר: מנין שכל החלומות הולכין אחר הפה\u0004 של הפותר? — \u0003שנאמר\u0004 בסיפור חלומות שני שרי פרעה, שר המשקים ושר האופים, שאמרו הם לפרעה: \u0003\"ויהי כאשר פתר לנו כן היה\"\u0004 (בראשית מא, יג). \u0003אמר רבא,\u0004 יש להגביל דברים אלו: \u0003והוא\u0004 דווקא באופן \u0003דמפשר ליה\u0004 \u0005[שפותר לו]\u0006 \u0003מעין חלמיה\u0004 \u0005[מעין חלומו],\u0006 שנראה שהפתרון נובע מהחלום, \u0003שנאמר\u0004 בסיפור פתרון חלומות שרי פרעה על ידי יוסף \u0003\"איש כחלמו פתר\"\u0004 (שם יב).","ואגב הבאת פתרון החלומות על ידי יוסף, שואלים: נאמר \u0003\"וירא שר האפים\u0004 כי טוב פתר\" (שם מ, טז), ו\u0003מנא\u0004 \u0005[מנין]\u0006 \u0003ידע\u0004 שר האופים שפתרון טוב הוא? \u0003אמר ר' אלעזר: מלמד שכל אחד ואחד\u0004 מהם \u0003הראוהו חלומו ופתרון חלומו של חבירו,\u0004 ולכן ידע שהוא הפתרון הנכון.","על התאמתותם של חלומות \u0003אמר ר' יוחנן:\u0004 מי ש\u0003השכים ונפל לו פסוק לתוך פיו,\u0004 שעם קומו בבוקר עולה בדעתו פסוק מסויים, \u0003הרי זו נבואה קטנה,\u0004 ויש בכך רמז שיתקיים תוכן הפסוק.","\u0003ו\u0004עוד \u0003אמר ר' יוחנן: שלשה חלומות מתקיימין: חלום של שחרית, וחלום שחלם לו\u0004 (עליו) \u0003חבירו, וחלום שנפתר בתוך\u0004 ה\u0003חלום. ויש\u0004 מי ש\u0003אומר\u0004 ש\u0003אף חלום שנשנה\u0004 כמה פעמים מתקיים, \u0003שנאמר \"ועל השנות החלום\u0004 אל פרעה פעמיים כי נכון הדבר מעם האלהים וממהר האלהים לעשותו\" (שם מא, לב).","\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: אין מראין לו לאדם\u0004 בחלום \u0003אלא מהרהורי לבו\u0004 בהקיץ. וראיה לדבר ממה \u0003שנאמר\u0004 שאמר דניאל לנבוכדנצר: \u0003\"אנת מלכא רעיונך על משכבך סלקו\u0004 מה די להוא אחרי דנה\" \u0005[אתה המלך רעיונותיך על משכבך עלו מה יהיה אחרי כן]\u0006 (דניאל ב, כט). \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שהדבר נלמד \u0003מהכא\u0004 \u0005[מכאן],\u0006 מפסוק אחר באותו ענין \u0003\"ורעיוני לבבך תנדע\"\u0004 \u0005[ומחשבות לבך תדע]\u0006 (שם ל), ואיך תדע? — בכך שהם יתגלו לך בחלום. \u0003אמר רבא: תדע\u0004 שכן הוא, שהרי \u0003לא מחוו ליה לאינש\u0004 \u0005[מראים לו לאדם]\u0006 בחלום \u0003לא דקלא דדהבא\u0004 \u0005[דקל\u0006 העשוי \u0005מזהב]\u0006 \u0003ולא פילא דעייל בקופא דמחטא\u0004 \u0005[פיל\u0006 הנכנס \u0005בקוף המחט],\u0006 כלומר, שאין בחלום דברים שאין אדם מעלה על דעתו."],["ומעין זה מסופר ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003קיסר\u0004 רומי \u0003לר' יהושע בר' חנניא: אמריתו דחכמיתו טובא\u0004 \u0005[אתם\u0006 היהודים \u0005אומרים, שאתם חכמים ביותר],\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003לי\u0004 אם כן \u0003מאי חזינא בחלמאי\u0004 \u0005[מה אראה בחלומי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע: \u0003חזית דמשחרי לך פרסאי וגרבי בך, ורעיי בך שקצי בחוטרא דדהבא\u0004 \u0005[תראה ששובים אותך הפרסים ומשעבדים אותך, ורועים על ידך שקצים במקל של זהב].\u0006 \u0003הרהר כוליה יומא\u0004 \u0005[כל\u0006 אותו \u0005היום]\u0006 בתיאור הדברים כפי שאמר לו ר' יהושע, \u0003ולאורתא חזא\u0004 \u0005[ובלילה ראה]\u0006 חלום זה. וכן \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שבור מלכא,\u0004 מלך פרס \u0003לשמואל: אמריתו דחכמיתו טובא\u0004 \u0005[אתם\u0006 היהודים \u0005אומרים, שאתם חכמים ביותר],\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003לי\u0004 אם כן \u0003מאי חזינא בחלמאי\u0004 \u0005[מה אראה בחלומי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003חזית דאתו רומאי ושבו לך, וטחני בך קשייתא ברחייא דדהבא\u0004 \u0005[תראה שיבואו הרומאים וישבו אותך,\u0006 ויכריחו אותך \u0005לטחון גרעיני תמרים בריחים של זהב].\u0006 \u0003הרהר כוליה יומא\u0004 \u0005[כל\u0006 אותו \u0005היום]\u0006 בתיאור הדברים כפי שאמר לו שמואל, \u0003ולאורתא חזא\u0004 \u0005[ובלילה ראה]\u0006 חלום זה.","מסופר: \u0003בר הדיא מפשר חלמי הוה\u0004 \u0005[פותר חלומות היה].\u0006 \u0003מאן דיהיב ליה אגרא\u0004 \u0005[מי שהיה נותן לו שכר]\u0006 — \u0003מפשר ליה למעליותא\u0004 \u0005[היה פותר לו למעלה,\u0006 לטובה\u0005],\u0006 \u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003לא יהיב ליה אגרא\u0004 \u0005[היה נותן לו שכר]\u0006 — \u0003מפשר ליה לגריעותא\u0004 \u0005[היה פותר לו לרעה].\u0006 ומספרים: היה מעשה ש\u0003אביי ורבא חזו\u0004 \u0005[ראו]\u0006 שניהם \u0003חלמא\u0004 \u0005[חלום]\u0006 זהה, ובקשו מבר הדיא לפותרו. \u0003אביי יהיב ליה זוזא\u0004 \u0005[נתן לו זוז]\u0006 בשכרו, \u0003ורבא לא יהיב ליה\u0004 \u0005[נתן לו].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003אקרינן בחלמין\u0004 \u0005[הקריאו לנו בחלומנו]\u0006 את הפסוק \u0003\"שורך טבוח לעיניך\u0004 ולא תאכל ממנו\" (דברים כח, לא). \u0003לרבא אמר,\u0004 הסביר \u0003ליה\u0004 \u0005[לו]:\u0006 \u0003פסיד\u0004 \u0005[יפסיד]\u0006 \u0003עסקך ולא אהני לך למיכל מעוצבא דלבך\u0004 \u0005[תוכל לאכול מ\u0006רוב \u0005עצבות לבך].\u0006 ו\u0003לאביי אמר\u0004 ( הסביר) \u0003ליה\u0004 \u0005[לו]:\u0006 \u0003מרווח\u0004 \u0005[ירוויח,\u0006 יצליח\u0005]\u0006 \u0003עסקך ולא אהני לך למיכל מחדוא דלבך\u0004 \u0005[תוכל לאכול מרוב שמחת לבך].\u0006","עוד \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003אקרינן\u0004 \u0005[הקריאו לנו]\u0006 בחלומנו את הפסוק \u0003\"בנים ובנות תוליד\u0004 ולא יהיו לך כי ילכו בשבי\" (שם מא). \u0003לרבא אמר ליה\u0004 \u0005[לו]\u0006 כהסבר: \u0003כבישותיה\u0004 \u0005[כרעתו],\u0006 כלומר, כמשמעות הכתוב. ו\u0003לאביי אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בנך ובנתך נפישי, ומינסבן בנתך לעלמא, ומדמיין באפך כדקא אזלן בשביה\u0004 \u0005[בניך ובנותיך ירבו ובנותיך תנשאנה לעולם,\u0006 החוצה, \u0005וידמו בעיניך כאילו נלקחו בשבי].\u0006","ושוב אמרו לו: \u0003אקריין\u0004 \u0005[הקריאו לנו]\u0006 בחלומנו את הפסוק \u0003\"בניך ובנתיך נתנים לעם אחר\"\u0004 (שם לב). \u0003לאביי אמר ליה\u0004 \u0005[לו]\u0006 כהסבר: \u0003בנך ובנתך נפישין, את אמרת לקריבך והיא אמרה לקריבה, ואכפה לך ויהבת להון לקריבה, דהוי\u0004 \u0005[בניך ובנותיך ירבו, אתה תאמר,\u0006 נשיא אותם, \u0005לקרובין. והיא:\u0006 אשתך, \u0005תאמר לקרוביה, ותכפה היא אותך ותשיא אותם לקרוביה, ויהיו]\u0006 בעיניך \u0003כעם אחר.\u0004 ו\u0003לרבא אמר ליה\u0004 \u0005[לו]\u0006 כהסבר: \u0003דביתהו שכיבא, ואתו בניה ובנתיה לידי איתתא אחריתי\u0004 \u0005[אשתך תמות ויבואו בניך ובנותיך לידי אשה אחרת].\u0006 שכן \u0003אמר רבא אמר ר' ירמיה בר אבא אמר רב: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות זה \u0005שנאמר]\u0006 בפסוק \u0003\"בניך ובנתיך נתנים לעם אחר\"\u0004 — \u0003זו אשת האב,\u0004 אם חורגת.","ושוב אמרו לו: \u0003אקרינן בחלמין\u0004 \u0005[הקריאו לנו בחלומנו]\u0006 פסוק זה: \u0003\"לך אכל בשמחה לחמך\u0004 ושתה בלב טוב יינך\" (קהלת ט, ז) \u0003לאביי אמר ליה\u0004 \u0005[לו]\u0006 כהסבר: \u0003מרווח\u0004 \u0005[ירוויח,\u0006 יצליח\u0005]\u0006 \u0003עסקך ואכלת ושתית וקרית פסוקא מחדוא דלבך\u0004 \u0005[ותאכל ותשתה ותקרא פסוק זה מתוך שמחת לבך],\u0006 ו\u0003לרבא אמר ליה\u0004 \u0005[לו]\u0006 כהסבר: \u0003פסיד\u0004 \u0005[יפסיד]\u0006 \u0003עסקך, טבחת ולא אכלת ושתית וקרית לפכוחי פחדך\u0004 \u0005[תשחט ולא תאכל ותשתה\u0006 יין, \u0005ותקרא כדי להתפכח מפחדך].\u0006","ושוב אמרו לו: \u0003אקרינן\u0004 \u0005[הקריאו לנו]\u0006 בחלומנו את הפסוק \u0003\"זרע רב תוציא השדה\u0004 ומעט תאסוף כי יחסלנו הארבה\" (דברים כח, לח) \u0003לאביי אמר ליה\u0004 \u0005[לו]\u0006 כהסבר \u0003מרישיה\u0004 \u0005[מתחילתו]\u0006 של הפסוק, כלומר, שתתקיים בו תחילת הפסוק, ואילו \u0003לרבא אמר ליה\u0004 \u0005[לו]\u0006 כהסבר \u0003מסיפיה\u0004 \u0005[מסופו]\u0006 של הפסוק, שיתקיים בו סופו.","ושוב אמרו לו: \u0003אקרינן\u0004 \u0005[הקריאו לנו]\u0006 בחלומנו את הפסוק \u0003\"זיתים יהיו לך בכל גבולך\u0004 ושמן לא תסוך כי ישל זיתך\" (שם מ), ושוב \u0003לאביי אמר ליה\u0004 \u0005[לו]\u0006 כפתרון \u0003מרישיה\u0004 \u0005[מתחילתו]\u0006 של הפסוק, ואילו \u0003לרבא אמר ליה\u0004 \u0005[לו]\u0006 כפתרון \u0003מסיפיה\u0004 \u0005[מסופו].\u0006","ושוב אמרו לו: \u0003אקרינן\u0004 \u0005[הקריאו לנו]\u0006 בחלומנו את הפסוק \u0003\"וראו כל עמי הארץ\u0004 כי שם ה' נקרא עליך ויראו ממך\" (שם י), \u0003לאביי אמר ליה\u0004 \u0005[לו]\u0006 כפתרון: \u0003נפק\u0004 \u0005[יצא]\u0006 \u0003לך שמא דריש מתיבתא הוית\u0004 \u0005[שם שתהיה ראש ישיבה] ,\u0006 ו\u0003אימתך נפלת בעלמא\u0004 \u0005[תיפול על הכל].\u0006 ו\u0003לרבא אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בדיינא דמלכא אתבר, ומתפסת בגנבי, ודייני כולי עלמא\u0004 \u0005[אוצר המלך נפרץ, ותתפס ב\u0006אשמת \u0005גניבה, וידונו הכל]\u0006 \u0003קל וחומר מינך\u0004 \u0005[ממך],\u0006 שאם רבא העשיר והמיוחס נתפס באשמה זו, מה יעשו האחרים. ואכן \u0003למחר אתבר בדיינא דמלכא ואתו ותפשי ליה\u0004 \u0005[למחרת נפרץ אוצר המלך, ובאו ותפסו אותו],\u0006 את \u0003רבא.\u0004","\u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 עוד אביי ורבא: \u0003חזן חסא על פום דני\u0004 \u0005[ראינו חסה על פי החביות].\u0006 \u0003לאביי אמר ליה\u0004 \u0005[לו]\u0006 כפתרון: \u0003עיף\u0004 \u0005[יכפל]\u0006 \u0003עסקך כחסא\u0004 \u0005[כחסה]\u0006 שעליה רחבים ומקומטים. ואילו \u0003לרבא אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מריר\u0004 \u0005[מר]\u0006 יהיה \u0003עסקך כי חסא\u0004 \u0005[כמו\u0006 קלח \u0005החסה].\u0006","שוב \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003חזן בשרא על פום דני\u0004 \u0005[ראינו בשר על פי חביות].\u0006 \u0003לאביי אמר ליה\u0004 \u0005[לו]\u0006 כפתרון: \u0003בסים חמרך, ואתו כולי עלמא למזבן בשרא וחמרא מינך\u0004 \u0005[יינך יהא מבושם\u0006 ומתוק, \u0005ויבואו הכל לקנות בשר ויין ממך].\u0006 ואילו \u0003לרבא אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תקיף חמרך, ואתו כולי עלמא למזבן בשרא למיכל ביה\u0004 \u0005[יחמיץ יינך, וילכו הכל לקנות בשר כדי לטבל בו\u0006 בחומץ שלך את הבשר\u0005].\u0006","שוב \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003חזן חביתא דתלי בדיקלא\u0004 \u0005[ראינו חבית התלויה בדקל].\u0006 \u0003לאביי אמר ליה\u0004 \u0005[לו]\u0006 כפתרון: \u0003מדלי\u0004 \u0005[ירום]\u0006 \u0003עסקך כדיקלא\u0004 \u0005[כדקל].\u0006 ואילו \u0003לרבא אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חלי\u0004 \u0005[ימתק]\u0006 \u0003עסקך כתמרי\u0004 \u0005[כתמרים],\u0006 שהם זולים מאד בבבל, וכך תאלץ למכור את סחורתך.","שוב \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003חזן רומנא דקדחי אפום דני\u0004 \u0005[ראינו רימון המכה שורשים בפי החביות],\u0006 \u0003לאביי אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עשיק\u0004 \u0005[יתיקר]\u0006 \u0003עסקך כרומנא\u0004 \u0005[כרימון].\u0006 \u0003ולרבא אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קאוי\u0004 \u0005[יחמץ]\u0006 \u0003עסקך כרומנא\u0004 \u0005[כרימון].\u0006","עוד \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003חזן חביתא דנפל לבירא\u0004 \u0005[ראינו חבית שנפלה לבור].\u0006 \u0003לאביי אמר ליה\u0004 \u0005[לו]\u0006 כפתרון: \u0003מתבעי\u0004 \u0005[יבוקש]\u0006 \u0003עסקך, כדאמר\u0004 \u0005[כמו שאומר\u0006 הפתגם\u0005]\u0006 \u0003\"נפל פתא בבירא\u0004 \u0005[הלחם בבור]\u0006 \u0003ולא אשתכח\"\u0004 \u0005[נמצא],\u0006 כלומר הכל יחפשו אחר סחורתך ולא תימצא מרוב קונים. ואילו \u0003לרבא אמר ליה\u0004 \u0005[לו]\u0006 כפתרון: \u0003פסיד\u0004 \u0005[יפסיד]\u0006 \u0003עסקך ושדיא ליה לבירא\u0004 \u0005[וייזרק לבור].\u0006","\u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 עוד: \u0003חזינן בר חמרא דקאי אאיסדן\u0004 \u0005[ראינו עייר שעומד למראשותינו]\u0006 \u0003ונוער. לאביי אמר ליה\u0004 \u0005[לו]\u0006 כפתרון: \u0003מלכא הוית, וקאי\u0004 \u0005[מלך,\u0006 כלומר, ראש ישיבה, \u0005תהיה ויעמוד]\u0006 \u0003אמורא,\u0004 מתורגמן, \u0003עלך\u0004 \u0005[עליך]\u0006 להשמיע בקול רם את דרשתך. ואילו \u0003לרבא אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"פטר חמור\" גהיט מתפילך\u0004 \u0005[מחוק מן התפילין שלך].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003לדידי חזי לי, ואיתיה\u0004 \u0005[אני עצמי ראיתיו\u0006 בתפילין, \u0005וישנו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר הדיא: האות \u0003וא\"ו\u0004 של \u0003\"פטר חמור\" ודאי גהיט מתפילך\u0004 \u0005[מחוקה מהתפילין שלך].\u0006","\u0003לסוף אזל\u0004 \u0005[לבסוף הלך]\u0006 \u0003רבא לחודיה לגביה\u0004 \u0005[בעצמו אליו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לבר הדיא: \u0003חזאי דשא ברייתא דנפל\u0004 \u0005[ראיתי את הדלת החיצונית\u0006 של ביתי \u0005שנפלה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר הדיא: \u0003אשתך שכבא\u0004 \u0005[תמות],\u0006 שהיא שומרת הבית. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003חזאי ככי ושני דנתור\u0004 \u0005[ראיתי את שיני שנפלו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בנך ובנתך שכבן\u0004 \u0005[בניך ובנותיך ימותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003חזאי תרתי יוני דפרחן\u0004 \u0005[ראיתי שתי יונים שעפות].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תרי נשי מגרשת\u0004 \u0005[שתי נשים תגרש].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003חזאי תרי גרגלידי דלפתא\u0004 \u0005[ראיתי שני ראשי לפתות].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תרין קולפי בלעת\u0004 \u0005[שתי\u0006 מכות של \u0005ראש אלה,\u0006 הדומה ללפת, \u0005תקבל].\u0006 \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רבא ההוא יומא ויתיב בי מדרשא כוליה יומא\u0004 \u0005[באותו יום וישב בבית המדרש כל היום].\u0006 \u0003אשכח הנהו תרי סגי נהורי דהוו קמנצו בהדי הדדי\u0004 \u0005[מצא שני עיוורים שהיו מתקוטטים זה עם זה].\u0006 \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רבא לפרוקינהו, ומחוהו\u0004 \u0005[להפריד ביניהם, והכוהו]\u0006 את \u0003רבא תרי\u0004 \u0005[שתי]\u0006 מכות. כאשר \u0003דלו למחוייה אחריתי\u0004 \u0005[הרימו\u0006 מקלותיהם \u0005להכותו\u0006 מכה \u0005אחרת,\u0006 נוספת\u0005],\u0006 \u0003אמר: מסתיי, תרין חזאי\u0004 \u0005[מספיק לי,\u0006 רק \u0005שתים ראיתי].\u0006","\u0003לסוף אתא\u0004 \u0005[לבסוף בא]\u0006 \u0003רבא ויהיב ליה אגרא\u0004 \u0005[ונתן לו\u0006 לבר הדיא \u0005שכר].\u0006 ואז \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לבר הדיא: \u0003חזאי אשיתא דנפל\u0004 \u0005[ראיתי את חומתי שנפלה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר הדיא כפתרון: \u0003נכסים בלא מצרים קנית\u0004 (תקנה). \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003חזאי אפדנא\u0004 \u0005[ראיתי\u0006 את \u0005ביתו]\u0006 של \u0003אביי\u0004 ש\u0003נפל וכסיין אבקיה\u0004 \u0005[ומכסה אותי אבקו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר הדיא: \u0003אביי שכיב\u0004 \u0005[ימות]\u0006 \u0003ומתיבתיה אתיא לגבך\u0004 \u0005[וישיבתו תבוא אצלך,\u0006 תעבור אליך\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003חזאי אפדנא דידי\u0004 \u0005[ראיתי\u0006 את \u0005ביתי שלי]\u0006 \u0003דנפיל\u0004 \u0005[שנפל],\u0006 \u0003ואתו כולי עלמא שקיל לבינתא לבינתא\u0004 \u0005[ובאים הכל ולוקחים לבינה לבינה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שמעתתך מבדרן בעלמא\u0004 \u0005[הלכותיך יהיו מפוזרות בעולם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003חזאי דאבקע רישי ונתר מוקרי\u0004 \u0005[ראיתי שנבקע ראשי ויצא מוחי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אודרא מבי סדיא נפיק\u0004 \u0005[נוצה יצאה מן הכר\u0006 שלראשך\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003אקריון הללא מצראה בחלמא\u0004 \u0005[הקריאו לי את ההלל המצרי,\u0006 הלל שאומרים על יציאת מצרים, \u0005בחלומי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נסי מתרחשי\u0004 \u0005[נסים יתרחשו]\u0006 \u0003לך.\u0004","\u0003הוה אזיל בהדיה בארבא\u0004 \u0005[היה הולך אתו,\u0006 בר הדיא עם רבא, \u0005בספינה].\u0006 \u0003אמר\u0004 בר הדיא: \u0003בהדי גברא דמתרחיש ליה ניסא\u0004 \u0005[עם אדם שמתרחשים לו נסים]\u0006 \u0003למה לי\u0004 ללכת, שמא יהיה הנס שתטבע הספינה והוא לבדו ינצל. \u0003בהדי דקא סליק\u0004 \u0005[תוך שהיה עולה]\u0006 \u0003נפל סיפרא מיניה\u0004 \u0005[ספר ממנו]\u0006 מבר הדיא. \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003רבא\u0004 לאותו ספר \u0003וחזא דהוה כתיב ביה\u0004 \u0005[וראה שהיה כתוב בו]\u0006 \u0003\"כל החלומות הולכין אחר הפה\". אמר\u0004 רבא לבר הדיא: \u0003רשע, בדידך קיימא, וצערתן כולי האי\u0004 \u0005[בשלך,\u0006 בידך, \u0005היה\u0006 הדבר, \u0005וצערתני כל כך].\u0006 \u0003כולהו מחילנא\u0004 \u0005[\u0006את \u0005הכל אני מוחל]\u0006 \u0003לך, בר מברתיה\u0004 \u0005[חוץ מבתו]\u0006 של \u0003רב חסדא\u0004 שהיתה אשתו של רבא, ובר הדיא התנבא עליה שתמות. \u0003יהא רעוא דלמסר ההוא גברא לידי דמלכותא דלא מרחמו עליה\u0004 \u0005[יהא רצון שימסר אותו האיש בידי מלכות שלא תרחם עליו].\u0006","\u0003אמר\u0004 בר הדיא בליבו: \u0003מאי אעביד\u0004 \u0005[מה אעשה]?\u0006 הלא \u0003גמירי\u0004 \u0005[למודים אנו]\u0006 ש\u0003קללת חכם אפילו\u0004 כשבאה \u0003בחנם, היא באה, וכל שכן רבא דבדינא קא לייט\u0004 \u0005[שבדין קילל\u0006 אותי\u0005].\u0006 \u0003אמר\u0004 לעצמו: \u0003איקום ואגלי\u0004 \u0005[אקום ואגלה],\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003גלות מכפרת עוון.\u0004","\u0003קם גלי לבי רומאי\u0004 \u0005[עמד\u0006 ו\u0005גלה לבית,\u0006 למקום השלטון של \u0005הרומאים].\u0006 \u0003אזל יתיב אפתחא דריש טורזינא דמלכא\u0004 \u0005[הלך וישב על פתחו של שומר בגדי המלך].\u0006 \u0003ריש טורזינא חזא חלמא\u0004 \u0005[שומר הבגדים חלם חלום].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שומר הבגדים לבר הדיא: \u0003חזאי חלמא דעייל מחטא\u0004 \u0005[ראיתי חלום שנכנסה,\u0006 דקרה, \u0005מחט]\u0006 את \u0003אצבעתי. אמר ליה\u0004 \u0005[לו]\u0006 בר הדיא: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי זוזא\u0004 \u0005[זוז],\u0006 \u0003ולא יהב ליה\u0004 \u0005[נתן לו].\u0006 \u0003לא אמר ליה\u0004 \u0005[לו]\u0006 בר הדיא \u0003ולא מידי\u0004 \u0005[דבר].\u0006 ושוב \u0003אמר ליה\u0004 \u0005[לו]\u0006 שומר הבגדים: \u0003חזאי\u0004 \u0005[ראיתי]\u0006 ש\u0003נפל,\u0004 כלומר, אוכלת \u0003תכלא בתרתין אצבעתי\u0004 \u0005[תולעת את שתי אצבעותי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי זוזא\u0004 \u0005[זוז],\u0006 \u0003ולא יהב ליה\u0004 \u0005[נתן לו],\u0006 \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 בר הדיא כלום. ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 השומר: \u0003חזאי\u0004 \u0005[ראיתי]\u0006 ש\u0003נפל,\u0004 כלומר, אוכלת \u0003תכלא בכולא ידא\u0004 \u0005[תולעת את כל ידי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר הדיא: \u0003נפל\u0004 (יאכלו) \u0003תכלא בכולהו שיראי\u0004 \u0005[התולעים את כל המשי].\u0006 \u0003שמעי בי מלכא, ואתיוה לריש טורזינא קא קטלי ליה\u0004 \u0005[שמעו בית המלך, והביאו את שומר הבגדים להרוג אותו].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא אמאי\u0004 \u0005[אני, מדוע]?\u0006 \u0003אייתו להאי דהוה ידע\u0004 \u0005[הביאו את זה שהיה יודע]\u0006 \u0003ולא אמר. אייתוהו\u0004 \u0005[הביאוהו]\u0006 את \u0003בר הדיא, אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003אמטו זוזא דידך חרבו\u0004 \u0005[בגלל הזוז שלך התקלקלו]\u0006"],["\u0003שיראי דמלכא\u0004 \u0005[מעילי המלך]!\u0006 \u0003כפיתו תרין ארזי בחבלא\u0004 \u0005[קשרו שני ארזים בחבל],\u0006 \u0003אסור חד כרעיה לחד ארזא וחד כרעיה לחד ארזא\u0004 \u0005[קשרו רגל אחת לארז אחד ורגל אחת,\u0006 האחרת, \u0005לארז אחד,\u0006 אחר\u0005],\u0006 \u0003ושרו לחבלא עד דאצטליק רישיה\u0004 \u0005[והתירו את החבל עד שיתפצל ראשו].\u0006 \u0003אזל כל חד וחד וקם אדוכתיה ואצטליק ונפל בתרין\u0004 \u0005[הלך כל אחד ואחד,\u0006 כל חלק וחלק \u0005ועמד במקומו והתפצל ונפל בשתים].\u0006","סיפור אחר ביחס לחכם שהיה פותר חלומות מספרים על ר' ישמעאל. ש\u0003שאל בן דמא בן אחותו של ר' ישמעאל את ר' ישמעאל\u0004 דודו: \u0003ראיתי\u0004 בחלום על \u0003שני לחיי שנשרו,\u0004 מהו פתרון חלומי? \u0003אמר\u0004 לו ר' ישמעאל: \u0003שני גדודי רומי יעצו עליך רעה, ומתו,\u0004 שהלחיים מסמלים פה שדיבר רע.","בדומה מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בר קפרא לרבי: ראיתי\u0004 בחלום את \u0003חוטמי שנשר,\u0004 מהו פתרון חלומי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 הרי זה מרמז ש\u0003חרון אף נסתלק ממך.\u0004 הוסיף ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 בר קפרא: \u0003ראיתי\u0004 בחלום את \u0003שני ידי שנחתכו. אמר ליה\u0004 \u0005[לו]\u0006 רבי: פתרון חלומך הוא ש\u0003לא תצטרך למעשה ידיך,\u0004 שתהיה עשיר ותהיה פרנסתך ברווח גם בלא מאמץ. עוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר קפרא: \u0003ראיתי שני רגלי שנקטעו. אמר ליה\u0004 \u0005[לו]\u0006 רבי כפתרון לחלומו: \u0003על סוס אתה רוכב.\u0004 הוסיף ואמר לו: \u0003חזאי דאמרי\u0004 \u0005[ראיתי שאומרים]\u0006 \u0003לי ב\u0004חודש \u0003אדר מיתת\u0004 \u0005[תמות]\u0006 \u0003ו\u0004את \u0003ניסן לא חזית\u0004 \u0005[תראה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003באדרותא מיתת\u0004 \u0005[בהדר תמות]\u0006 \u0003ולא אתית\u0004 \u0005[תבוא]\u0006 \u0003לידי נסיון.\u0004","על פתרון חלומות בדרך אחרת מסופר: \u0003אמר ליה ההוא\u0004 \u0005[לו אותו]\u0006 \u0003מינא\u0004 \u0005[מין]\u0006 \u0003לר' ישמעאל: ראיתי\u0004 בחלומי \u0003שאני משקה שמן לזיתים,\u0004 מהו פתרון חלומי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 סימן הוא שאותו אדם \u0003בא על אמו,\u0004 שהרי השמן בא מן הזית והוא מחזיר השמן לזיתים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו מין: \u0003חזאי דקטיף לי כוכבא\u0004 \u0005[ראיתי שאני קוטף כוכב].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בר\u0004 \u0005[בן]\u0006 \u0003ישראל גנבת,\u0004 שנמשלו ישראל לכוכבים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 המין: \u0003חזאי\u0004 \u0005[ראיתי]\u0006 ש\u0003בלעתי לכוכבא\u0004 \u0005[את הכוכב].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בר\u0004 \u0005[בן]\u0006 \u0003ישראל זבנתיה\u0004 \u0005[מכרת]\u0006 \u0003ואכלת לדמיה\u0004 \u0005[את כספו],\u0006 הכסף שקבלת בעדו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 המין: \u0003חזאי\u0004 \u0005[ראיתי]\u0006 את \u0003עיני דנשקן אהדדי\u0004 \u0005[ש\u0006הן \u0005נושקות זו לזו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אותו אדם \u0003בא על אחותו,\u0004 שהיא והוא כשתי עינים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 המין: \u0003חזאי דנשקי סיהרא\u0004 \u0005[ראיתי שאני נושק את הירח].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אותו אדם \u0003בא על אשת ישראל\u0004 שנמשלה לירח. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזאי דדריכנא בטונא דאסא\u0004 \u0005[ראיתי שאני דורך במיטה של הדס].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בא על נערה המאורסה,\u0004 שרגילים היו לעשות לה בשעת אירוסין חופת הדסים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזאי טונא מעילאי והוא מתתאי\u0004 \u0005[ראיתי שהמיטה מעלי, והוא,\u0006 אני, \u0005מתחתיה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משכבך הפוך. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזאי עורבי דהדרי לפורייה\u0004 \u0005[ראיתי עורבים שמסתובבים מסביב למיטתי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אשתך זנתה מאנשים הרבה. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזאי יוני דהדרי לפורייה\u0004 \u0005[ראיתי יונים הסובבות את מיטתי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נשים הרבה טמאת. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזאי דנקיט תרי יוני ופרחן\u0004 \u0005[ראיתי שאני מחזיק שתי יונים ו\u0006הן \u0005פורחות].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תרתי נשי נסבת ופטרתינון\u0004 \u0005[שתי נשים נשאת ופטרתן\u0006 מביתך\u0005]\u0006 \u0003בלא גט.\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזאי דקליפנא ביעי\u0004 \u0005[ראיתי שאני קולף ביצים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שכבי קא משלחת\u0004 \u0005[מתים אתה מפשיט],\u0006 שהביצה נאכלת בסעודת הבראה על המת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו מין: \u0003כולהו\u0004 \u0005[כל\u0006 מה שפתרת\u0005]\u0006 אכן \u0003איתנהו\u0004 \u0005[יש]\u0006 \u0003בי, לבר מהא\u0004 \u0005[חוץ מזה\u0006 הפתרון האחרון\u0005]\u0006 \u0003דליתא\u0004 \u0005[שאין]\u0006 בי. \u0003אדהכי והכי אתיא האי איתתא\u0004 \u0005[בין כה וכה באה אשה אחת]\u0006 \u0003ואמרה ליה\u0004 \u0005[לו]:\u0006 \u0003האי גלימא דמכסא\u0004 — \u0003דגברא פלוני הוא, דמית ואשלחתיה\u0004 \u0005[גלימה זו שאתה מתכסה\u0006 בה — \u0005של אדם פלוני היא, שמת והפשטת אותו].\u0006","המשיך ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 המין לר' ישמעאל: \u0003חזאי דאמרי\u0004 \u0005[ראיתי שאמרו]\u0006 \u0003לי\u0004 בחלום: \u0003שבק\u0004 \u0005[הניח]\u0006 \u0003לך אבוך נכסי\u0004 \u0005[אביך נכסים]\u0006 \u0003בקפודקיא. אמר ליה\u0004 \u0005[לו]\u0006 ר' ישמעאל: האם \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך נכסי\u0004 \u0005[נכסים]\u0006 \u0003בקפודקיא?\u0004 האם \u0003אזל אבוך\u0004 \u0005[הלך אביך]\u0006 \u0003לקפודקיא? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו\u0004 \u0005[לא].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם כן,\u0004 יש להבין כך: \u0003קפא\u0004 ביוונית הוא \u0003כשורא\u0004 \u0005[קורה],\u0006 \u0003דיקא\u0004 הוא ביוונית \u0003עשרה. זיל חזי קפא דריש עשרה\u0004 \u0005[ראה\u0006 את הקורה העשירית] בביתך \u0003שהיא מלאה זוזי\u0004 \u0005[זוזים,\u0006 כסף\u0005].\u0006 \u0003אזל אשכח\u0004 \u0005[הלך ומצא]\u0006 \u0003שהיא מלאה זוזי\u0004 \u0005[זוזים].\u0006","ומכאן ואילך פתרונות לפרטי חלומות. \u0003אמר ר' חנינא: הרואה באר בחלום\u0004 — \u0003רואה שלום, שנאמר \"ויחפרו עבדי יצחק בנחל וימצאו שם באר מים חיים\"\u0004 (בראשית כו, יט), וסופה היה שלום. \u0003ר' נתן אומר:\u0004 הרואה באר בחלומו סימן הוא כי \u0003מצא תורה,\u0004 שהבאר מסמלת תורה, ומנין למד אתה זאת — \u0003שנאמר\u0004 על התורה \u0003\"כי מצאי מצא חיים\"\u0004 (משלי ח, לה), \u0003וכתיב הכא\u0004 \u0005[ונאמר כאן]\u0006 \u0003\"באר מים חיים\",\u0004 והרי ש\"חיים\" הם תורה. \u0003רבא אמר:\u0004 הבאר מסמלת \u0003חיים ממש.\u0004","\u0003אמר ר' חנן: שלש שלומות הן,\u0004 ששלושה דברים הנראים בחלום מרמזים לשלום: \u0003נהר, צפור, וקדרה.\u0004 ומפרטים: \u0003נהר\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הנני נטה אליה כנהר שלום\"\u0004 (ישעיהו סו, יב). \u0003צפור\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כצפרים עפות כן יגן ה' צבאות\u0004 על ירושלים\" וגו' (שם לא, ה). \u0003קדרה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ה' תשפת שלום לנו\"\u0004 (שם כו, יב), שהשלום מדומה בפסוק זה כקדרה ששופתים אותה על האש. ו\u0003אמר ר' חנינא: ו\u0004דווקא \u0003בקדרה שאין בה בשר שנינו\u0004 כאן. שקדרה שיש בה בשר מסמלת פורענות, וכפי שנאמר: \u0003\"ופרשו כאשר בסיר וכבשר בתוך קלחת\"\u0004 (מיכה ג, ג).","מאחר ובכתובים יש דברים להם שתי משמעויות, לטוב ולרע, לכן \u0003אמר ר' יהושע בן לוי\u0004 שכל הרואה בחלום דבר שיש לו משמעות כפולה, ימהר ויאמר את הפסוק הקשור לאותו דבר והוא בעל משמעות טובה. וכגון: \u0003הרואה נהר בחלום, ישכים ויאמר\u0004 את הפסוק המפרשו לטובה: \u0003\"הנני נטה אליה כנהר שלום\", קודם שיקדמנו\u0004 בהתגשמות \u0003פסוק אחר\u0004 המשתמש לרע בסמל זה, והוא \u0003\"כי יבא כנהר צר\"\u0004 (ישעיהו נט יט). \u0003הרואה צפור בחלום, ישכים ויאמר \"כצפרים עפות כן יגן\u0004 ה' צבאות על ירושלים\", \u0003קודם שיקדמנו\u0004 בהתגשמות \u0003פסוק אחר \"כצפור נודדת מן קנה\u0004 כן איש נודד ממקומו\" (משלי כז, ח). \u0003הרואה קדרה בחלום, ישכים ויאמר\u0004 \"ויאמר \u0003ה' תשפת שלום לנו\" קודם שיקדמנו\u0004 בהתגשמות \u0003פסוק אחר \"שפת הסיר שפת\"\u0004 (יחזקאל כד, ג) המסיים שם בנבואת זעם.","\u0003הרואה ענבים בחלום, ישכים ויאמר \"כענבים במדבר\u0004 מצאתי אבותיכם\u0003\"\u0004 (הושע ט, י), \u0003קודם שיקדמנו\u0004 בהתגשמות \u0003פסוק אחר \"ענבמו ענבי רוש\u0004 אשכלות מרורות למו\" (דברים לב, לב). \u0003הרואה הר בחלום, ישכים ויאמר \"מה נאוו על ההרים רגלי מבשר\u0004 משמיע שלום מבשר טוב משמיע ישועה\" (ישעיהו נב, ז) \u0003קודם שיקדמנו\u0004 בהתגשמות \u0003פסוק אחר \"על ההרים אשא בכי ונהי\"\u0004 (ירמיהו ט, ט).","\u0003הרואה שופר בחלום, ישכים ויאמר \"והיה ביום ההוא יתקע בשופר גדול\u0004 ובאו האובדים בארץ אשור והנדחים בארץ מצרים\" (ישעיהו כז, יג), \u0003קודם שיקדמנו\u0004 בהתגשמות \u0003פסוק אחר \"תקעו שופר בגבעה\"\u0004 (הושע ה, ח) כסמל מלחמה.","\u0003הרואה כלב בחלום, ישכים ויאמר \"ולכל בני ישראל לא יחרץ כלב לשנו\"\u0004 (שמות יא, ז) \u0003קודם שיקדמנו\u0004 בהתגשמות \u0003פסוק אחר: \"והכלבים עזי נפש\"\u0004 (ישעיהו נו, יא). \u0003הרואה ארי בחלום, ישכים ויאמר \"אריה שאג מי לא יירא\u0004 ה' אלהים דבר מי לא ינבא\u0003\"\u0004 (עמוס ג, ח) \u0003קודם שיקדמנו\u0004 בהתגשמות \u0003פסוק אחר \"עלה אריה מסבכו\u0004 ומשחית גוים נסע יצא ממקומו\" (ירמיהו ד, ז).","\u0003הרואה תגלחת בחלום, ישכים ויאמר \"ויגלח ויחלף שמלתיו\"\u0004 (בראשית מא, יד), שכן נאמר ביוסף כשיצא מבית הסוהר ועלה לגדולה, \u0003קודם שיקדמנו\u0004 בהתגשמות \u0003פסוק אחר\u0004 שנאמר בשמשון \u0003\"כי אם גלחתי וסר ממני כחי\u0004 וחליתי\" (שופטים טז, יז). \u0003הרואה באר בחלום, ישכים ויאמר \"באר מים חיים\"\u0004 (שיר השירים ד, טו) \u0003קודם שיקדמנו\u0004 בהתגשמות \u0003פסוק אחר \"כהקיר ביר מימיה\u0004 כן הקרה רעתה\" (ירמיהו ו, ז). \u0003הרואה קנה בחלום, ישכים ויאמר \"קנה רצוץ לא ישבור\"\u0004 (ישעיהו מב, ג) האמור בשבחו של המשיח, \u0003קודם שיקדמנו\u0004 בהתגשמות \u0003פסוק אחר \"הנה בטחת לך על משענת הקנה הרצוץ\"\u0004 (מלכים ב' יח, כא).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרואה קנה בחלום\u0004 — \u0003יצפה לחכמה, שנאמר: \"קנה חכמה\"\u0004 (משלי ד, ז). הרואה \u0003קנים\u0004 — \u0003יצפה לבינה, שנאמר: \"ובכל קנינך קנה בינה\"\u0004 (שם). הוסיף ו\u0003אמר ר' זירא: קרא\u0004 \u0005[דלעת],\u0006 \u0003קורא\u0004 \u0005[קור הדקל],\u0006 \u0003קירא\u0004 \u0005[שעוה]\u0006 ו\u0003קניא\u0004 \u0005[קנה]\u0006 — \u0003כולהו מעלו לחלמא\u0004 \u0005[כולם מעולים\u0006 יפים, \u0005לחלום],\u0006 כשאדם חולם עליהם. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין מראין דלועין\u0004 בחלום \u0003אלא למי שהוא ירא שמים בכל כחו.\u0004 שדלועים נדרשים כקיצור \"דלו עיני למרום\" (ישעיהו לח, יד).","\u0003הרואה שור בחלום, ישכים ויאמר \"בכור שורו הדר לו\"\u0004 (דברים לג, יז) \u0003קודם שיקדמנו\u0004 בהתגשמות \u0003פסוק אחר\u0004 \"ו \u0003כי יגח שור את איש\"\u0004 (שמות כא, כח).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003חמשה דברים נאמרו\u0004 בחלומות הקשורים \u0003בשור. ה\u0004חולם ש\u0003אוכל מבשרו\u0004 — \u0003מתעשר.\u0004 החולם ש\u0003נגחו\u0004 — \u0003הויין\u0004 \u0005[יהיו]\u0006 \u0003ליה\u0004 \u0005[לו]\u0006 \u0003בנים\u0004 תלמידי חכמים \u0003שמנגחים בתורה. אם\u0004 ראה בחלום ש\u0003נשכו\u0004 השור — \u0003יסורין באים עליו.\u0004 חלם ש\u0003בעטו\u0004 השור — \u0003דרך רחוקה נזדמנה לו\u0004 ללכת בעתיד. ראה ש\u0003רכבו\u0004 — סימן הוא שיהא \u0003עולה לגדולה.\u0004","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שאם ראה ש\u0003רכבו\u0004 — הרי זה סימן לכך שהוא \u0003מת!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שהוא עולה לגדולה הרי זה באופן שראה בחלום \u0003דרכיב\u0004 \u0005[שרוכב]\u0006 \u0003הוא לתורא\u0004 \u0005[על השור].\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שזהו סימן למיתתו הקרובה, הרי זה באופן שראה \u0003דרכיב תורא לדידיה\u0004 \u0005[שרוכב השור עליו].\u0006","\u0003הרואה חמור בחלום\u0004 — \u0003יצפה לישועה, שנאמר \"הנה מלכך יבוא לך צדיק ונושע הוא עני ורכב על חמור\"\u0004 (זכריה ט, ט). \u0003הרואה חתול בחלום\u0004 — \u0003באתרא דקרו ליה\u0004 \u0005[במקום שקוראים לו]\u0006 בארמית \u0003\"שונרא\"\u0004 — \u0003נעשית לו שירה נאה.\u0004 ובמקום קוראים לחתול \u0003\"שינרא\"\u0004 — סימן הוא ש\u0003נעשה לו שינוי רע. הרואה ענבים בחלום,\u0004 אם ראה ענבים \u0003לבנות,\u0004 כלומר, בהירות, \u0003בין\u0004 שראה אותם \u0003בזמנן\u0004 שהיא עונת הבשלת ענבים אלה, \u0003ובין שלא בזמנן\u0004 — \u0003יפות\u0004 הן לו. ואם ראה ענבים \u0003שחורות\u0004 רק אם ראה אותם \u0003בזמנן\u0004 — \u0003יפות.\u0004 ואולם אם ראה אותם \u0003שלא בזמנן\u0004 — \u0003רעות. הרואה סוס לבן בחלום, בין\u0004 שהיה הסוס מהלך \u0003בנחת, בין ברדוף\u0004 (ממהר) — סימן \u0003יפה לו.\u0004 ואולם אם ראה סוס \u0003אדום, בנחת\u0004 — סימן \u0003יפה, ברדוף\u0004 — \u0003קשה.\u0004","אמרו: \u0003הרואה ישמעאל בחלום\u0004 — סימן הוא כי \u0003תפלתו\u0004 תהא \u0003נשמעת,\u0004 כשם שנשמעה תפילתו של ישמעאל. ומעירים: \u0003ודוקא\u0004 כשראה את \u0003ישמעאל בן אברהם, אבל טייעא בעלמא\u0004 \u0005[סתם ערבי]\u0006 — \u0003לא,\u0004 אינו סימן יפה. \u0003הרואה גמל בחלום\u0004 — סימן הוא ש\u0003מיתה נקנסה לו מן השמים והצילוהו ממנה. אמר ר' חמא בר' חנינא: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המרמז על דבר זה — \u0003\"ואנכי ארד עמך מצרימה ואנכי אעלך גם עלה\"\u0004 (בראשית מו, ד), \"גם עלה\" נדרש כהרחבה של \"גמל\". \u0003רב נחמן בר יצחק אמר:\u0004 המקור לדבר הוא \u0003מהכא\u0004 \u0005[מכאן]\u0006 מפסוק אחר: \u0003\"גם ה' העביר חטאתך לא תמות\"\u0004 (שמואל ב' יב, יג).","\u0003הרואה פינחס בחלום\u0004 — הרי זה סימן כי \u0003פלא נעשה לו,\u0004 כדרך שנעשו ניסים לפנחס. \u0003הרואה פיל בחלום\u0004 — הרי זה סימן כי \u0003פלאות נעשו לו\u0004 (מקירבת המלים פיל—פלא). והרואה \u0003פילים\u0004 בחלום — \u0003פלאי פלאות נעשו לו.\u0004","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003כל מיני חיות יפין לחלום,\u0004 כשאדם חולם עליהם \u0003חוץ מן הפיל ומן הקוף!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006"],["\u0003הא\u0004 \u0005[זה]\u0006 ששנינו שסימן יפה, הרי זה באופן שראהו \u0003דמסרג\u0004 \u0005[ש\u0006הוא \u0005חבוש אוכף],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שראיית פיל אינה סימן יפה, הרי זה באופן \u0003דלא מסרג\u0004 \u0005[כשאינו חבוש אוכף].\u0006 ועוד: \u0003הרואה\u0004 אדם ששמו \u0003הונא בחלום\u0004 — סימן הוא ש\u0003נס נעשה לו,\u0004 שהאות נ' בשם הונא היא קיצור המלה \"נס\". והרואה אדם ששמו \u0003חנינא, חנניא,\u0004 או \u0003יוחנן\u0004 — הרי זה סימן כי \u0003נסי נסים נעשו לו\u0004 שהרי יש פעמיים נ' בשמות אלה. \u0003הרואה הספד בחלום\u0004 — סימן הוא ש\u0003מן השמים חסו עליו ופדאוהו\u0004 שלא יצטרכו להספידו במציאות. \u0003ו\u0004אולם מגבילים זאת ואומרים כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא כשראה את ההספד \u0003בכתבא\u0004 \u0005[בכתב],\u0006 כלומר, שעדיין לא השתמשו בהספד.","\u0003העונה\u0004 בחלום \u0003\"יהא שמיה רבא מברך\"\u0004 — \u0003מובטח לו שהוא בן העולם הבא. ה\u0004רואה ש\u0003קורא קריאת שמע בחלום\u0004 — \u0003ראוי\u0004 הוא \u0003שתשרה עליו שכינה, אלא שאין דורו זכאי לכך,\u0004 ולכן אין השכינה שורה עליו בפועל.","\u0003ה\u0004רואה ש\u0003מניח תפילין בחלום\u0004 — \u0003יצפה לגדולה,\u0004 וכפי \u0003שנאמר: \"וראו כל עמי הארץ כי שם ה' נקרא עליך\u0004 ויראו ממך\u0003\"\u0004 (דברים כח, י). \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר הגדול אומר:\u0004 \"כי שם ה' נקרא עליך\" \u0003אלו תפילין שבראש,\u0004 שהם שם ה' המצוי על האדם. \u0003ה\u0004רואה ש\u0003מתפלל בחלום\u0004 — \u0003סימן יפה\u0004 הוא \u0003לו. ו\u0004אולם מגבילים זאת ואומרים כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא באופן שרואה בחלום שעדיין \u0003לא סיים\u0004 תפילתו, ועדיין קרוב הוא אצל הקדוש ברוך הוא, אבל אם ראה שכבר סיים הרי כבר אינו מתפלל, ושוב אין לו סימן.","ועוד: \u0003ה\u0004רואה ש\u0003בא על אמו בחלום\u0004 — \u0003יצפה לבינה, שנאמר: \"כי אם לבינה תקרא\"\u0004 (משלי ב, ג), ודורשים \"אם\" כמו \"אם\". \u0003הבא\u0004 בחלום \u0003על נערה מאורסה\u0004 — \u0003יצפה לתורה, שנאמר: \"תורה צוה לנו משה מורשה קהלת יעקב\"\u0004 (דברים לג, ד), ו\u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"מורשה\" אלא \"מאורשה\". הבא על אחותו בחלום\u0004 — \u0003יצפה לחכמה, שנאמר: \"אמר לחכמה אחתי את\"\u0004 (משלי ז, ד). \u0003הבא על אשת איש בחלום\u0004 — \u0003מובטח לו שהוא בן העולם הבא,\u0004 ונוטל חלקו וחלק חבירו בגן עדן, שיש בכך דמיון לאשת איש. \u0003ו\u0004אולם מגבילים זאת ואומרים כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא באופן ש\u0003לא ידע לה\u0004 \u0005[הכיר אותה]\u0006 \u0003ולא הרהר בה מאורתא\u0004 \u0005[מבערב],\u0006 אלא ראה אותה בחלום באופן אקראי.","\u0003אמר ר' חייא בר אבא: הרואה חטים בחלום\u0004 — סימן הוא כי \u0003ראה שלום, שנאמר: \"השם גבולך שלום חלב חטים ישביעך\"\u0004 (תהלים קמז, יד). ו\u0003הרואה שעורים בחלום\u0004 — סימן הוא כי \u0003סרו עונותיו, שנאמר: \"וסר עונך וחטאתך תכפר\"\u0004 (ישעיהו ו, ז), ש\"שעורים\" נדרש כקיצור של \"סר עוון\". \u0003אמר ר' זירא: אנא\u0004 \u0005[אני]\u0006 \u0003לא סלקי\u0004 \u0005[עליתי]\u0006 \u0003מבבל לארץ ישראל עד דחזאי שערי בחלמא\u0004 \u0005[שראיתי שעורים בחלום].\u0006","\u0003הרואה גפן טעונה\u0004 ענבים \u0003בחלום\u0004 — סימן הוא ש\u0003אין אשתו מפלת נפלים, שנאמר: \"אשתך כגפן פריה\u0004 בירכתי ביתך\" (תהלים קכח, ג). והרואה \u0003שורקה,\u0004 כלומר, ענף גפן נטוע — \u0003יצפה למשיח, שנאמר: \"אסרי לגפן עירה, ולשרקה בני אתנו\"\u0004 (בראשית מט, יא).","\u0003הרואה תאנה בחלום\u0004 — סימן הוא ש\u0003תורתו משתמרת בקרבו, שנאמר: \"נוצר תאנה יאכל פריה\"\u0004 (משלי כז, יח). \u0003הרואה רמונים בחלום,\u0004 אם היו \u0003זוטרי\u0004 \u0005[קטנים]\u0006 — \u0003פרי עסקיה כרמונא\u0004 \u0005[יפרח\u0006 וירבה \u0005עסקו כ\u0006גרעיני ה\u0005רימון],\u0006 ואם היו \u0003רברבי\u0004 \u0005[גדולים]\u0006 — הרי זה סימן כי \u0003רבי עסקיה כרמונא\u0004 \u0005[יגדל עיסקו כרימון].\u0006 ואם ראה בחלומו \u0003פלגי\u0004 \u0005[פלחי\u0006 רימונים\u0005],\u0006 \u0003אם תלמיד חכם הוא\u0004 החולם — \u0003יצפה לתורה, שנאמר: \"אשקך מיין הרקח מעסיס רמני\"\u0004 (שיר השירים ח, ב) המקובל כרמז לתורה. \u0003ואם עם הארץ הוא\u0004 החולם — \u0003יצפה למצות, שנאמר: \"כפלח הרמון רקתך\"\u0004 (שם ד, ג), וכבר דרשו: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות המלה \u0003\"רקתך\"\u0004 — לומר ש\u0003אפילו ריקנין שבך,\u0004 בעם ישראל, \u0003מלאים מצות כרמון.\u0004","\u0003הרואה זיתים בחלום,\u0004 אם היו \u0003זוטרי\u0004 \u0005[קטנים]\u0006 — סימן הוא כי \u0003פרי ורבי וקאי עסקיה\u0004 \u0005[יפרה וירבה ויעמוד,\u0006 יתקיים \u0005עסקו]\u0006 \u0003כזיתים. ו\u0004אולם מגבילים זאת ואומרים כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא כשרואה \u0003פרי\u0004 הזית, \u0003אבל\u0004 אם רואה \u0003אילני\u0004 \u0005[אילנות]\u0006 הזית — סימן הוא כי \u0003הויין ליה\u0004 \u0005[יהיו לו]\u0006 \u0003בנים מרובין, שנאמר: \"בניך כשתלי זיתים\u0004 סביב לשולחנך\u0003\"\u0004 (תהלים קכח, ג). \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003הרואה זית בחלום\u0004 — סימן הוא כי \u0003שם טוב יוצא לו, שנאמר: \"זית רענן יפה פרי תאר קרא ה' שמך\"\u0004 (ירמיהו יא, טז). \u0003הרואה שמן זית בחלום\u0004 — \u0003יצפה למאור תורה, שנאמר \"ויקחו אליך שמן זית זך\". הרואה תמרים בחלום\u0004 — סימן הוא כי \u0003תמו עונותיו, שנאמר: \"תם עונך בת ציון\"\u0004 (איכה ד, כב), שנדרש תמרה כמו תם רע.","\u0003אמר רב יוסף, הרואה עז בחלום\u0004 — סימן הוא כי \u0003שנה מתברכת לו, עזים\u0004 — \u0003שנים מתברכות לו, שנאמר: \"ודי חלב עזים ללחמך\u0004 ללחם ביתך וחיים לנערותיך\" (משלי כז, כז). \u0003הרואה הדס בחלום\u0004 — סימן הוא כי \u0003נכסיו מצליחין לו. ואם אין לו נכסים\u0004 — הרי זה סימן כי \u0003ירושה נופלת לו ממקום אחר. אמר עולא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי \u0003במתניתא תנא\u0004 \u0005[בברייתא\u0006 היא \u0005שנוייה]:\u0006 \u0003והוא\u0004 דווקא באופן \u0003דחזא בכנייהו\u0004 \u0005[שראה\u0006 אותם \u0005צומחים].\u0006 \u0003הרואה אתרוג בחלום\u0004 — סימן הוא כי \u0003הדור הוא לפני קונו, שנאמר\u0004 על אתרוג: \u0003\"פרי עץ הדר כפת תמרים\"\u0004 (ויקרא כג, מ). \u0003הרואה לולב בחלום\u0004 — סימן הוא ש\u0003אין לו אלא לב אחד לאביו שבשמים,\u0004 ונדרש \"לולב\" כמו \"לו לב\".","ועוד: \u0003הרואה אווז בחלום\u0004 — \u0003יצפה לחכמה שנאמר: \"חכמות בחוץ תרנה\u0004 ברחובות תתן קולה\" (משלי א, כ) והאווזים משמיעים קולם לרוב. \u0003וה\u0004חולם כי \u0003בא עליה,\u0004 על האווזה, והתקשר עימה על ידי כך — \u0003הוי\u0004 \u0005[יהיה]\u0006 \u0003ראש ישיבה.\u0004 ו\u0003אמר רב אשי: אני ראיתיה\u0004 את האווזה בחלום, \u0003ו\u0004ראיתי גם ש\u0003באתי עליה, וסלקית\u0004 \u0005[ועליתי]\u0006 \u0003לגדולה\u0004 של ראש ישיבה.","\u0003הרואה תרנגול בחלום\u0004 — \u0003יצפה לבן זכר. תרנגולים\u0004 — \u0003יצפה לבנים זכרים.\u0004 והרואה \u0003תרנגולת\u0004 — \u0003יצפה לתרביצה\u0004 \u0005[גינה]\u0006 \u0003נאה וגילה\u0004 ש\"תרנגולת\" נדרש כקיצור של \"תרביצה נאה וגילה\". \u0003הרואה ביצים בחלום\u0004 — \u0003תלויה בקשתו\u0004 שמבקש, שביצה היא בארמית \"ביעא\" הקרוב למשמעות בקשה. ואם חלם ש\u0003נשתברו\u0004 הביצים — הרי זה סימן כי \u0003נעשית\u0004 כבר \u0003בקשתו,\u0004 וכאילו נתגלה מה שהיה בתוך קליפה. \u0003וכן\u0004 משמעות חלום שרואה בו \u0003אגוזים, וכן\u0004 חלום שרואה בו \u0003קשואים, וכן כל כלי זכוכית, וכן כל הנשברים כאלו,\u0004 שאם חלם שנשבר דבר מה — סימן שנעשתה בקשתו.","\u0003ה\u0004חולם ש\u0003נכנס לכרך\u0004 — סימן הוא ש\u0003נעשו לו חפציו, שנאמר: \"וינחם אל מחוז חפצם\"\u0004 (תהלים קז, ל). \u0003המגלח ראשו בחלום\u0004 — \u0003סימן יפה לו,\u0004 שהוריד מעליו את השערות הממאיסות, והוא סימן של התחדשות וגדולה. ואם גלח בחלום \u0003ראשו וזקנו\u0004 — סימן יפה \u0003לו ולכל משפחתו.\u0004","\u0003היושב\u0004 בחלום \u0003בעריבה\u0004 (בסירה) \u0003קטנה\u0004 — הרי זה סימן כי \u0003שם טוב יוצא לו.\u0004 ואם רואה את עצמו בחלום יושב \u0003בעריבה גדולה\u0004 — סימן יפה \u0003לו ולכל משפחתו. ו\u0004אולם מגבילים זאת ואומרים כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא באופן \u0003דמדליה דלויי\u0004 \u0005[ש\u0006הסירה \u0005נמצאת בגובה\u0006 הגלים\u0005].\u0006","\u0003הנפנה\u0004 לצרכיו \u0003בחלום\u0004 — \u0003סימן יפה\u0004 הוא \u0003לו, שנאמר: \"מהר צעה להפתח\u0004 ולא ימות לשחת ולא יחסר לחמו\" (ישעיהו נא, יד). \u0003ו\u0004אולם מגבילים זאת ואומרים כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא באופן ש\u0003לא קנח\u0004 והתלכלך שוב.","\u0003העולה לגג בחלום\u0004 — סימן שהוא \u0003עולה לגדולה.\u0004 ראה בחלום שאחר שעלה שוב חזר ו\u0003ירד\u0004 מהגג — הרי זה סימן ש\u0003יורד\u0004 הוא \u0003מגדולתו.\u0004 ואילו \u0003אביי ורבא דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003כיון שעלה\u0004 — \u0003עלה\u0004 וסימן יפה הוא, גם אם חלם אחר כך שירד. \u0003הקורע בגדיו בחלום\u0004 — הרי זה סימן ש\u0003קורעים לו גזר דינו\u0004 הרע. וה\u0003עומד ערום בחלום,\u0004 אם חלם \u0003בבבל\u0004 — סימן הוא לו שהוא \u0003עומד בלא חטא,\u0004 שכן ישיבת חוץ לארץ היא עצמה עבירה, והעומד ערום פירושו שהוא מנוקה מאותה עבירה. ואם חלם \u0003בארץ ישראל\u0004 — סימן הוא לו שהוא \u0003ערום בלא מצות. ה\u0004חולם ש\u0003נתפס לסרדיוט,\u0004 כלומר, שחייל שומר אותו — סימן הוא ש\u0003שמירה נעשית לו\u0004 משמים. ואם ראה ש\u0003נתנוהו בקולר\u0004 (שמו שרשרת על צווארו) — סימן הוא כי \u0003הוסיפו לו שמירה על שמירתו,\u0004 שיש לו שמירה יתירה. \u0003ו\u0004אולם מגבילים זאת ואומרים כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא אם ראה בחלום שצווארו נתון \u0003בקולר, אבל\u0004 אם ראה שצווארו נתון ב\u0003חבלא בעלמא\u0004 \u0005[חבל בלבד]\u0006 — \u0003לא,\u0004 איננו סימן לשמירה מעולה.","\u0003הנכנס לאגם בחלום\u0004 — סימן הוא כי \u0003נעשה ראש ישיבה,\u0004 שכן בחלומו הוא רואה כאילו הוא עומד יחידי, וכל קני הסוף, הגדולים והקטנים, מסביבו כתלמידים. וכן הוא ראש הישיבה שכלל בני הישיבה מתקבצים סביבו לשמוע את דבריו. והחולם שנכנס \u0003ליער\u0004 ורואה מסביבו רק עצים גדולים — סימן הוא לו כי הוא \u0003נעשה ראש\u0004 רק \u0003לבני כלה,\u0004 שהוא רק מפרש את דברי הרב מוסר השיעור לתלמידי הישיבה הגדולים, שכל אחד מהם אילן גדול לעצמו ואינו קרוב אצל האחר.","ומסופר: כי \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע חזו חלמא\u0004 \u0005[ראו\u0006 כל אחד מהם \u0005חלום]:\u0006 \u0003רב פפא\u0004 שבחלומו ראה \u0003דעייל לאגמא\u0004 \u0005[ש\u0006הוא \u0005נכנס לאגם]\u0006 — \u0003נעשה\u0004 בסופו של דבר \u0003ראש ישיבה.\u0004 ו\u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 שבחלומו ראה \u0003דעייל\u0004 \u0005[ש\u0006הוא \u0005נכנס]\u0006 \u0003ליער\u0004 — \u0003נעשה ראש לבני כלה. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003תרווייהו לאגמא עיילי\u0004 \u0005[שניהם\u0006 חלמו \u0005שנכנסו לאגם],\u0006 אלא, \u0003רב פפא\u0004 שחלם \u0003דתלי טבלא\u0004 \u0005[שתלוי\u0006 בצווארו \u0005תוף]\u0006 — \u0003נעשה ראש ישיבה,\u0004 שהקשה בתוף סימן הוא לראש ישיבה שמשמיע קולו ברבים, ו\u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 ש\u0003לא תלי טבלא\u0004 \u0005[\u0006היה \u0005תלוי\u0006 בחלומו \u0005תוף\u0006 בצווארו\u0005]\u0006 — \u0003נעשה\u0004 רק \u0003ראש לבני כלה. אמר רב אשי: אנא עיילית לאגמא ותלאי טבלא ונבחי בה נבוחי\u0004 \u0005[אני\u0006 חלמתי ש\u0005נכנסתי לאגם ותליתי תוף והקשתי בו הקשות],\u0006 והרי היה רב אשי ראש ישיבה.","\u0003תני תנא קמיה\u0004 \u0005[שנה\u0006 אחד מ\u0005חוזרי המשניות לפני]\u0006 \u0003רב נחמן בר יצחק: המקיז דם בחלום\u0004 — סימן הוא כי \u0003עונותיו מחולין לו,\u0004 שהעוון נמשל תמיד לאדום כצבע הדם (\"אם יהיו עוונותיכם כשנים... אם יאדימו כתולע...\" (ישעיהו א, יח), והקזת דם פירושה איפוא שהעוונות יוצאים ממנו.","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 שהרואה בחלומו שהוא מקיז דם \u0003עונותיו סדורין לו!\u0004 ומתרצים: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות המלה \u0003\"סדורין\"\u0004 — שהם \u0003סדורין להמחל.\u0004","\u0003תני תנא קמיה\u0004 \u0005[שנה\u0006 אחד מ\u0005חוזרי המשניות לפני]\u0006 \u0003רב ששת: הרואה נחש בחלום\u0004 הרי זה סימן כי \u0003פרנסתו מזומנת לו\u0004 כנחש שעפר לחמו, ומצוי בכל עת. ראה בחלומו ש\u0003נשכו\u0004 הנחש — הרי זה סימן ש\u0003נכפלה לו\u0004 פרנסתו. ואם חלם ש\u0003הרגו\u0004 לנחש — הרי זה סימן כי \u0003אבדה פרנסתו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת:\u0004 להיפך, סימן יפה הוא לו ו\u0003כל שכן שנכפלה פרנסתו.\u0004 ומעירים: \u0003ולא היא,\u0004 אין הדבר כן, אלא \u0003רב ששת הוא דחזא חויא בחלמיה וקטליה\u0004 \u0005[שראה נחש בחלומו והרגו]\u0006 ורצה לפתור את חלומו שלו לטובה.","\u0003תני תנא קמיה\u0004 \u0005[שנה\u0006 אחד מ\u0005חוזרי המשניות לפני]\u0006 \u0003ר' יוחנן: כל מיני משקין יפין לחלום\u0004 כשאדם חולם עליהם \u0003חוץ מן היין,\u0004 ש\u0003יש\u0004 רואה בחלומו ש\u0003שותהו וטוב לו, ויש\u0004 רואה בחלומו ש\u0003שותהו ורע לו.\u0004 וראיות לדבר: \u0003יש שותהו וטוב לו\u0004 — \u0003שנאמר \"ויין ישמח לבב אנוש\"\u0004 (תהלים קד, טו), \u0003ויש שותהו ורע לו\u0004 — \u0003שנאמר: \"תנו שכר לאובד ויין למרי נפש\"\u0004 (משלי לא, ו).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לתנא\u0004 \u0005[חוזר המשניות]:\u0006 \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003תלמיד חכם לעולם\u0004 סימן \u0003טוב לו\u0004 הוא חלום היין, \u0003שנאמר\u0004 בדברי החכמה: \u0003\"לכו לחמו בלחמי ושתו ביין מסכתי\"\u0004 (משלי ט, ה)."],["\u0003אמר ר' יוחנן: השכים\u0004 בבוקר \u0003ו\u0004מיד כשקם ממטתו \u0003נפל פסוק לתוך פיו\u0004 — \u0003הרי זה נבואה קטנה. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה מלכים הם,\u0004 שראיית כל אחד מהם בחלום יש לה משמעות. \u0003הרואה\u0004 את \u0003דוד בחלום\u0004 — \u0003יצפה לחסידות.\u0004 ראה את \u0003שלמה\u0004 — \u0003יצפה לחכמה.\u0004 ראה את \u0003אחאב\u0004 — \u0003ידאג מן הפורענות,\u0004 כדרך שאירע לאחאב.","וכן \u0003שלשה\u0004 ספרי \u0003נביאים הם,\u0004 ומשמעות שונה לכל אחד מהם ביחס לרואה אותם בחלום: \u0003הרואה ספר מלכים\u0004 — \u0003יצפה לגדולה\u0004 (מלכות). ראה את ספר \u0003יחזקאל\u0004 — \u0003יצפה לחכמה,\u0004 שיש בספר יחזקאל תבנית המרכבה. ראה את ספר \u0003ישעיה\u0004 — \u0003יצפה לנחמה.\u0004 ראה את ספר \u0003ירמיה\u0004 — \u0003ידאג מן הפורענות,\u0004 לפי שהתנבא הרבה מענין הפורענות.","ובדומה לכך, אף \u0003שלשה\u0004 ספרי \u0003כתובים גדולים הם,\u0004 ומשמעות מיוחדת לכל אחד מהם עבור הרואה אותם בחלומו, שכן \u0003הרואה ספר תהלים\u0004 — \u0003יצפה לחסידות, משלי\u0004 — \u0003יצפה לחכמה, איוב\u0004 — \u0003ידאג מן הפורענות.\u0004","ובדומה לכך, \u0003שלשה\u0004 ספרי \u0003כתובים קטנים הם,\u0004 שהם מגילות בלבד, ומשמעות שונה לכל אחד מהם ביחס לרואה אותם בחלום: \u0003הרואה\u0004 את \u0003שיר השירים בחלום\u0004 — \u0003יצפה לחסידות,\u0004 לפי שהוא מתפרש כתיאור אהבת ה' לישראל. \u0003קהלת\u0004 — \u0003יצפה לחכמה. קינות\u0004 (איכה) — \u0003ידאג מן הפורענות. הרואה\u0004 בחלום \u0003מגלת אסתר\u0004 — סימן הוא כי \u0003נס נעשה לו.\u0004","\u0003שלשה חכמים הם\u0004, ומשמעות שונה לכל אחד מהם ביחס לרואה אותם בחלום: \u0003הרואה\u0004 את \u0003רבי בחלום\u0004 — \u0003יצפה לחכמה.\u0004 ראה את \u0003ר' אלעזר בן עזריה\u0004 — \u0003יצפה לעשירות,\u0004 שהיה ר' אלעזר בן עזריה עשיר מופלג. ואם ראה את \u0003ר' ישמעאל בן אלישע\u0004 — \u0003ידאג מן הפורענות,\u0004 שר' ישמעאל הוא אחד מעשרת הרוגי מלכות.","כן \u0003שלשה תלמידי חכמים הם,\u0004 שהיו גדולים בתורה אף על פי שלא זכו להסמך ולהקרא רבי, ומשמעות שונה לכל אחד מהם ביחס לרואה אותם בחלום: \u0003הרואה\u0004 את \u0003בן עזאי בחלום\u0004 — \u0003יצפה לחסידות.\u0004 ראה את \u0003בן זומא\u0004 — \u0003יצפה לחכמה.\u0004 ואם ראה את \u0003אחר\u0004 (אלישע בן אבויה) — \u0003ידאג מן הפורענות,\u0004 שכן יצא לתרבות רעה.","אמרו: \u0003כל מיני חיות יפות לחלום,\u0004 כשאדם רואה אותם בחלום, \u0003חוץ מן הפיל והקוף והקפוד.\u0004 ושואלים: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]\u0006 ש\u0003הרואה פיל בחלום פלא נעשה לו!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר החכם שסימן יפה הוא לו, הרי זה באופן שראהו \u0003דמסרג\u0004 \u0005[ש\u0006הוא \u0005חבוש אוכף],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שראיית פיל אינה סימן יפה, הרי זה באופן \u0003דלא מסרג\u0004 \u0005[כשאינו חבוש אוכף].\u0006","כעין זה אמרו ש\u0003כל מיני\u0004 כלי \u0003מתכת יפין לחלום, חוץ ממר\u0004 (מעדר), \u0003פסל\u0004 (מפסלת), \u0003וקרדום,\u0004 שכן כלים אלה עשויים לקלקול. \u0003והני מילי דחזנהו בקתייהו\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא \u0005כשראה אותם עם קתותיהם,\u0006 ידיותיהם\u0005].\u0006 וכעין זה אמרו: \u0003כל מיני פירות יפין לחלום, חוץ מפגי תמרה,\u0004 שהם תמרים שלא הבשילו כל צרכם. וכן \u0003כל מיני ירקות יפין לחלום, חוץ מראשי לפתות.\u0004 ומקשים, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: לא איעתרי\u0004 \u0005[התעשרתי]\u0006 \u0003עד דחזאי\u0004 \u0005[שראיתי]\u0006 בחלומי \u0003ראשי לפתות,\u0004 והרי שהוא סימן טוב! ומשיבים: רב \u0003כי חזא\u0004 \u0005[כאשר ראה]\u0006 אותם — \u0003בכנייהו חזא\u0004 \u0005[במקום גידולם\u0006 הוא ש\u0005ראה],\u0006 אבל כשרואה בחלום ראשי לפתות תלושים — סימן רע הוא לו. וכעין זה: \u0003כל מיני צבעונין\u0004 (צבעים) \u0003יפין לחלום, חוץ מן התכלת.\u0004 וכן \u0003כל מיני עופות יפין לחלום, חוץ מן קריא וקפופא וקורפראי,\u0004 ששלושתם עופות לילה ודמותם משונה ומפחידה.","המילים \u0003הגו\"ף, הגו\"ף, מעי\"ן, משיבי\"ן, ומרחיבי\"ן,\u0004 הן \u0003סימן\u0004 לדברים שיידונו להלן בגמרא, ויש בכולם תכונות משותפות, בדומה למה ששנינו כבר.","אמרו: \u0003שלשה\u0004 דברים \u0003נכנסים לגוף, ו\u0004אולם \u0003אין הגוף נהנה מהן,\u0004 והם \u0003גודגדניות, וכפניות\u0004 (תמרים גרועים), \u0003ופגי תמרה.\u0004 ולעומת זאת: \u0003שלשה\u0004 דברים \u0003אין נכנסין לגוף, ו\u0004אף על פי כן \u0003הגוף נהנה מהן,\u0004 ו\u0003אלו הן: רחיצה, וסיכה ותשמיש.\u0004 ועוד אמרו: \u0003שלשה\u0004 דברים הם \u0003מעין העולם הבא,\u0004 ו\u0003אלו הן: שבת, שמש ותשמיש.\u0004","על כך שאלו: \u0003תשמיש דמאי\u0004 \u0005[של מה],\u0006 איזה תשמיש? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 כי הכוונה ל\u0003תשמיש המטה\u0004 — \u0003הא מכחש כחיש\u0004 \u0005[הרי\u0006 הוא \u0005מכחיש]\u0006 ומחליש את הגוף! \u0003אלא\u0004 הכוונה ל\u0003תשמיש נקבים\u0004 — שנפנה לצרכיו.","ועוד אמרו, \u0003שלשה\u0004 דברים \u0003משיבין דעתו של אדם,\u0004 ו\u0003אלו הן: קול, ומראה, וריח,\u0004 שכאשר הם נעימים וטובים, הריהם משיבים דעתו של אדם. ועוד, \u0003שלשה\u0004 דברים \u0003מרחיבין דעתו של אדם,\u0004 ו\u0003אלו הן: דירה נאה, ואשה נאה, וכלים נאים.\u0004","המילים \u0003חמש\"ה, ושש\"ה, ועשר\"ה\u0004 הן \u0003סימן\u0004 לדברים שיידונו להלן. אמרו: \u0003חמשה\u0004 דברים בעולמנו, שכל אחד מהם הוא \u0003אחד מששים\u0004 לדברים גדולים השייכים לדרגה עליונה, ו\u0003אלו הן: אש, דבש, ושבת, ושינה, וחלום.\u0004 ומפרטים: \u0003אש\u0004 שלנו היא \u0003אחד מששים לגיהנם. דבש\u0004 — \u0003אחד מששים למן. שבת\u0004 — \u0003אחד מששים לעולם הבא. שינה\u0004 — \u0003אחד מששים למיתה. חלום\u0004 — \u0003אחד מששים\u0004","\u0003לנבואה.\u0004 כעין זה אמרו: \u0003ששה דברים סימן יפה\u0004 הם \u0003לחולה: עטוש, זיעה, שלשול, קרי, ושינה, וחלום.\u0004 ורמז בכתובים לדברים: \u0003עטוש\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עטישותיו תהל אור\"\u0004 (איוב מא, י), הנדרש שעל ידי העיטוש מגיע הוא לראות באורו של העולם. \u0003זיעה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בזעת אפיך תאכל לחם\"\u0004 (בראשית ג, יט). \u0003שלשול\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מהר צעה להפתח ולא ימות לשחת\"\u0004 (ישעיהו נא, נד). \u0003קרי\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יראה זרע יאריך ימים\"\u0004 (שם כג, י). \u0003שינה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ישנתי אז ינוח לי\"\u0004 (איוב ג, יג). \u0003חלום\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותחלימני והחיני\"\u0004 (ישעיהו לח, טז), \"ותחלימני\" — לשון חלום.","וכעין זה: \u0003ששה דברים מרפאין את החולה מחליו ורפואתו רפואה,\u0004 ו\u0003אלו הן: כרוב, ותרדין, וסיסין יבשין, וקיבה, והרת, ויותרת הכבד. ויש אומרים\u0004 כי תכונות אלו יש \u0003אף\u0004 ל\u0003דגים קטנים. ולא עוד, אלא שדגים קטנים מפרין ומברין כל גופו של אדם.\u0004","ולעומת זאת, \u0003עשרה דברים מחזירין את החולה\u0004 שהתרפא מחוליו שוב \u0003לחליו, וחליו קשה\u0004 משהיה, ו\u0003אלו הן:\u0004 האוכל \u0003בשר שור, בשר שמן\u0004 בכלל, או \u0003בשר צלי,\u0004 או \u0003בשר צפרים, וביצה צלויה, ותגלחת,\u0004 שאם מתגלח החולה הרי זה מזיק לו, \u0003ו\u0004כן אם היה אוכל \u0003שחלים, והחלב, והגבינה, ו\u0004רחיצה בבית \u0003המרחץ. ויש אומרים\u0004 ש\u0003אף\u0004 אכילת \u0003אגוזים. ויש אומרים\u0004 ש\u0003אף\u0004 אכילת \u0003קשואים.\u0004","ומעין זה \u0003תנא דבי\u0004 \u0005[שנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: למה נקרא שמן קשואים\u0004 — \u0003מפני שהן קשין לגוף כחרבות.\u0004 ושואלים: \u0003איני\u0004 \u0005[הרי אין הדבר כן],\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויאמר ה' לה שני גוים בבטנך\"\u0004 (בראשית כה, כג), ואמרו: \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"גוים\" אלא \"גיים\"\u0004 (גאים), \u0003ואמר רב יהודה אמר רב: אלו\u0004 שני אנשים גדולים שיצאו מרבקה, ובהם נתקיים פסוק זה, \u0003אנטונינוס ורבי, ש\u0004מרוב עושרם \u0003לא פסק משלחנם לא צנון ולא חזרת ולא קשואין, לא בימות החמה ולא בימות הגשמים.\u0004 והרי שהקישואים הם דבר טוב ואף מעדן מלכים!","ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שהם קשים לגוף הרי זה \u0003ברברבי\u0004 \u0005[בגדולים],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שלא פסקו משולחנם של רבי ואנטונינוס, והרי שטובים הם, הרי זה \u0003בזוטרי\u0004 \u0005[בקטנים].\u0006","ועוד בענין החלום, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 החולם שהוא רואה \u0003מת בבית\u0004 — סימן הוא ל\u0003שלום בבית. אכל ושתה\u0004 המת בחלומו \u0003בבית\u0004 — \u0003סימן יפה לבית. נטל\u0004 המת \u0003כלים מן הבית\u0004 — \u0003סימן רע\u0004 הוא \u0003לבית,\u0004 שמרמז הוא כאילו המת לוקח עמו מישהו מהבית. \u0003תרגמא\u0004 \u0005[הסביר]\u0006 זאת \u0003רב פפא במסאנא וסנדלא\u0004 \u0005[במנעל וסנדל],\u0006 שאם חלם שלקח המת דברים אלה הרי זה רמז שמישהו צריך ללכת לדרך ארוכה, וכן אמרו: \u0003כל\u0004 מה \u0003דשקיל שכבא\u0004 \u0005[שלוקח המת]\u0006 בחלום — הרי זה \u0003מעלי\u0004 \u0005[מעולה],\u0006 \u0003בר ממסאנא וסנדלא\u0004 \u0005[חוץ ממנעל וסנדל],\u0006 \u0003וכל דיהיב שכבא\u0004 \u0005[שנותן המת]\u0006 בחלום — הרי זה \u0003מעלי\u0004 \u0005[מעולה],\u0006 \u0003בר מעפרא וחרדלא\u0004 \u0005[חוץ מעפר וחרדל]\u0006 הדומה במראהו לעפר, שהם סימן לקבורה.","שנינו במשנה שהרואה \u0003מקום שנעקרה ממנו עבודה זרה\u0004 מברך \"ברוך... שעקר עבודה זרה מארצנו\". ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003הרואה\u0004 את העבודה זרה ששמה \u0003מרקוליס, אומר: \"ברוך... שנתן ארך אפים לעוברי רצונו\",\u0004 שבכל יום היו מוסיפים וזורקים אבנים חדשות על הגל שבנו לכבודו (תוספות). והרואה \u0003מקום שנעקרה ממנו עבודה זרה, אומר \"ברוך... שעקר עבודה זרה מארצנו. וכשם שנעקרה ממקום זה כן תעקר מכל מקומות ישראל, והשב לב עובדיהם לעבדך\". ובחוץ לארץ אין צריך לומר \"והשב לב עובדיהם לעבדך\" מפני שרובה\u0004 מאכלסת \u0003גויים. ר' שמעון בן אלעזר אומר: אף בחוץ לארץ צריך לומר כן, מפני ש\u0004כל העמים \u0003עתידים להתגייר\u0004 לעתיד לבוא, \u0003שנאמר:\u0004 \"כי \u0003אז אהפך אל עמים שפה ברורה\u0004 לקרוא בשם ה' לעובדו שכם אחד\" (צפניה ג, ט).","להלן עוסקת הגמרא בדברים שאדם רואה ותקנו חכמים לכל אלו ברכות ראיה מיוחדות. \u0003דרש רב המנונא: הרואה\u0004 את \u0003בבל הרשעה צריך לברך חמש ברכות.\u0004 ומפרטים: \u0003ראה\u0004 את חורבות העיר \u0003בבל, אומר: \"ברוך... שהחריב בבל הרשעה\". ראה ביתו\u0004 החרב \u0003של נבוכדנצר, אומר: \"ברוך... שהחריב ביתו של נבוכדנצר הרשע\". ראה\u0004 את \u0003גוב של\u0004 ה\u0003אריות\u0004 שהושלך אליו דניאל \u0003או\u0004 את \u0003כבשן האש\u0004 שהושלכו בתוכו חנניה מישאל ועזריה, \u0003אומר: \"ברוך... שעשה נסים לאבותינו במקום הזה\". ראה מרקוליס, אומר: \"ברוך... שנתן ארך אפים לעוברי רצונו\". ראה מקום שנוטלין ממנו עפר,\u0004 כי מחורבות בבל היו במשך דורות לוקחים עפר ומשתמשים בו לזיבול או לבניה מסביב, \u0003אומר: \"ברוך... אומר ועושה גוזר ומקיים\".\u0004","ומסופר כי \u0003רבא כי הוה חזי חמרי דשקלי עפרא, טריף להו ידא על גבייהו, ואמר\u0004 \u0005[כאשר היה רואה חמורים הנושאים עפר\u0006 מבבל, \u0005היה טופח בידו על גביהם ואומר]\u0006 להם: \u0003רהוטו צדיקי למעבד רעותא דמרייכו\u0004 \u0005[רוצו צדיקים לעשות את רצון אדונכם].\u0006 \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא כי הוה מטי\u0004 \u0005[כאשר היה מגיע]\u0006 \u0003לבבל הוה שקיל עפרא בסודריה ושדי לברא\u0004 \u0005[היה לוקח עפר בסודרו וזורק לחוץ],\u0006 \u0003לקיים מה שנאמר \"וטאטאתיה במטאטא השמד\"\u0004 (ישעיהו יד, כג). \u0003אמר רב אשי: אנא, הא\u0004 \u0005[אני,\u0006 מימרא \u0005זו]\u0006 של \u0003רב המנונא\u0004 שהרואה בבל הרשעה צריך לברך חמש ברכות \u0003לא שמיע לי\u0004 \u0005[שמעתי]\u0006 אותה, \u0003אלא מדעתאי בריכתינהו לכולהו\u0004 \u0005[מדעתי ברכתי את כולן]\u0006"],["ומענין בבל מביאים את מה ש\u0003אמר ר' ירמיה בן אלעזר: נתקללה בבל\u0004 — \u0003נתקללו שכניה. נתקללה שומרון\u0004 — \u0003נתברכו שכניה\u0004 עימה. ומקור לדברים: \u0003נתקללה בבל\u0004 — \u0003נתקללו שכניה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושמתיה למורש קפד ואגמי מים\"\u0004 (ישעיהו יד, כג), כלומר, שלא רק היא תחרב אלא שהמקום יהיה משכן לבעלי חיים מזיקים אשר יזיקו לכל הסביבה. \u0003נתקללה שומרון\u0004 ובכל זאת \u0003נתברכו שכניה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושמתי שמרון לעי השדה למטעי כרם\"\u0004 (מיכה א, ו), שאף שתיהרס, תשמש למטרה מועילה.","\u0003ואמר רב המנונא: הרואה\u0004 את \u0003אוכלוסי ישראל,\u0004 כלומר, מספר גדול מאד (ששים ריבוא), \u0003אומר: \"ברוך... חכם הרזים\".\u0004 והרואה \u0003אוכלוסי גוים, אומר: \"בושה אמכם\u0004 מאד חפרה יולדתכם הנה אחרית גויים מדבר ציה וערבה\u0003\"\u0004 (ירמיהו נ, יב).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: הרואה את \u0003אוכלוסי ישראל, אומר: \"ברוך... חכם הרזים\".\u0004 ומה טעם הדבר? — שרואה הוא עם שלם \u0003שאין דעתם דומה זה לזה, ואין פרצופיהן דומים זה לזה,\u0004 ו\"חכם הרזים\", הקדוש ברוך הוא, יודע מה בלב כולם. ומסופר ש\u0003בן זומא ראה\u0004 פעם אחת \u0003אוכלוסא\u0004 של ישראל כשהיה עומד \u0003על גב מעלה\u0004 (מדרגה) \u0003בהר הבית,\u0004 ומיד ברך ו\u0003אמר: \"ברוך... חכם הרזים\" ו\"ברוך... שברא כל אלו לשמשני\".\u0004","\u0003הוא היה אומר\u0004 כהסבר למנהגו: \u0003כמה יגיעות יגע אדם הראשון עד שמצא פת לאכול.\u0004 שהרי \u0003חרש, וזרע, וקצר, ועמר, ודש, וזרה\u0004 ברוח \u0003ו\u0004בכך \u0003ברר\u0004 את הבר מן התבן, \u0003וטחן\u0004 את התבואה לקמח, \u0003והרקיד\u0004 (לנפות), \u0003ולש, ואפה, ו\u0004רק \u0003אחר כך אכל, ו\u0004אילו \u0003אני משכים ומוצא\u0004 את \u0003כל אלו מתוקנין לפני.\u0004 שהחברה האנושית מחלקת את עבודתה, וכל אחד נהנה ממה שעולם שלם משמש אותו. \u0003ו\u0004כיוצא בזה \u0003כמה יגיעות יגע אדם הראשון עד שמצא בגד ללבוש.\u0004 שהרי \u0003גזז, ולבן\u0004 (כיבס), \u0003ונפץ\u0004 (סרק), \u0003וטוה, וארג, ו\u0004רק \u0003אחר כך מצא בגד ללבוש, ו\u0004אילו \u0003אני משכים ומוצא\u0004 את \u0003כל אלו מתוקנים לפני. כל אומות שוקדות ובאות לפתח ביתי\u0004 (של סוחרים ויצרנים), \u0003ואני משכים ומוצא כל אלו לפני.\u0004","\u0003הוא היה אומר,\u0004 כלומר, רגיל היה לומר: \u0003אורח טוב מהו אומר?\u0004 — \u0003כמה טרחות טרח בעל הבית בשבילי, כמה בשר הביא\u0004 בעל הבית \u0003לפני, כמה יין הביא לפני, כמה גלוסקאות\u0004 (עוגות) \u0003הביא לפני, וכל מה שטרח\u0004 — \u0003לא טרח אלא בשבילי,\u0004 והשכר שאני משלם הוא פיצוי מועט עבור דברים אלה. \u0003אבל אורח רע מהו אומר?\u0004 — \u0003מה טורח טרח בעל הבית\u0004 ה\u0003זה?\u0004 הלא רק \u0003פת אחת אכלתי\u0004 אצלו, \u0003חתיכה אחת אכלתי, כוס אחד שתיתי,\u0004 ו\u0003כל טורח שטרח בעל הבית\u0004 ה\u0003זה\u0004 — \u0003לא טרח אלא בשביל אשתו ובניו.\u0004","ואומר: \u0003על אורח טוב מהו אומר?\u0004 — \u0003\"זכר כי תשגיא פעלו אשר שררו אנשים\"\u0004 (איוב לו, כד), שהוא משבח ומודה לאנשים שעזרו לו. ו\u0003על אורח רע כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"לכן יראוהו אנשים\u0004 לא יראה כל חכמי לב\u0003\"\u0004 (שם לז, כד).","ואגב הזכרת האוכלוסא מביאים כתוב אחר בענין זה. על הנאמר \u0003\"והאיש בימי שאול זקן בא באנשים\"\u0004 (שמואל א' יז, יב) \u0003אמר רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב זביד, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אושעיא: זה ישי אבי דוד ש\u0004תמיד \u0003יצא\u0004 מלווה \u0003באוכלוסא, ונכנס באוכלוסא, ודרש\u0004 בדברי תורה \u0003באוכלוסא. אמר עולא: נקיטינן\u0004 \u0005[מוחזקים אנו]\u0006 בדבר זה כי \u0003אין אוכלוסא בבבל. תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003אין אוכלוסא פחותה מששים רבוא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003הרואה חכמי ישראל, אומר: \"ברוך... שחלק מחכמתו ליראיו\".\u0004 הרואה \u0003חכמי אומות העולם, אומר: \" ברוך... שנתן מחכמתו לבריותיו\". הרואה מלכי ישראל, אומר: \"ברוך... שחלק מכבודו ליראיו\".\u0004 הרואה \u0003מלכי אומות העולם, אומר: \"ברוך... שנתן מכבודו לבריותיו\".\u0004","\u0003אמר ר' יוחנן: לעולם ישתדל אדם לרוץ לקראת מלכי ישראל. ולא לקראת מלכי ישראל בלבד\u0004 ישתדל לרוץ, \u0003אלא אפילו לקראת מלכי אומות העולם, שאם יזכה\u0004 — \u0003יבחין בין מלכי ישראל למלכי אומות העולם.\u0004","מסופר: \u0003רב ששת סגי נהור הוה\u0004 \u0005[עיוור היה].\u0006 \u0003הוו קאזלי כולי עלמא לקבולי אפי מלכא, וקם אזל בהדייהו\u0004 \u0005[היו הולכים הכל לקבל את פני המלך, ועמד\u0006 ו\u0005הלך אתם]\u0006 \u0003רב ששת. אשכחיה ההוא מינא\u0004 \u0005[מצאו מין אחד]\u0006 ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חצבי לנהרא, כגני לייא\u0004 \u0005[הכדים\u0006 השלמים הולכים \u0005לנהר, לאן\u0006 הולכים הכדים \u0005השבורים],\u0006 כלומר, מה לעיוור לראות בתהלוכה של המלך? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת: \u0003תא חזי דידענא טפי מינך\u0004 \u0005[בוא\u0006 ו\u0005ראה שיודע אני יותר ממך].\u0006 \u0003חלף גונדא קמייתא, כי קא אוושא\u0004 \u0005[עבר הגדוד הראשון,\u0006 ו\u0005כאשר נשמע הרעש]\u0006 \u0003אמר ליה ההוא מינא\u0004 \u0005[לו אותו המין]:\u0006 \u0003אתא מלכא\u0004 \u0005[בא המלך].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת: לא קא אתי מלכא\u0004 \u0005[בא המלך].\u0006 \u0003חלף גונדא תניינא כי קא אוושא\u0004 \u0005[עבר הגדוד השני,\u0006 ו\u0005כאשר נשמע הרעש]\u0006 \u0003אמר ליה ההוא מינא\u0004 \u0005[לו אותו המין]:\u0006 \u0003השתא קא אתי מלכא\u0004 \u0005[עכשיו בא המלך].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת: לא קא אתי מלכא\u0004 \u0005[בא המלך].\u0006 \u0003חליף תליתאי כי קא שתקא\u0004 \u0005[עבר\u0006 הגדוד \u0005השלישי, וכאשר\u0006 כולם \u0005השתתקו]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת: ודאי השתא אתי מלכא\u0004 \u0005[עכשיו בא המלך].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[אותו המין]:\u0006 \u0003מנא\u0004 \u0005[מנין]\u0006 \u0003לך הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת: \u0003דמלכותא דארעא\u0004 \u0005[שמלכות הארץ]\u0006 היא \u0003כעין מלכותא דרקיעא\u0004 \u0005[מלכות השמים],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בהתגלות ה': \u0003\"צא ועמדת בהר לפני ה' והנה ה' עבר ורוח גדולה וחזק מפרק הרים ומשבר סלעים לפני ה' לא ברוח ה' ואחר הרוח רעש לא ברעש ה'. ואחר הרעש אש לא באש ה' ואחר האש קול דממה דקה.\u0004 ויהי כשמוע אליהו וילט פניו באדרתו ויצא ויעמוד פתח המערה\" (מלכים א' יט, יא–יג), הרי שהגילוי דווקא בזמן השתיקה.","\u0003כי אתא מלכא\u0004 \u0005[כאשר בא המלך],\u0006 \u0003פתח רב ששת וקא מברך ליה\u0004 \u0005[וברך אותו].\u0006 \u0003אמר ליה ההוא מינא\u0004 \u0005[לו אותו מין]\u0006 בלגלוג: \u0003למאן דלא חזית ליה קא מברכת\u0004 \u0005[למי שאינך רואה אתה מברך]?\u0006 בסופו של דבר שאלו: \u0003ומאי הוי עליה דההוא מינא\u0004 \u0005[מה היה עליו,\u0006 מה קרה לו \u0005לאותו המין]?\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003חברוהי כחלינהו לעיניה\u0004 \u0005[חבריו נקרו את עיניו],\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ש\u0003רב ששת נתן עיניו בו, ונעשה גל של עצמות.\u0004","בהקשר מסויים שבין מלכות שמים והמלכות בעולם הזה מובא סיפור אחר: \u0003ר' שילא נגדיה לההוא גברא\u0004 \u0005[\u0006פקד \u0005להלקות אדם אחד]\u0006 ש\u0003בעל גויה. אזל אכל ביה קורצא בי מלכא\u0004 \u0005[הלך אותו האיש והלשין למלך],\u0006 \u0003אמר: איכא חד גברא ביהודאי דקא דיין דינא בלא הרמנא דמלכא\u0004 \u0005[יש אדם אחד בין היהודים שהוא דן דין בלי רשיון המלך].\u0006 \u0003שדר עליה פריסתקא\u0004 \u0005[שלח עליו\u0006 המלך \u0005שליח בית דין]\u0006 להביאו. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003אמרי ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא נגדתיה להאי\u0004 \u0005[מה טעם\u0006 פקדת \u0005להלקות את זה]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 משום ש\u0003בא על חמרתא\u0004 \u0005[אתון],\u0006 ואף לפי החוק הפרסי היתה זו עבירה חמורה ביותר. \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 וכי \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך סהדי\u0004 \u0005[עדים]\u0006 לדבר זה? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אליהו\u0004 הנביא \u0003אדמי ליה כאיניש, ואסהיד\u0004 \u0005[נדמה להם כאדם, והעיד].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003אי הכי, בר קטלא\u0004 \u0005[אם כך, בן\u0006 חיוב עונש \u0005מיתה]\u0006 \u0003הוא,\u0004 ומדוע לא המתת אותו? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנן מיומא דגלינן מארעין לית לן רשותא למקטל\u0004 \u0005[אנחנו מיום שגלינו מארצנו אין לנו רשות להרוג],\u0006 ואולם \u0003אתון, מאי דבעיתון עבידו ביה\u0004 \u0005[אתם, מה שאתם רוצים עשו בו].\u0006","\u0003עד דמעייני ביה בדינא\u0004 \u0005[שהיו\u0006 הם \u0005מעיינים בו בדינו]\u0006 \u0003פתח ר' שילא ואמר\u0004 בשבח ה' שהצילו מהסכנה: \u0003\"לך ה' הגדלה והגבורה\u0004 והתפארת והנצח וההוד כי כל בשמים ובארץ לך ה' הממלכה והמתנשא לכל לראש\" (דברי הימים א' כט, יא). \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003מאי קאמרת\u0004 \u0005[מה אמרת]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי קאמינא\u0004 \u0005[כך אמרתי]:\u0006 \u0003\"בריך רחמנא דיהיב מלכותא בארעא כעין מלכותא דרקיעא, ויהב לכו שולטנא ורחמי דינא\"\u0004 \u0005[ברוך ה' שנתן מלכות בארץ כעין מלכות השמים, ונתן לכם שלטון ואהבת משפט].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 אכן \u0003חביבא עליה יקרא דמלכותא כולי האי\u0004 \u0005[חביבה עליו תפארת המלוכה כל כך]!\u0006 \u0003יהבי ליה קולפא\u0004 \u0005[נתנו לו אלה]\u0006 כסמל שלטון ו\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003דון דינא\u0004 \u0005[דין],\u0006 שנתנו לו רשות לדון.","\u0003כי הוה נפיק\u0004 \u0005[כאשר יצא]\u0006 \u0003אמר ליה ההוא גברא\u0004 \u0005[לו אותו אדם]:\u0006 וכי \u0003עביד רחמנא ניסא לשקרי הכי\u0004 \u0005[עושה הקדוש ברוך הוא נס לשקרנים כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רשע,\u0004 וכי \u0003לאו \"חמרי\" איקרו\u0004 \u0005[לא \"חמורים\" נקראו]\u0006 הגויים? \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"אשר בשר חמורים בשרם\"\u0004 (יחזקאל כג, כ). \u0003חזייה דקאזיל למימרא להו דקרינהו \"חמרי\"\u0004 \u0005[ראה אותו\u0006 ר' שילא \u0005שהוא עומד ללכת ולספר להם שקראם \"חמורים\"],\u0006 \u0003אמר: האי\u0004 \u0005[זה]\u0006 \u0003רודף הוא,\u0004 כלומר, אדם זה מנסה להרוג אותי. \u0003ו\u0004הרי \u0003התורה אמרה: אם בא להרגך\u0004 — \u0003השכם להרגו. מחייה בקולפא וקטליה\u0004 \u0005[הכהו באלה והרגו].\u0006","\u0003אמר: הואיל ואתעביד\u0004 \u0005[ונעשה]\u0006 \u0003לי ניסא בהאי קרא\u0004 \u0005[נס בגלל פסוק זה]\u0006 שאמרתי, \u0003דרשינא ליה\u0004 \u0005[אדרוש אותו].\u0006 וכך דרש: \u0003\"לך ה' הגדלה\"\u0004 — \u0003זו מעשה בראשית, וכן הוא אומר: \"עשה גדלות עד אין חקר\"\u0004 (איוב ט, י) בתיאור מעשי בראשית. \u0003\"והגבורה\"\u0004 — \u0003זו יציאת מצרים, שנאמר\u0004 בה: \u0003\"וירא ישראל את היד הגדלה\u0004 אשר עשה ה' במצרים\" (שמות יד, לא). \u0003\"והתפארת\"\u0004 — \u0003זו\u0004 ה\u0003חמה ו\u0004ה\u0003לבנה שעמדו לו ליהושע,\u0004 וכפי \u0003שנאמר: \"וידם השמש וירח עמד\u0004 עד יקום גוי אויביו\u0003\"\u0004 (יהושע י, יג). \u0003\"והנצח\"\u0004 — \u0003זו מפלתה של רומי. וכן הוא אומר\u0004 בתאור מפלת אדום: \u0003\"ויז נצחם על בגדי\u0004 וכל מלבושי אגאלתי\u0003\"\u0004 (ישעיהו סג, ג). \u0003\"וההוד\"\u0004 — \u0003זו מלחמת נחלי ארנון, ש\u0004עליה \u0003נאמר \"על כן יאמר בספר מלחמת ה' את והב בסופה\u0004 ואשד הנחלים ארנון\u0003\"\u0004 (במדבר כא, יד). \u0003\"כי כל בשמים ובארץ\"\u0004 — \u0003זו מלחמת סיסרא, שנאמר\u0004 בה: \u0003\"מן שמים נלחמו הכוכבים ממסלותם\u0004 נלחמו עם סיסרא\" (שופטים ה, כ). \u0003\"לך ה' הממלכה\"\u0004 — \u0003זו מלחמת עמלק, וכן הוא אומר: \"כי יד על כס יה\u0004 מלחמה לה' בעמלק מדור דור\" (שמות יז, טז), שאז ישב ה' על כסא. \u0003\"והמתנשא\"\u0004 — \u0003זו מלחמת גוג ומגוג, וכן הוא אומר: \"הנני אליך גוג נשיא ראש משך ותבל\"\u0004 (יחזקאל לח, ג). \u0003\"לכל לראש\"\u0004 — \u0003אמר רב חנן בר רבא אמר ר' יוחנן: אפילו\u0004 את \u0003ריש גרגיתא\u0004 \u0005[הממונה על חלוקת המים]\u0006 \u0003מן שמיא מנו ליה\u0004 \u0005[השמים ממנים אותו],\u0006 כלומר, כל ראשות ושררה ואפילו הקטנה ביותר בידי שמים היא.","\u0003במתניתא תנא משמיה\u0004 \u0005[בברייתא שנינו משמו]\u0006 של \u0003ר' עקיבא: \"לך ה' הגדלה\"\u0004 — \u0003זו קריעת ים סוף. \"והגבורה\"\u0004 — \u0003זו מכת בכורות. \"והתפארת\"\u0004 — \u0003זו מתן תורה. \"והנצח\"\u0004 — \u0003זו ירושלים. \"וההוד\"\u0004 — \u0003זו בית המקדש.\u0004"],["\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרואה בתי ישראל בישובן\u0004 ובשלוותם בארץ, \u0003אומר: \"ברוך... מציב גבול אלמנה\".\u0004 ו\u0003בחורבנן, אומר: \"ברוך דיין האמת\".\u0004 הרואה \u0003בתי גויים בישובן, אומר: \"בית גאים יסח ה'\u0004 ויצב גבול אלמנה\u0003\"\u0004 (משלי טו, כה). ו\u0003בחורבנן, אומר: \"אל נקמות ה' אל נקמות הופיע\"\u0004 (תהלים צד, א).","מסופר כי \u0003עולא ורב חסדא הוו קא אזלי באורחא\u0004 \u0005[היו מהלכים בדרך].\u0006 \u0003כי מטו אפתחא דבי\u0004 \u0005[כאשר הגיעו לפתח בית]\u0006 \u0003רב חנא בר חנילאי נגד\u0004 \u0005[נאנק]\u0006 \u0003רב חסדא ואתנח\u0004 \u0005[ונאנח].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003עולא: אמאי קא מתנחת\u0004 \u0005[מדוע אתה נאנח]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: אנחה שוברת חצי גופו של אדם,\u0004 וכפי \u0003שנאמר: \"ואתה בן אדם האנח בשברון מתנים\"\u0004 וכו' (יחזקאל כא, יא), והרי שהאנחה שוברת את האדם עד מתניו. \u0003ור' יוחנן אמר\u0004 שהאנחה שוברת \u0003אף כל גופו של אדם\u0004, וכפי \u0003שנאמר: \"והיה כי יאמרו אליך על מה אתה נאנח ואמרת אל שמועה כי באה ונמס כל לב\u0004 ורפו כל ידים וכהתה כל רוח וכל ברכיים תלכנה מים\u0003\"\u0004 (שם יב).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לעולא: \u0003היכי\u0004 \u0005[איך]\u0006 \u0003לא אתנח\u0004 \u0005[אאנח],\u0006 והרי \u0003ביתא דהוו בה שיתין אפייתא ביממא ושיתין אפייתא בליליא, ואפיין לכל מאן דצריך\u0004 \u0005[בית שהיו בו ששים אופות ביום, וששים אופות בלילה, והיו אופות לכל מי שצריך],\u0006 \u0003ולא שקל ידא מן כיסא\u0004 \u0005[הוציא את היד מהכיס]\u0006 משום שהוא \u0003סבר דילמא אתי\u0004 \u0005[שמא יבוא]\u0006 \u0003עני בר\u0004 \u0005[בן]\u0006 \u0003טובים ואדמטו ליה לכיסא קא מכסיף\u0004 \u0005[ועד שיושיט ידו לכיס יתבייש]\u0006 העני. \u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003הוו פתיחין ליה\u0004 \u0005[היו פתוחות לו]\u0006 לאותו בית \u0003ארבע בבי\u0004 \u0005[דלתות]\u0006 \u0003לארבע רוחתא\u0004 \u0005[רוחות,\u0006 צדדים\u0005],\u0006 \u0003וכל\u0004 מי \u0003דהוה עייל כפין נפיק כי שבע\u0004 \u0005[שהיה נכנס רעב, היה יוצא כאשר\u0006 הוא \u0005שבע].\u0006 \u0003והוו שדו ליה חטי ושערי\u0004 \u0005[והיו זרוקים להם חיטים ושעורים]\u0006 \u0003בשני בצורת אבראי\u0004 \u0005[מבחוץ]\u0006 כדי ש\u0003כל מאן דכסיפא מילתא למשקל ביממא\u0004 \u0005[מי שמתבייש לקחת ביום]\u0006 \u0003אתי ושקיל בליליא\u0004 \u0005[יבוא ויקח בלילה].\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003נפל\u0004 הבית \u0003בתלא\u0004 \u0005[ונשארה חורבה],\u0006 \u0003ולא אתנח\u0004 \u0005[אאנח]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא לרב חסדא: אין לך מה להיאנח, שכן \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: מיום שחרב בית המקדש נגזרה גזירה על בתיהם של צדיקים שיחרבו, שנאמר: \"באזני ה' צבאות אם לא בתים רבים לשמה יהיו גדלים וטובים מאין יושב\"\u0004 (ישעיהו ה, ט). \u0003ו\u0004עוד \u0003אמר ר' יוחנן:\u0004 לעתיד לבוא \u0003עתיד הקדוש ברוך הוא להחזירן לישובן\u0004 ולמקומן, \u0003שנאמר: \"שיר המעלות לדוד הבטחים בה' כהר ציון\u0004 לא ימוט לעולם ישב\u0003\"\u0004 (תהלים קכה, א), ומפסוק זה יש ללמוד: \u0003מה הר ציון עתיד הקדוש ברוך הוא להחזירו לישובו, אף בתיהן של צדיקים עתיד הקדוש ברוך הוא להחזירן לישובן.\u0004 ואם כן אין לך סיבה להיאנח. \u0003חזייה\u0004 \u0005[ראה אותו]\u0006 עולא ש\u0003לא מיישב דעתיה\u0004 \u0005[מתיישבת דעתו]\u0006 בדברי נחמה אלה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דיו לעבד שיהיה כרבו\u0004 (אדונו), ומאחר והקדוש ברוך הוא משאיר את ביתו, בית המקדש, הרוס, אין להתרעם איפוא על חורבן בתי הצדיקים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003הרואה קברי ישראל, אומר: \"ברוך... אשר יצר אתכם בדין, וזן אתכם בדין, וכלכל אתכם בדין, ואסף אתכם בדין, ועתיד להקימכם בדין\".\u0004 ו\u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא מסיים בה,\u0004 בנוסח ברכה זו, \u0003משמיה\u0004 \u0005[משומו]\u0006 של \u0003רב נחמן: \"ויודע מספר כולכם, והוא עתיד להחיותכם ולקיים אתכם. ברוך... מחיה המתים\".\u0004 והרואה \u0003קברי גוים, אומר: \"בושה אמכם\u0004 חפרה יולדתכם הנה אחרית גויים מדבר ציה וערבה\" (ירמיהו נ, יב).","\u0003אמר ר' יהושע בן לוי: הרואה את חבירו לאחר שלשים יום\u0004 שלא ראהו, \u0003אומר: \"ברוך... שהחיינו וקיימנו והגיענו לזמן הזה\".\u0004 והרואה אותו \u0003לאחר שנים עשר חדש, אומר: \"ברוך... מחיה המתים\".\u0004 ש\u0003אמר רב: אין המת משתכח מן הלב אלא לאחר שנים עשר חדש\".\u0004 וראיה לדבר ממה \u0003שנאמר: \"נשכחתי כמת מלב הייתי ככלי אובד\"\u0004 (תהלים לא, יג), ובדיני השבת אבידה יודעים אנו שמטבע האדם שהוא מתייאש מאבידתו לאחר שנים עשר חודש (ראה ב\"מ כח, א). הרי ששנה היא תקופת זמן שלמה שבה עלול אדם לשכוח ולהשכח לגמרי.","מסופר: \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע הוו קאזלי באורחא\u0004 \u0005[היו מהלכים בדרך].\u0006 \u0003פגעו ביה\u0004 \u0005[פגשו בו]\u0006 \u0003ברב חנינא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003בהדי דחזינך בריכינן עלך תרתי\u0004 \u0005[כאשר ראינוך ברכנו עליך שתי\u0006 ברכות\u0005],\u0006 \u0003\"ברוך... אשר חלק מחכמתו ליראיו\" ו\u0004ברכת \u0003\"שהחיינו\",\u0004 שכן לא התראו יותר מחודש. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא נמי\u0004 \u0005[אני גם כן],\u0006 \u0003כיון דחזתינכו\u0004 \u0005[שראיתיכם]\u0006 \u0003חשבתינכו עלואי כשיתין רבוון\u0004 \u0005[חשבתי אתכם לגבי כששים ריבוא]\u0006 \u0003בית ישראל, וברכינא עלייכו תלתא\u0004 \u0005[וברכתי עליכם שלוש\u0006 ברכות\u0005],\u0006 \u0003הנך תרתי\u0004 \u0005[אלה השתים]\u0006 שברכתם אתם, \u0003ו\u0004כן \u0003\"ברוך... חכם הרזים\",\u0004 שהיא ברכה שמברכים על ראיית ששים ריבוא מישראל. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 וכי \u0003חכימת כולי האי\u0004 \u0005[נעשית כל כך חכם]!\u0006 \u0003יהבי ביה עינייהו, ושכיב\u0004 \u0005[נתנו בו עיניהם, ומת].\u0006","וממשיכה הגמרא בדבר הצורך לברך על ראיית דברים היוצאים מגדר הרגיל. \u0003אמר ר' יהושע בן לוי: הרואה את הבהקנים\u0004 (אנשים יש עליהם בהרות מבריקות), \u0003אומר\u0004 עליהם: \u0003\"ברוך... משנה הבריות\". מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003ראה את הכושי, ואת הגיחור\u0004 (מי שהוא אדום ביותר), \u0003ואת הלווקן\u0004 (לבן ביותר), \u0003ואת הקפח\u0004 (רזה מאד וגבוה), \u0003ואת הננס, ואת הדרניקוס\u0004 (שפיו מעוקם), \u0003אומר\u0004 עליהם: \u0003\"ברוך... משנה את הבריות\".\u0004 ואילו הרואה \u0003את הקטע, ואת הסומא, ואת פתויי הראש\u0004 (שראשם משוטח), \u0003ואת החגר, ואת המוכה שחין, ואת הבהקנים, אומר: \"ברוך... דיין אמת\",\u0004 והרי שהברכה על בהקן אינה \"משנה הבריות\"!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' יהושע בן לוי שמברכים \"משנה הבריות\", הרי זה באופן שהוא בהקן עוד \u0003ממעי אמו. הא\u0004 \u0005[זה]\u0006 ששנינו שעל בהקן מברכים \"דיין האמת\" הרי זה באופן שנהיה בהקן רק \u0003בתר דאיתיליד\u0004 \u0005[אחרי שנולד].\u0006 ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייקת גם כן]\u0006 הבחנה זו, על פי השוואה עם הדברים הכתובים שם, שהרי \u0003קתני דומיא\u0004 \u0005[שנה\u0006 את הבהקן \u0005בדומה]\u0006 ל\u0003קטע\u0004 שאף זה מום שכרגיל בא לאחר לידה. ומעירים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כדבריך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרואה פיל, קוף\u0004 או \u0003קפוף\u0004 (קוף קטן), \u0003אומר: \"ברוך... משנה את הבריות\". ראה בריות טובות,\u0004 כלומר, יצורים מכל מין המעולים בטיבם או ביופיים, או \u0003אילנות טובות, אומר: \"ברוך... שככה לו בעולמו\".\u0004","שנינו במשנה ש\u0003על הזיקין\u0004 מברך \"שכוחו וגבורתו מלא עולם\". ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הם \u0003זיקין? אמר שמואל:\u0004 הם \u0003כוכבא דשביט\u0004 \u0005[כוכב שביט].\u0006 \u0003ואמר שמואל: נהירין לי שבילי דשמיא\u0004 \u0005[השמים]\u0006 \u0003כשבילי\u0004 העיר \u0003נהרדעא,\u0004 עירי, \u0003לבר מכוכבא דשביט דלא ידענא מאי ניהו\u0004 \u0005[חוץ מכוכב השביט שאין אני יודע מה הוא].\u0006 \u0003וגמירי דלא עבר כסלא\u0004 \u0005[ולמודים אנו\u0006 במסורת \u0005שאינו עובר\u0006 את מערכת הכוכבים של \u0005כסיל,\u0006 אוריון\u0005],\u0006 \u0003ואי עבר כסלא\u0004 \u0005[ואם יעבור\u0006 את \u0005כסיל]\u0006 — \u0003חרב עלמא\u0004 \u0005[יחרב העולם].\u0006 ושואלים: \u0003והא קא חזינן דעבר\u0004 \u0005[והרי אנו רואים ש\u0006הוא \u0005עובר]\u0006 על פני כסיל! ודוחים: \u0003זיויה\u0004 \u0005[זיוו]\u0006 \u0003הוא דעבר\u0004 \u0005[שעובר],\u0006 \u0003ומתחזי כדעבר איהו\u0004 \u0005[ונראה כאילו הוא עובר].\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר\u0004 תשובה אחרת: רק \u0003וילון\u0004 (אחד הרקיעים) \u0003הוא דמקרע, דמגלגל, ומחזי נהורא\u0004 \u0005[שנקרע,\u0006 ו\u0005מתגלגל, ונראה אור]\u0006 ה\u0003רקיע,\u0004 ונדמה שהוא כוכב השביט. \u0003רב אשי אמר\u0004 הסבר אחר: לא כוכב השביט הוא שעובר את כסיל, כי אם \u0003כוכבא\u0004 \u0005[כוכב]\u0006 \u0003הוא דעקר מהאי גיסא דכסלא וחזי ליה חבריה מהך גיסא\u0004 \u0005[שעוקר מצד זה של כסיל ורואה אותו חבירו,\u0006 כוכב אחר, \u0005מצד אחר],\u0006 \u0003ומיבעית\u0004 \u0005[ונבהל]\u0006 ומזדעזע, \u0003ומחזי כמאן דעבר\u0004 \u0005[ונראה כמי שעובר].\u0006","ואגב הדיון בכוכבים מביאים את מה ש\u0003שמואל רמי\u0004 \u0005[משליך]\u0006 ממשמעות פסוק אחד ומקשה ממשמעות השני בענין הזכרת המזלות. מצד אחד \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"עושה עש כסיל וכימה\u0004 וחדרי תימן\" (איוב ט, ט), שבו הוא מקדים את כסיל לכימה, \u0003ו\u0004בפסוק אחר \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"עושה כימה וכסיל\"\u0004 (עמוס ה, ח), שבו הוא מקדים כימה לכסיל. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 אתה מסביר זאת? ומשיבים: \u0003אלמלא חמה של כסיל,\u0004 שנחשב כמשפיע חום, \u0003לא נתקיים\u0004 ה\u0003עולם מפני\u0004 ה\u0003צינה של כימה, ו\u0004להיפך, \u0003אלמלא צינה של כימה\u0004 — \u0003לא נתקיים\u0004 ה\u0003עולם מפני חמה של כסיל.\u0004","\u0003ו\u0004עוד \u0003גמירי\u0004 \u0005[למודים אנו\u0006 במסורת\u0005]\u0006 בענין הכוכבים כי \u0003אי לאו עוקצא דעקרבא דמנח\u0004 \u0005[אם לא\u0006 היה \u0005עוקצו של\u0006 מזל \u0005עקרב]\u0006 מונח \u0003בנהר דינור,\u0004 הרי \u0003כל מאן דהוה טריקא ליה עקרבא\u0004 \u0005[מי שהיה עוקץ אותו העקרב]\u0006 \u0003לא הוה חיי\u0004 \u0005[היה חי].\u0006 \u0003והיינו דקאמר ליה רחמנא\u0004 \u0005[וזהו שאמר לו הקדוש ברוך הוא]\u0006 \u0003לאיוב\u0004 בענין יחס של קור וחום בין הכוכבים: \u0003\"התקשר מעדנות כימה או משכות כסיל תפתח\"\u0004 (איוב לח, לא), שה' מגביר בכל פעם את כוחו של מזל אחר על מנת להוסיף או להמעיט בחום.","על כימה שאלו: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003\"כימה\"?\u0004 מדוע נקרא שמה כך? \u0003אמר שמואל:\u0004 לפי שהיא \u0003כמאה ככבי\u0004 \u0005[כוכבים]\u0006 שיש במערכת כוכבים זו מאה כוכבים. \u0003אמרי לה דמכנפי\u0004 \u0005[יש אומרים ש\u0006כוכבים אלה \u0005מכונסים\u0006 יחד\u0005],\u0006 \u0003ואמרי לה דמבדרן\u0004 \u0005[ויש אומרים ש\u0006הם \u0005מפוזרים].\u0006","ועם הזכרת הפסוק \"עושה עש כסיל וכימה\" (איוב ט, ט), שואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"עש\"? אמר רב יהודה:\u0004 הוא הכוכב הנקרא \u0003יותא.\u0004 אך גם שם זה לא היה ידוע ושאלו גם עליו \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"יותא\"?\u0004 ובכך נחלקו, \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 שהם הכוכבים הנמצאים ושייכים ל\u0003זנב טלה. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיא שייכת ל\u0003רישא דעגלא\u0004 \u0005[לראש,\u0006 תחילת מזל \u0005שור].\u0006 ומסכמים: \u0003ומסתברא\u0004 \u0005[ומסתבר]\u0006 לומר \u0003כמאן דאמר\u0004 \u0005[כמי שאומר]\u0006 שהם הכוכבים הנמצאים ושייכים ל\u0003זנב טלה, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ועיש על בניה תנחם\"\u0004 (איוב לח, לב). \u0003אלמא חסרה ומתחזיא\u0004 \u0005[מכאן שהיא חסרה\u0006 וזנב זה \u0005נראה]\u0006"],["\u0003כטרפא דטריף\u0004 \u0005[שהדביקו לו].\u0006 ומסבירים: \u0003והאי דאזלא בתרה\u0004 \u0005[וזו ש\u0006היא, עיש, \u0005הולכת אחריה,\u0006 אחרי כימה\u0005],\u0006 \u0003דאמרה\u0004 \u0005[ש\u0006היא כ\u0005אומרת]\u0006 \u0003לה: הב\u0004 \u0005[תני]\u0006 \u0003לי בני,\u0004 שני הכוכבים שלי. וכפי שמסופר \u0003שבשעה שהקדוש ברוך הוא בקש להביא מבול לעולם נטל שני כוכבים מכימה והביא מבול לעולם. וכשבקש\u0004 אחר כך \u0003לסתמה,\u0004 כלומר, לסתום את החלל, \u0003נטל שני כוכבים מעיש וסתמה\u0004 בהם. ולכן מחזר מזל עיש אחר כימה ומבקש את כוכביו.","ושואלים: \u0003וליהדר\u0004 \u0005[ושיחזיר]\u0006 \u0003לה\u0004 הקדוש ברוך הוא לכימה את שני כוכביה? ומשיבים: \u0003אין הבור מתמלא מחוליתו,\u0004 שחלק מן הבור אינו יכול לסתום את הבור ממנו נטלוהו. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר כי \u0003אין קטיגור נעשה סניגור,\u0004 שכוכבים אלה שגרמו למבול אין זה נאה שעכשו יביאו ברכה.","ושואלים: \u0003וליברי\u0004 \u0005[ושיבראו]\u0006 \u0003לה,\u0004 לכימה, \u0003תרי ככבי אחריני\u0004 \u0005[שני כוכבים אחרים,\u0006 חדשים\u0005]!\u0006 ומשיבים: \u0003\"אין כל חדש תחת השמש\"\u0004 (קהלת א, ט). ו\u0003אמר רב נחמן:\u0004 לעתיד לבוא \u0003עתיד הקדוש ברוך הוא להחזירן,\u0004 לאותם כוכבים, \u0003לה,\u0004 לעיש. וכפי \u0003שנאמר: \"ועיש על בניה תנחם\"\u0004 (איוב לח, לב) המתפרש מלשון תנחומים, ובודאי יהיה זה בשל החזרת הכוכבים.","\u0003ו\u0004עוד שנינו במשנה כי \u0003על הזועות\u0004 יש לברך \"שכוחו וגבורתו מלא עולם\". ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הן ה\u0003זועות? אמר רב קטינא: גוהא\u0004 \u0005[רעידת אדמה].\u0006 ומסופר: \u0003רב קטינא הוה קאזיל באורחא\u0004 \u0005[היה מהלך בדרך].\u0006 \u0003כי מטא אפתחא דבי אובא טמיא גנח גוהא\u0004 \u0005[כאשר הגיע לפתח בית\u0006 העושה כישוף \u0005אוב\u0006 ב\u0005עצמות\u0006 מת, בעל אוב, \u0005נשמעה רעידת אדמה].\u0006 \u0003אמר: מי ידע אובא טמיא האי גוהא\u0004 \u0005[האם יודע בעל האוב רעש אדמה זה]\u0006 \u0003מהו? רמא ליה קלא\u0004 \u0005[הרים קולו]\u0006 ואמר: \u0003קטינא קטינא, אמאי לא ידענא\u0004 \u0005[מדוע איני יודע]?\u0006 ודאי טעם הרעש הוא ש\u0003בשעה שהקדוש ברוך הוא זוכר את בניו ששרויים בצער בין אומות העולם מוריד שתי דמעות לים הגדול, וקולו נשמע מסוף העולם ועד סופו, והיינו גוהא\u0004 \u0005[וזוהי רעידת האדמה].\u0006","\u0003אמר רב קטינא: אובא טמיא כדיב\u0004 \u0005[בעל האוב כוזב]\u0006 \u0003הוא, ומיליה כדיבין\u0004 \u0005[ודבריו כוזבים].\u0006 שכן \u0003אי הכי\u0004 \u0005[אם כך]\u0006 כדבריו — \u0003גוהא גוהא מיבעי ליה\u0004 \u0005[רעידת האדמה\u0006 ועוד \u0005רעידת אדמה,\u0006 כלומר, פעמיים \u0005היתה צריכה להיות]\u0006 כנגד שתי דמעות. ומעירים: \u0003ולא היא,\u0004 אין הדבר כן, \u0003גוהא גוהא עביד\u0004 \u0005[רעידת האדמה\u0006 ועוד \u0005רעידת אדמה עושה],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003לא אודי ליה\u0004 \u0005[הודה לו]\u0006 רב קטינא לאותו בעל אוב, הרי זה \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ליטעי כולי עלמא אבתריה\u0004 \u0005[יטעו הכל אחריו].\u0006","\u0003ורב קטינא דידיה\u0004 \u0005[\u0006הסבר \u0005משלו]\u0006 \u0003אמר\u0004 בסיבת רעידת האדמה: מפני שהקדוש ברוך הוא \u0003סופק כפיו,\u0004 כלומר, מכה כף לכף מתוך צער וכפי \u0003שנאמר: \"וגם אני אכה כפי אל כפי והניחתי חמתי\u0004 אני ה' דברתי\u0003\"\u0004 (יחזקאל כא, כב). ו\u0003ר' נתן אומר:\u0004 סיבת רעש האדמה היא מפני שהקדוש ברוך הוא \u0003אנחה מתאנח\u0004 על צרת ישראל, כפי \u0003שנאמר: \"\u0004וכלה אפי \u0003והניחתי חמתי בם והנחמתי\"\u0004 (שם ה, יג). \u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים]:\u0006 סיבת הרעש היא לפי שהקדוש ברוך הוא \u0003בועט ברקיע,\u0004 ומתוך כך נשמע הקול, וכפי \u0003שנאמר: \"\u0004ה' ממרום ישאג וממעון קדשו יתן קולו שאוג ישאג על נוהו \u0003הידד כדרכים יענה אל כל ישבי הארץ\"\u0004 (ירמיהו כה, ל). ו\u0003רב אחא בר יעקב אמר:\u0004 סיבת הרעש היא, שהקדוש ברוך הוא \u0003דוחק את רגליו\u0004 מ\u0003תחת\u0004 ל\u0003כסא הכבוד\u0004 והעולם מזדעזע, וכפי \u0003שנאמר: \"השמים כסאי והארץ הדם רגלי\"\u0004 (ישעיהו סו, א).","\u0003ו\u0004עוד שנינו במשנה ש\u0003על הרעמים\u0004 יש לברך \"שכוחו וגבורתו מלא עולם\". ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הם ה\u0003רעמים,\u0004 כיצד הם נוצרים? \u0003אמר שמואל:\u0004 אלו הם \u0003ענני בגלגלא\u0004 \u0005[עננים\u0006 הנמצאים \u0005בגלגל\u0006 הרקיע\u0005]\u0006 וכשהם מתנגשים בו נשמע קול זה. וראיה לדבר ממה \u0003שנאמר: \"קול רעמך בגלגל האירו ברקים תבל רגזה ותרעש הארץ\"\u0004 (תהלים עז, יט). \u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים]:\u0006 הרעם הוא קול \u0003ענני דשפכי מיא להדדי\u0004 \u0005[עננים השופכים מים זה לזה],\u0006 וכפי \u0003שנאמר: \"לקול תתו המון מים בשמים\"\u0004 (ירמיהו י, יג). \u0003רב אחא בר יעקב אמר:\u0004 הסיבה היא \u0003ברקא תקיפא דבריק בעננא, ומתבר גזיזי דברזא\u0004 \u0005[ברק חזק המבריק בענן, ושובר את גושי הקרח].\u0006 \u0003רב אשי אמר:\u0004 הסיבה לרעש זה משום ש\u0003ענני חלחולי מחלחלי, ואתי זיקא ומנשב אפומייהו, ודמי כזיקא על פום דני\u0004 \u0005[חלולים\u0006 הם \u0005העננים, ובאה הרוח ומנשבת על פיהם,\u0006 ונשמע הקול \u0005ונדמה כ\u0006קול ה\u0005רוח\u0006 הנושבת \u0005על פי הכדים].\u0006 ומסכמים: \u0003ומסתברא\u0004 \u0005[ומסתבר]\u0006 לומר \u0003כ\u0004טעמו של \u0003רב אחא בר יעקב,\u0004 שרואים \u0003דבריק ברקא, ומנהמי ענני, ואתי מטרא\u0004 \u0005[שמבריק הברק, ונוהמים העננים, ובא הגשם].\u0006","\u0003ו\u0004עוד שנינו במשנה ש\u0003על הרוחות,\u0004 יש לברך \"שכוחו וגבורתו מלא עולם\". ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הן \u0003רוחות\u0004 אלה? \u0003אמר אביי:\u0004 המדובר ב\u0003זעפא\u0004 \u0005[רוח סערה].\u0006 \u0003ואמר אביי: גמירי, דזעפא בליליא לא הוי\u0004 \u0005[למודים אנו\u0006 במסורת \u0005שאין רוח סערה בלילה],\u0006 ושואלים: \u0003והא קא חזינן דהוי\u0004 \u0005[והרי אנו רואים שיש]\u0006 רוח סערה בלילה! ומשיבים: \u0003ההוא,\u0004 אותה רוח סערה שישנה בלילה לא מדובר ברוח שהתחילה בלילה, אלא \u0003דאתחולי ביממא\u0004 \u0005[שהתחילה ביום].\u0006 \u0003ו\u0004עוד \u0003אמר אביי: גמירי, דזעפא תרתי שעי לא קאי\u0004 \u0005[למודים אנו\u0006 במסורת \u0005שרוח הסערה אינה\u0006 נמשכת \u0005שתי שעות],\u0006 \u0003לקיים מה שנאמר: \"לא תקום פעמים צרה\"\u0004 (נחום א, ט). ושואלים: \u0003והא קא חזינן דקאי\u0004 \u0005[והרי אנו רואים שעומדת,\u0006 נמשכת\u0005]\u0006 יותר משעתיים! ומשיבים: אכן אינה נמשכת יותר משעתיים, ומה שרואים אנו שנמשכת, אינה רצופה אלא \u0003דמפסיק ביני ביני\u0004 \u0005[שנפסקת בינתיים]\u0006 לזמן קצר.","\u0003ו\u0004שנינו במשנה ש\u0003על הברקים אומר \"ברוך... שכחו וגבורתו מלא עולם\".\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הם \u0003ברקים\u0004 אלה? \u0003אמר רבא: ברקא\u0004 \u0005[אור בוהק].\u0006 \u0003ואמר רבא: ברקא יחידאה\u0004 \u0005[ברק יחידי],\u0006 \u0003וברקא חיורא\u0004 \u0005[וברק לבן],\u0006 \u0003וברקא ירוקתא\u0004 \u0005[וברק ירוק],\u0006 \u0003וענני דסלקן\u0004 \u0005[ועננים העולים]\u0006 \u0003בקרן מערבית ואתיין\u0004 \u0005[ובאים]\u0006 \u0003מקרן דרומית, ותרתי ענני דסלקן חדא לאפי חברתה\u0004 \u0005[ושני עננים העולים זה מול זה]\u0006 — \u0003כולהו קשיין\u0004 \u0005[כולם קשים].\u0006","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 שיודעים אנו שקשים הם? ומשיבים: \u0003למבעי רחמי\u0004 \u0005[לבקש רחמים]\u0006 מה' שלא יזיקו. \u0003ו\u0004מסייגים את הדברים ואומרים כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא כאשר הם באים \u0003בליליא\u0004 \u0005[בלילה],\u0006 \u0003אבל בצפרא\u0004 \u0005[בבוקר]\u0006 — \u0003לית בהו מששא\u0004 \u0005[אין בהם ממש].\u0006","וכן \u0003אמר ר' שמואל בר יצחק: הני\u0004 \u0005[אלה]\u0006 \u0003ענני דצפרא\u0004 \u0005[הבוקר]\u0006 \u0003לית בהו מששא\u0004 \u0005[אין בהם ממש],\u0006 שמיד יעלמו. וראיה לכך ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וחסדכם כענן בקר\u0004 וכטל משכים הולך\u0003\"\u0004 (הושע ו, ד). על כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי, הא אמרי אינשי\u0004 \u0005[הרי אומרים אנשים]\u0006 כפתגם מקובל: \u0003כד מפתח בבי מיטרא, בר חמרא, מוך שקיך וגני\u0004 \u0005[כאשר בפתיחת השערים\u0006 בבוקר \u0005יורד גשם, החמר, קפל את שקיך ושכב לישון],\u0006 שוודאי ימשך הגשם זמן רב, ואם כן נראה מכאן שענני בוקר אינם חולפים מיד! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמשמע שבודאי שיהיו גשמים רבים, הרי זה באופן \u0003דקטר בעיבא\u0004 \u0005[שנקשרו\u0006 השמים \u0005בעבים,\u0006 עננים כבדים\u0005],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' שמואל בר יצחק שבענני הבוקר אין ממש ולא יהיו מהם גשמים רבים, הרי זה באופן \u0003דקטר בענני\u0004 \u0005[שנקשרו\u0006 השמים \u0005בעננים\u0006 קלים\u0005]\u0006 שודאי יחלפו.","\u0003אמר ר' אלכסנדרי אמר ר' יהושע בן לוי: לא נבראו\u0004 ה\u0003רעמים אלא\u0004 כדי להפיל אימה ובכך \u0003לפשוט\u0004 (ליישר) \u0003עקמומית שבלב, שנאמר: \"והאלהים עשה שיראו מלפניו\"\u0004 (קהלת ג, יד). \u0003ו\u0004עוד \u0003אמר ר' אלכסנדרי אמר ר' יהושע בן לוי: הרואה את הקשת בענן צריך שיפול על פניו, שנאמר: \"כמראה הקשת אשר יהיה בענן\u0004 כן מראה כבוד ה' \u0003ואראה ואפל על פני\"\u0004 (יחזקאל א, כח), ואם כן מסמלים צבעי הקשת כביכול את כבוד ה' ואין להביט בהם. אולם \u0003לייטי עלה במערבא\u0004 \u0005[היו מקללים על כך בארץ ישראל]\u0006 מי שנפל על פניו למראה הקשת, והטעם: \u0003משום דמחזי כמאן דסגיד לקשתא\u0004 \u0005[שנראה כמי שמשתחווה לקשת].\u0006 \u0003אבל ברוכי\u0004 \u0005[לברך]\u0006 הכל מודים כי \u0003ודאי מברך. מאי\u0004 \u0005[מה],\u0006 איזו ברכה \u0003מברך?\u0004 — \u0003\"ברוך... זוכר הברית\"\u0004 (הברית עם נח). \u0003במתניתא תנא\u0004 \u0005[בברייתא שנינו],\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקא אומר\u0004 כי נוסח הברכה הוא: \"ברוך... \u0003נאמן בבריתו וקיים במאמרו\". אמר רב פפא: הלכך נימרינהו לתרוייהו\u0004 \u0005[על כן נאמר את שניהם]\u0006 בנוסחה משולבת \u0003\"ברוך... זוכר הברית, ונאמן בבריתו, וקיים במאמרו\".\u0004","שנינו במשנה כי \u0003על ההרים ועל הגבעות\u0004 מברך \"ברוך... עושה בראשית\". ושואלים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003כל הני דאמרן\u0004 \u0005[אלה שאמרנו]\u0006 \u0003עד השתא\u0004 \u0005[עכשיו],\u0006 וכגון ברקים, \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מעשה בראשית נינהו\u0004 \u0005[הם]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בין שאר שבחי ה' בבריאת העולם ובעשיית ההרים נזכר גם כי \u0003\"ברקים למטר עשה\"\u0004 (תהלים קלה, ז)! \u0003אמר אביי: כרוך\u0004 את שתי הברכות הללו, \u0003ותני\u0004 \u0005[ושנה]\u0006 שבכל המקרים שבמשנה יש לברך שתי ברכות אלו. ו\u0003רבא אמר: התם\u0004 \u0005[שם]\u0006 על ברקים ורעמים \u0003מברך תרתי\u0004 \u0005[שתים]\u0006 — \u0003\"ברוך... שכחו מלא עולם\", ו\"עושה מעשה בראשית\".\u0004 ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 על ההרים והגבעות ברכת \u0003\"עושה מעשה בראשית\"\u0004 — \u0003איכא\u0004 \u0005[יש],\u0006 ואולם \u0003\"שכחו מלא עולם\" ליכא\u0004 \u0005[אין],\u0006 שאין למראה העין מקום לברך על התגלות כוח ה'.","\u0003אמר ר' יהושע בן לוי: הרואה רקיע בטהרתה, אומר: \"ברוך... עושה בראשית\".\u0004 ושואלים: \u0003אימתי\u0004 נראה כך הרקיע? \u0003אמר אביי: כי אתא מטרא כולי ליליא, ובצפרא אתא אסתנא ומגליא להו לשמיא\u0004 \u0005[כאשר בא,\u0006 יורד, \u0005הגשם כל הלילה, ובבוקר נושבת רוח צפונית ומגלה את השמים].\u0006","ומעירים: \u0003ופליגי\u0004 \u0005[וחלוקים\u0006 הם\u0005]\u0006 בדבר זה על דברי \u0003רפרם בר פפא\u0004 ש\u0003אמר\u0004 בשם \u0003רב חסדא.\u0004 ש\u0003אמר רפרם בר פפא אמר רב חסדא: מיום שחרב בית המקדש לא נראית רקיע בטהרתה, שנאמר: \"אלביש שמים קדרות ושק אשים כסותם\"\u0004 (ישעיהו נ, ג)."],["\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרואה חמה בתקופתה, לבנה בגבורתה, וכוכבים במסילותם, ומזלות כסדרן, אומר \"ברוך... עושה בראשית\".\u0004 ושואלים: \u0003ואימת הוי\u0004 \u0005[ומתי היא]\u0006 השעה שהחמה בתקופתה? \u0003אמר אביי: כל עשרים ושמונה שנין\u0004 \u0005[שנים],\u0006 כאשר \u0003הדר\u0004 \u0005[חוזר]\u0006 ה\u0003מחזור ונפלה\u0004 \u0005[ונופלת]\u0006 \u0003תקופת ניסן,\u0004 שחל שוויון היום והלילה האביבי \u0003ב\u0004תוך מזל \u0003שבתאי באורתא דתלת נגהי ארבע\u0004 \u0005[בליל\u0006 יום \u0005שלישי אור\u0006 ליום \u0005רביעי],\u0006 שאז מצב הדברים חוזר להיות כמו בעת שנתלו המזלות.","שנינו במשנה ש\u0003ר' יהודה אומר\u0004 ש\u0003הרואה\u0004 את \u0003הים הגדול\u0004 מברך \"ברוך שעשה את הים הגדול\", וזהו דווקא כשרואהו לפרקים. ושואלים: \u0003\"לפרקים\"\u0004 ששנינו \u0003עד כמה\u0004 הוא? \u0003אמר רמי בר אבא אמר רב יצחק: עד שלשים יום. ו\u0004עוד","\u0003אמר רמי בר אבא אמר רב יצחק: הרואה פרת אגשרא\u0004 \u0005[ליד הגשר]\u0006 של \u0003בבל, אומר: \"ברוך... עושה בראשית\".\u0004 ומוסיפים: \u0003והאידנא דשניוה פרסאי\u0004 — \u0003מבי שבור ולעיל\u0004 \u0005[ועכשיו ששינוהו הפרסים,\u0006 את מהלך הנהר — \u0005אפשר לברך רק מבית שבור ולמעלה],\u0006 אבל במורד הנהר שוב אינו זורם כבראשית, ואין לברך עליו \"עושה מעשה בראשית\". ו\u0003רב יוסף אמר:\u0004 יש לברך רק \u0003מאיהי דקירא ולעיל\u0004 \u0005[ולמעלה].\u0006 \u0003ו\u0004כן \u0003אמר רמי בר אבא: הרואה דגלת\u0004 (חדקל) \u0003אגשרא\u0004 \u0005[ליד הגשר]\u0006 של \u0003שביסתנא, אומר: \"ברוך... עושה בראשית\".\u0004 ואגב הזכרת הנהרות מסבירים את שמותיהם.","\u0003מאי\u0004 \u0005[מה]\u0006 מקור השם \u0003\"חדקל\"\u0004 — \u0003אמר רב אשי:\u0004 שמו נגזר ממה \u0003שמימיו חדין\u0004 (חריפים) \u0003וקלין\u0004 (קלים) במשקלם, ולכן טובים הם לשתיה. \u0003מאי\u0004 \u0005[מה]\u0006 הוא מקור השם \u0003\"פרת\"?\u0004 — \u0003שמימיו פרין ורבין,\u0004 שמרובים בהם הדגים.","\u0003ו\u0004מכיון שהוזכר נהר החדקל מובא כאן מה ש\u0003אמר רבא: האי דחריפי\u0004 \u0005[זה שחריפים]\u0006 \u0003בני\u0004 העיר \u0003מחוזא\u0004 — הרי זה \u0003משום דשתו מיא דדגלת\u0004 \u0005[ש\u0006הם \u0005שותים\u0006 את \u0005מי החדקל].\u0006 \u0003האי דגיחורי\u0004 \u0005[זה ש\u0006הם \u0005אדמונים]\u0006 — הרי זה \u0003משום דמשמשי ביממא\u0004 \u0005[ש\u0006הם \u0005משמשים\u0006 מיטתם \u0005ביום].\u0006 \u0003והאי דניידי עינייהו\u0004 \u0005[וזה שעיניהם נדות]\u0006 תמיד — הרי זה משום \u0003דדיירו\u0004 \u0005[ש\u0006הם \u0005דרים]\u0006 \u0003בבית אפל.\u0004","שנינו במשנה ש\u0003על הגשמים\u0004 יש לברך \"ברוך... הטוב והמטיב\". ושואלים: \u0003ו\u0004האם \u0003על הגשמים \"הטוב והמטיב\"\u0004 הוא ש\u0003מברך? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבהו, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי דבר זה \u0003במתניתא תנא\u0004 \u0005[בברייתא\u0006 הוא \u0005שנוי]:\u0006 \u0003מאימתי מברכין על הגשמים\u0004 — \u0003משיצא חתן לקראת כלה.\u0004 כלומר, שיש שלוליות מים בחוץ, וטיפות המים הבאות מלמעלה (החתן) מקפיצות כנגדן טיפות מלמטה (הכלה).","ושואלים: \u0003מאי\u0004 \u0005[מה],\u0006 איזו ברכה \u0003מברכין? אמר רב יהודה:\u0004 נוסח הברכה הוא \u0003\"מודים אנחנו לך על כל טפה וטפה שהורדת לנו\". ור' יוחנן מסיים בה,\u0004 בנוסח ברכה זו \u0003הכי\u0004 \u0005[כך]:\u0006 \u0003\"אילו פינו מלא שירה כים... אין אנחנו מספיקין להודות לך ה' אלהינו\"\u0004 והלאה מתפילת \"נשמת\" \u0003עד \"תשתחוה. ברוך אתה ה' רוב ההודאות\".\u0004","ובדרך אגב שואלים: נוסח הברכה הוא \u0003\"רוב ההודאות\" ולא \"כל ההודאות\"?\u0004 שהרי לקדוש ברוך הוא כל ההודאות! \u0003אמר רבא: אימא\u0004 \u0005[אמור]\u0006 ותקן: \u0003\"האל ההודאות\". אמר רב פפא: הלכך נימרינהו לתרוייהו\u0004 \u0005[על כן יאמרו את שתיהן,\u0006 שתי הנוסחאות\u0005],\u0006 \u0003\"רוב ההודאות\" ו\"האל ההודאות\".\u0004","\u0003ואלא\u0004 עדיין \u0003קשיא\u0004 \u0005[קשה],\u0006 שהלא רואים שנוסח הברכה על הגשמים אינו \"הטוב והמטיב\" כפי המובא במשנתנו! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו במשנה שמברך \"הטוב והמטיב\", הרי זה באופן \u0003דשמע משמע\u0004 \u0005[שהוא שמע]\u0006 את הגשם יורד. \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שמברך \"מודים אנחנו לך...\", הרי זה באופן \u0003דחזא מחזי\u0004 \u0005[שראה]\u0006 אותו יורד.","ושואלים: \u0003דשמע משמע\u0004 \u0005[שהוא שמע]\u0006 את הגשמים יורדים הלא \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003בשורות טובות, ותנן על בשורות טובות אומר ברוך הטוב והמטיב\u0004 שבשורת הגשם בכלל בשורות טובות שאנו יודעים כבר שאומר עליהן \"הטוב והמטיב\", ואם כן אין מקום להזכיר במיוחד את הגשם!","\u0003אלא\u0004 יש לתרץ בדרך אחרת: \u0003אידי ואידי דחזי מחזי\u0004 \u0005[זה וזה\u0006 מדובר באופן \u0005שראה]\u0006 את הגשם, \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שמברך \"מודים אנחנו לך...\", הרי זה באופן \u0003דאתא פורתא\u0004 \u0005[שבא,\u0006 ירד \u0005מעט]\u0006 גשם, \u0003הא\u0004 \u0005[זה]\u0006 ששנינו במשנה שמברך \"הטוב והמטיב\", הרי זה באופן \u0003דאתא טובא\u0004 \u0005[שבא,\u0006 ירד \u0005הרבה]\u0006 גשם. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי \u0003הא והא דאתא טובא\u0004 \u0005[זה וזה\u0006 מדובר באופן \u0005שבא הרבה]\u0006 גשם, \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שמברך \"הטוב והמטיב\", הרי זה באופן \u0003דאית ליה ארעא\u0004 \u0005[שיש לו קרקע],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שמברך \"מודים אנחנו לך...\", הרי זה באופן \u0003דלית ליה ארעא\u0004 \u0005[שאין לו קרקע],\u0006 ואין זו עבורו במישרין בשורה טובה.","ושואלים: וכאשר \u0003אית ליה ארעא\u0004 \u0005[יש לו קרקע]\u0006 \u0003\"הטוב והמטיב\"\u0004 הוא ש\u0003מברך?! והא תנן\u0004 \u0005[והרי שנינו]:\u0006 מי ש\u0003בנה בית חדש,\u0004 או \u0003קנה כלים חדשים, אומר: \"ברוך... שהחיינו והגיענו לזמן הזה\".\u0004 ואם היה זה \u0003שלו ושל אחרים\u0004 — הריהו \u0003אומר: \"הטוב והמטיב\",\u0004 והרי שעל הגשמים היורדים לאדמתו מברך \"שהחיינו\" ולא \"הטוב והמטיב\"?","ומשיבים \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שמברך \"הטוב והמטיב\", הרי זה באופן \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003שותפות\u0004 בקרקע, \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שמברך \"שהחיינו\", הרי זה באופן \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003שותפות\u0004 בקרקע. \u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בדומה: \u0003קצרו של דבר, על\u0004 דבר טוב \u0003שלו,\u0004 שהגיע אליו בלבד, \u0003הוא אומר: \"ברוך... שהחיינו וקיימנו\", על\u0004 דבר טוב \u0003שלו ועל של חבירו\u0004 — \u0003אומר: \"ברוך... הטוב והמטיב\".\u0004","על הכלל הזה מקשים: \u0003וכל היכא דלית לאחרינא בהדיה\u0004 \u0005[מקום שאין לאחרים אתו]\u0006 הוא \u0003לא מברך \"הטוב והמטיב\"? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמרו לו\u0004 ש\u0003ילדה אשתו\u0004 בן \u0003זכר, אומר \"ברוך... הטוב והמטיב\"!\u0004 ומשיבים: \u0003התם נמי, דאיכא\u0004 \u0005[שם גם כן, שיש,\u0006 כשנמצאת\u0005]\u0006 \u0003אשתו בהדיה\u0004 \u0005[אתו]\u0006 \u0003דניחא\u0004 \u0005[שנוח]\u0006 \u0003לה בזכר.\u0004","ועוד מקשים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 דברים סותרים לכך במה ששנינו בברייתא: מי ש\u0003מת אביו והוא\u0004 היה \u0003יורשו, בתחלה,\u0004 כששומע שמת, הריהו \u0003אומר: \"ברוך... דיין האמת\", ולבסוף,\u0004 על הירושה \u0003הוא אומר: \"ברוך... הטוב והמטיב\".\u0004 ואם כן אף על הנאתו שלו מברך \"הטוב והמטיב\"! ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם גם כן]\u0006 מדובר באופן \u0003דאיכא אחי דקא ירתי בהדיה\u0004 \u0005[שיש אחים היורשים יחד אתו].\u0006","ועוד מקשים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 דברים סותרים לכך במה ששנינו בברייתא: \u0003שינוי\u0004 סוג ה\u0003יין\u0004 בתוך הסעודה \u0003אינו צריך לברך\u0004 שנית על היין \"בורא פרי הגפן\", אבל \u0003שינוי מקום צריך לברך\u0004 שוב על היין, \u0003ואמר ר' יוסף בר אבא אמר ר' יוחנן ואף על פי שאמרו\u0004 ש\u0003שינוי יין אינו צריך לברך, אבל אומר: \"ברוך... הטוב והמטיב\"!\u0004 ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 מדובר באופן שאינו לבד, אלא \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003בני חבורה דשתו בהדיה\u0004 \u0005[השותים אתו].\u0006","שנינו במשנה שמי ש\u0003בנה בית חדש\u0004 או \u0003קנה כלים חדשים\u0004 מברך \"ברוך... שהחיינו וקיימנו והגיענו לזמן הזה\". ובנושא זה של ברכת \"שהחיינו\" על כלים חדשים \u0003אמר רב הונא: לא שנו\u0004 שמברך \"שהחיינו\" על קניית כלי חדש \u0003אלא\u0004 כ\u0003שאין לו\u0004 מכבר כלים אחרים \u0003כיוצא בהן\u0004 שנפלו לו בירושה וכדומה, \u0003אבל\u0004 אם \u0003יש לו\u0004 כבר \u0003כיוצא בהן\u0004 — \u0003אינו צריך לברך,\u0004 שאין זה נחשב אצלו כדבר חדש לגמרי. \u0003ור' יוחנן אמר: אפילו יש לו\u0004 כבר \u0003כיוצא בהן\u0004 שנפלו לו בירושה, \u0003צריך לברך,\u0004 כיון שלענין קניה חדשים הם לגביו"],["ומדייקים: \u0003מכלל\u0004 דבריהם למדנו, \u0003דכי\u0004 \u0005[שכאשר]\u0006 \u0003קנה\u0004 חפץ חדש, \u0003וחזר וקנה\u0004 חפץ כיוצא בו ל\u0003דברי הכל אין צריך לברך,\u0004 שהרי כבר ברך פעם אחת על קניית חפץ חדש מסוג זה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 מחלוקת זו בנוסח אחר. \u0003אמר רב הונא: לא שנו\u0004 שמברך \"שהחיינו\" על קניית כלי חדש \u0003אלא כשלא קנה וחזר וקנה, אבל\u0004 אם \u0003קנה וחזר וקנה\u0004 — \u0003אין צריך לברך. ור' יוחנן אמר: אפילו קנה חזר וקנה\u0004 — \u0003צריך לברך. מכלל\u0004 דבריהם למדנו \u0003דכי\u0004 \u0005[שכאשר]\u0006 \u0003יש לו\u0004 כבר כלים כאלו \u0003וקנה\u0004 — ל\u0003דברי הכל צריך לברך.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כל ממה ששנינו בברייתא: מי ש\u0003בנה בית חדש ואין לו\u0004 כבר \u0003כיוצא בו,\u0004 או ש\u0003קנה כלים חדשים ואין לו\u0004 כבר \u0003כיוצא בהם\u0004 — \u0003צריך לברך.\u0004 ואולם אם \u0003יש לו\u0004 כבר \u0003כיוצא בהם\u0004 — \u0003אין צריך לברך,\u0004 אלה \u0003דברי ר' מאיר.\u0004 ואילו \u0003ר' יהודה אומר: בין כך ובין כך,\u0004 גם במקרה זה \u0003צריך לברך.\u0004","ושואלים: \u0003בשלמא ללישנא קמא\u0004 \u0005[נניח לפי הלשון הראשונה]\u0006 של מחלוקת רב הונא ור' יוחנן, אפשר לומר כי \u0003רב הונא\u0004 סבור \u0003כר' מאיר, ור' יוחנן כר' יהודה. אלא ללישנא בתרא\u0004 \u0005[ללשון האחרונה],\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003רב הונא\u0004 אמר \u0003כר' יהודה, אלא ר' יוחנן\u0004 ש\u0003אמר\u0004 דבריו, \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי\u0006 אמר\u0005]?\u0006 שהרי דבריו הם \u0003לא כ\u0004שיטת \u0003ר' מאיר,\u0004 אלא בניגוד להם, \u0003ולא כ\u0004שיטת \u0003ר' יהודה,\u0004 שאין להם סיוע מדברי ר' יהודה!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך ר' יוחנן: הוא הדין\u0004 ש\u0003ל\u0004דעת \u0003ר' יהודה\u0004 כאשר \u0003קנה וחזר וקנה\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003צריך לברך. והא דקא מיפלגי\u0004 \u0005[וזה שהם חלוקים]\u0006 רק \u0003ב\u0004מקרה ש\u0003יש לו\u0004 כבר כלים כאלו \u0003וקנה\u0004 חדשים, אין בכך הוכחה שרק בכך הם חולקים, אלא נאמרה המחלוקת בדרך זו \u0003להודיעך כחו\u0004 של \u0003ר' מאיר,\u0004 ש\u0003אפילו\u0004 כאשר \u0003קנה ויש לו\u0004 כבר כדוגמתם — \u0003אין צריך לברך, וכל שכן\u0004 כאשר \u0003קנה וחזר וקנה\u0004 ש\u0003אין צריך לברך. \u0004","ושואלים: אם זו הסיבה להבאת המחלוקת בצורה זו, \u0003ליפלגו\u0004 \u0005[שיחלקו]\u0006 \u0003ב\u0004מקרה ש\u0003קנה וחזר וקנה\u0004 שלדעת ר' מאיר \u0003אין צריך לברך, להודיעך כחו\u0004 של \u0003ר' יהודה\u0004 המחייב לברך אף בכגון זה! ומשיבים: מוטב להשתמש בנוסח שלפנינו, כיון ש\u0003כח דהתירא\u0004 \u0005[של היתר]\u0006 \u0003עדיף ליה\u0004 \u0005[לו]\u0006 להראות, עד כמה מתיר ר' מאיר שלא לברך.","שנינו במשנה ש\u0003מברך\u0004 אדם \u0003על הרעה\u0004 מעין הברכה שמברך אדם על הטובה, כלומר, על רעה שיש בה לעתיד צד של טוב מברך כפי המצב הקיים.","ושואלים: \u0003היכי דמי\u0004 \u0005[איך הוא בדיוק]?\u0006 מה היו בדיוק הדברים? ומסבירים: \u0003כגון דשקל בדקא בארעיה\u0004 \u0005[שנפרץ הסכר באדמתו],\u0006 \u0003אף על גב דטבא\u0004 \u0005[אף על פי ש\u0006לאחר זמן \u0005טובה]\u0006 \u0003היא, לדידיה\u0004 \u0005[לגביו]\u0006 כיון \u0003דמסקא ארעא\u0004 \u0005[שמעלה האדמה]\u0006 בשל שטפון המים \u0003שירטון ושבחא\u0004 \u0005[ומשתבחת]\u0006 בכך, \u0003השתא מיהא\u0004 \u0005[עכשיו בכל אופן]\u0006 \u0003רעה היא.\u0004","\u0003ו\u0004עוד שנינו במשנה ש\u0003על הטובה\u0004 שיש בה מעין רעה מברך על הטוב.","ושואלים: \u0003היכי דמי\u0004 \u0005[איך הוא בדיוק]?\u0006 מה היו בדיוק הדברים? ומסבירים: \u0003כגון דאשכח\u0004 \u0005[שמצא]\u0006 \u0003מציאה, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003רעה היא לדידיה\u0004 \u0005[לגביו],\u0006 משום \u0003דאי שמע בה מלכא\u0004 \u0005[שאם ישמע עליה המלך]\u0006 הרי בודאי \u0003שקיל לה מיניה\u0004 \u0005[יקח אותה ממנו],\u0006 מכל מקום \u0003השתא מיהא\u0004 \u0005[עכשיו בכל אופן]\u0006 \u0003טובה היא,\u0004 כי לפי החוק אז היו כל האבידות שייכות לאוצר המלך, ומי שלא מסרן אף נידון לעונש.","שנינו במשנה שאם \u0003היתה אשתו מעוברת ואמר: \"יהי רצון שתלד\u0004 אשתי בן זכר \u0003\"\u0004— \u0003הרי זו תפלת שוא. \u0004","ומכאן אתה למד כי \u0003לא מהני רחמי\u0004 \u0005[מועילה\u0006 בקשת \u0005רחמים]?\u0006 \u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב יוסף:\u0004 נאמר \u0003\"ואחר ילדה בת ותקרא את שמה דינה\"\u0004 (בראשית ל, כא), ויש לשאול: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות ההדגשה \"ואחר\", מה רוצה הכתוב לומר בהדגשת העובדה שלאחר לידת זבולון ילדה את דינה? \u0003אמר רב: לאחר שדנה לאה דין בעצמה ואמרה: שנים עשר שבטים עתידין לצאת מיעקב, ששה יצאו ממני וארבעה מן השפחות, הרי עשרה,\u0004 ו\u0003אם זה\u0004 הולד שבהריון \u0003זכר, לא תהיה אחותי\u0004 רחל אף \u0003כאחת השפחות, מיד נהפכה לבת, שנאמר: \"ותקרא את שמה דינה\"\u0004 על שם הדין. ודוחים: \u0003אין מזכירין מעשה נסים\u0004 ללמוד ממנו הלכה כללית.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 כי ה\u0003מעשה\u0004 של \u0003לאה\u0004 שהתפללה על הולד \u0003בתוך ארבעים יום\u0004 ליצירה \u0003הוה\u0004 \u0005[היה].\u0006 \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003שלשה ימים הראשונים\u0004 לאחר הביאה — \u0003יבקש אדם רחמים שלא יסריח\u0004 הזרע אלא יקלט ויהיה ולד. \u0003משלשה\u0004 ימים \u0003ועד ארבעים\u0004 יום \u0003יבקש רחמים שיהא זכר. מארבעים יום\u0004 ו\u0003עד שלשה חדשים\u0004 — \u0003יבקש רחמים שלא יהיה סנדל,\u0004 שכאשר העובר אינו מתפתח הריהו מקבל צורה הדומה קצת לדג הסנדל. \u0003משלשה חדשים ועד ששה\u0004 חדשים — \u0003יבקש רחמים שלא יהא נפל.\u0004 ו\u0003מששה\u0004 חדשים \u0003ועד תשעה\u0004 חדשים — \u0003יבקש רחמים שיצא בשלום.\u0004 הרי שבתוך ארבעים הימים הראשונים ליצירת הולד עדיין אפשר להתפלל ולשנות את מינו.","ושואלים: \u0003ומי מהני רחמי\u0004 \u0005[והאם מועילה\u0006 בקשת \u0005רחמים]\u0006 לענין זה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אמי:\u0004 מסורת היא שברגע היצירה נקבע מינו של הוולד, שאם ה\u0003איש מזריע תחלה\u0004 — \u0003יולדת\u0004 אשתו \u0003נקבה,\u0004 ואם ה\u0003אשה מזרעת תחלה\u0004 — \u0003יולדת זכר.\u0004 ורמז לדבר ממה \u0003שנאמר: \"אשה כי תזריע וילדה זכר\"\u0004 (ויקרא יב, ב)! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שהזריעו שניהם בבת אחת,\u0004 ומינו של הולד לא נקבע עדיין, ויש מקום לתפילה.","שנינו במשנה שאם \u0003היה\u0004 אדם \u0003בא בדרך\u0004 ושמע קול צוחה בעיר והתפלל שלא תהיה בתוך ביתו — הרי זו תפילת שוא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בהלל הזקן שהיה בא\u0004 פעם \u0003בדרך ושמע קול צוחה בעיר,\u0004 ו\u0003אמר: מובטח אני שאין זה בתוך ביתי. ועליו הכתוב אומר: \"משמועה רעה לא יירא נכון לבו בטח בה'\"\u0004 (תהלים קיב, ז). \u0003אמר רבא: כל היכי דדרשת להאי קרא\u0004 \u0005[בכל דרך שאתה דורש את הפסוק הזה]\u0006 הוא נדרש; \u0003מרישיה לסיפיה\u0004 \u0005[מראשו לסופו]\u0006 — \u0003מדריש\u0004 \u0005[\u0006הוא \u0005נדרש],\u0006 \u0003מסיפיה לרישיה\u0004 \u0005[מסופו לראשו]\u0006 — \u0003מדריש\u0004 \u0005[\u0006הוא \u0005נדרש].\u0006 ומפרטים: \u0003מרישיה לסיפיה מדריש\u0004 \u0005[מראשו לסופו\u0006 הוא \u0005נדרש]\u0006 — \u0003\"משמועה רעה לא יירא\", מה טעם\u0004 לא יירא? — כפי שנאמר בהמשך: כי \u0003\"נכון לבו בטח בה'\".\u0004 ו\u0003מסיפיה לרישיה מדריש\u0004 \u0005[מסופו לראשו\u0006 הוא \u0005נדרש]\u0006 — מי ש\u0003\"נכון לבו בטח בה'\",\u0004 אותו אדם \u0003\"משמועה רעה לא יירא\".\u0004","מסופר: \u0003ההוא תלמידא דהוה קא אזיל בתריה\u0004 \u0005[תלמיד אחד שהיה הולך אחרי]\u0006 \u0003ר' ישמעאל בר' יוסי בשוקא\u0004 \u0005[בשוק]\u0006 של \u0003ציון. חזייה דקא מפחיד\u0004 \u0005[ראהו\u0006 ר' ישמעאל לאותו תלמיד \u0005שהוא מפחד].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חטאה את\u0004 \u0005[חוטא אתה],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"פחדו בציון חטאים\u0004 רעדה אחזה חנפים\u0003\"\u0004 (ישעיהו לג, יד). \u0003אמר ליה\u0004 \u0005[לו]:\u0006 התלמיד: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"אשרי אדם מפחד תמיד\"\u0004 (משלי כח, יד)! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ישמעאל: הפסוק \u0003ההוא בדברי תורה כתיב\u0004 \u0005[\u0006הוא ש\u0005נאמר],\u0006 שיש לפחד שמא ישכחם, אך בשאר עליו לבטוח בה'.","בדומה קצת לכך מסופר: \u0003יהודה בר נתן הוה שקיל ואזיל בתריה\u0004 \u0005[היה הולך אחרי]\u0006 \u0003רב המנונא. אתנח\u0004 \u0005[נאנח]\u0006 יהודה בר נתן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב המנונא: וכי \u0003יסורים בעי ההוא גברא לאתויי אנפשיה\u0004 \u0005[רוצה אותו אדם להביא על עצמו]?\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"כי פחד פחדתי ויאתיני ואשר יגרתי יבא לי\"\u0004 (איוב ג, כה)! שאלו: \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"אשרי אדם מפחד תמיד\"!\u0004 וענה רב המנונא: הפסוק \u0003ההוא בדברי תורה כתיב\u0004 \u0005[\u0006הוא ש\u0005נאמר].\u0006","שנינו במשנה ש\u0003הנכנס לכרך\u0004 מברך שתי ברכות ולדעת בן עזאי ארבע ברכות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא פירוט שיטתו של בן עזאי: לקראת \u0003כניסתו\u0004 לעיר \u0003מהו אומר?\u0004 — \u0003\"יהי רצון מלפניך ה' אלהי שתכניסני לכרך זה לשלום\". נכנס\u0004 לעיר, \u0003אומר: \"מודה אני לפניך ה' אלהי שהכנסתני לכרך זה לשלום\". בקש לצאת\u0004 מהעיר, \u0003אומר: \"יהי רצון מלפניך ה' אלהי ואלהי אבותי, שתוציאני מכרך זה לשלום\". יצא, אומר: \"מודה אני לפניך ה' אלהי שהוצאתני מכרך זה לשלום. וכשם שהוצאתני לשלום, כך תוליכני לשלום, ותסמכני לשלום, ותצעידני לשלום, ותצילני מכף כל אויב ואורב בדרך\".\u0004","\u0003אמר רב מתנא: לא שנו\u0004 דברים אלה \u0003אלא בכרך שאין דנין והורגין בו,\u0004 שבאותו כרך עלול הוא ליהרג בלא משפט, \u0003אבל בכרך שדנין והורגין בו\u0004 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש ואינו צריך לתפילה זו, שהרי אם הוא חף מפשע — לא ינזק.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר רב מתנא\u0004 להיפך: ש\u0003אפילו בכרך שדנין והורגין בו\u0004 צריך לבקש רחמים, מפני ש\u0003זימנין דלא מתרמי ליה אינש דיליף ליה זכותא\u0004 \u0005[לפעמים אין מזדמן לו אדם שילמד עליו זכות].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנכנס לבית המרחץ,\u0004 בבתי מרחצאות רומיים שהאש היתה לוהטת מתחת לבריכת המים שבה היו מתרחצים, והיתה סכנת מפולת אל תוך האש, \u0003אומר\u0004 הנכנס: \u0003\"יהי רצון מלפניך ה' אלהי שתצילני מזה וכיוצא בו, ואל יארע בי דבר קלקלה ועון. ואם יארע בי דבר קלקלה ועון\u0004 — \u0003תהא מיתתי כפרה לכל עונותי\".\u0004","\u0003אמר אביי: לא לימא אינש הכי\u0004 \u0005[יאמר אדם כך],\u0006 \"אם יארע בי דבר קלקלה\", כדי ש\u0003לא לפתח פומיה\u0004 \u0005[יפתח\u0006 בכך \u0005פיו]\u0006 \u0003לשטן.\u0004 ש\u0003אמר ריש לקיש, וכן תנא\u0004 \u0005[שנו]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוסי: לעולם אל יפתח אדם פיו לשטן\u0004 להעלות מרצונו אפשרות של תקלה או מיתה.","\u0003אמר רב יוסף: מאי קראה\u0004 \u0005[מהו המקרא]\u0006 המרמז על כך — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כמעט כסדם היינו לעמרה דמינו\"\u0004 (ישעיהו א, ט) ואחר כך \u0003מאי אהדר להו\u0004 \u0005[מה החזיר להם]\u0006 הנביא — \u0003\"שמעו דבר ה' קציני סדם\u0004 האזינו תורת אלהינו עם עמורה\" (שם, י), הרי שעם הדימוי לסדום התקיים הדבר אחר כך בפועל.","וחוזרים לאותו אדם שנכנס לבית המרחץ, ושואלים: \u0003כי נפיק מאי\u0004 \u0005[כאשר יוצא,\u0006 מבית המרחץ, \u0005מה]\u0006 הוא \u0003אומר? אמר רב אחא,\u0004 יאמר: \u0003\"מודה אני לפניך שהצלתני מן האור\"\u0004 (אש).","מסופר: \u0003ר' אבהו על לבי בני\u0004 \u0005[נכנס לבית המרחץ].\u0006 \u0003אפחית בי בני מתותיה, אתרחיש ליה ניסא קם על עמודא, שזיב מאה וחד גברי בחד אבריה\u0004 \u0005[נפחת בית המרחץ מתחתיו,\u0006 ו\u0005התרחש לו נס\u0006 ש\u0005עמד על עמוד\u0006 ו\u0005הציל מאה ואחד אנשים בזרועו האחת],\u0006 שהוא החזיק בזרועו אדם אחד או שנים, ונתלו בהם אחרים ואחרים באחרים, עד שניצולו כולם. \u0003אמר: היינו\u0004 \u0005[זהו]\u0006 מה שאמר \u0003רב אחא.\u0004 כלומר, הרי זה אישור לדברי רב אחא שיש להודות על יציאה בשלום מהמרחץ.","שכך \u0003אמר רב אחא: הנכנס להקיז דם, אומר: \"יהי רצון מלפניך ה' אלהי שיהא עסק זה לי לרפואה, ותרפאני. כי אל רופא נאמן אתה ורפואתך אמת, לפי שאין דרכן של בני אדם לרפאות אלא שנהגו\".\u0004 כלומר, אין בכוחם של בני אדם ולא היה ראוי להם לעסוק ברפואה, אלא להניח את הדבר למעשה ה'.","על כך \u0003אמר אביי: לא לימא אינש הכי\u0004 \u0005[אל יאמר אדם כך],\u0006 \u0003דתני דבי\u0004 \u0005[ש\u0006הרי \u0005שנו בבית]\u0006 מדרשו של \u0003ר' ישמעאל\u0004 על הנאמר \u0003\"ורפא ירפא\"\u0004 (שמות כא, יט) — \u0003מכאן שניתנה רשות לרופא לרפאות.\u0004 ולכן אין לומר שהרפואה היא רק מנהג בני אדם, שלא לפי רצון ה'.","ובקשר למקיז דם שואלים: \u0003כי קאי מאי\u0004 \u0005[כאשר\u0006 הוא \u0005עומד\u0006 מן ההקזה \u0005מה]\u0006 הוא \u0003אומר?\u0004 — \u0003אמר רב אחא:\u0004 יאמר בהודאה \u0003\"ברוך... רופא חנם\".\u0004"],["\u0003הנכנס לבית הכסא, אומר\u0004 למלאכים המלווים אותו בכל עת: \u0003\"התכבדו מכובדים קדושים משרתי עליון, תנו כבוד לאלהי ישראל, הרפו ממני עד שאכנס ואעשה רצוני ואבא אליכם\". אמר אביי: לא לימא אינש הכי, דלמא שבקי ליה ואזלי\u0004 \u0005[אל יאמר אדם כך, שמא יעזבו אותו וילכו].\u0006 \u0003אלא לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"שמרוני שמרוני, עזרוני עזרוני, סמכוני סמכוני, המתינו לי המתינו לי עד שאכנס ואצא, שכן דרכן של בני אדם\". כי נפיק\u0004 \u0005[כאשר\u0006 הוא \u0005יוצא],\u0006 \u0003אומר: \"ברוך... אשר יצר את האדם בחכמה, וברא בו נקבים נקבים, חללים חללים, גלוי וידוע לפני כסא כבודך שאם יפתח אחד מהם או אם יסתם אחד מהם אי אפשר לעמוד לפניך\".\u0004","ושואלים: \u0003מאי חתים\u0004 \u0005[\u0006ב\u0005מה\u0006 הוא \u0005חותם]\u0006 ברכה זו? \u0003אמר רב:\u0004 יש לחתום \u0003\"\u0004ברוך... \u0003רופא חולים\". אמר שמואל: קא שוינהו\u0004 \u0005[עשה]\u0006 \u0003אבא,\u0004 רב, \u0003לכולי עלמא קצירי\u0004 \u0005[את כל העולם חולים].\u0006 \u0003אלא\u0004 יש לומר: \u0003\"רופא כל בשר\". רב ששת אמר:\u0004 יש לחתום בנוסח \u0003\"מפליא לעשות\". אמר רב פפא: הלכך נמרינהו לתרוייהו\u0004 \u0005[על כן נאמר את שתיהן,\u0006 שתי הנוסחאות\u0005].\u0006 \u0003\"רופא כל בשר ומפליא לעשות\".\u0004","מאחר שדובר בברכות הרגילות בכל יום מובאות עוד ברכות השייכות לסדר החיים היום יומי. \u0003הנכנס לישן על מטתו, אומר\u0004 קריאת שמע שעל המטה \u0003מ\"שמע ישראל\" עד \"והיה אם שמוע\", ו\u0004אחר כך \u0003אומר: \"ברוך... המפיל חבלי שינה על עיני ותנומה על עפעפי, ומאיר לאישון בת עין. יהי רצון מלפניך ה' אלהי, שתשכיבני לשלום, ותן חלקי בתורתך, ותרגילני לידי מצוה, ואל תרגילני לידי עבירה, ואל תביאני לידי חטא, ולא לידי עון, ולא לידי נסיון, ולא לידי בזיון. וישלוט בי יצר טוב, ואל ישלוט בי יצר הרע. ותצילני מפגע רע, ומחלאים רעים. ואל יבהלוני חלומות רעים והרהורים רעים. ותהא מטתי שלמה לפניך\u0004 (שלא יהיה פסול בצאצאיו). \u0003והאר עיני\u0004 (בבוקר) \u0003פן אישן המות\u0004 (ולא אתעורר משינה זו). \u0003ברוך אתה ה' המאיר לעולם כולו בכבודו\".\u0004","\u0003כי מתער\u0004 \u0005[כאשר מתעורר]\u0006 הריהו \u0003אומר: \"אלהי, נשמה שנתת בי טהורה. אתה יצרתה בי, אתה נפחתה בי, ואתה משמרה בקרבי, ואתה עתיד ליטלה ממני ולהחזירה בי לעתיד לבא. כל זמן שהנשמה בקרבי מודה אני לפניך ה' אלהי ואלהי אבותי, רבון כל העולמים, אדון כל הנשמות. ברוך אתה ה', המחזיר נשמות לפגרים מתים\".\u0004","\u0003כי שמע\u0004 \u0005[כאשר שומע]\u0006 את \u0003קול תרנגולא\u0004 \u0005[התרנגול],\u0006 \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... אשר נתן לשכוי בינה להבחין בין יום ובין לילה\". כי פתח עיניה\u0004 \u0005[כאשר פותח את עיניו]\u0006 \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... פוקח עורים\". כי תריץ ויתיב\u0004 \u0005[כאשר מתיישר ויושב]\u0006 \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... מתיר אסורים\". כי לביש\u0004 \u0005[כאשר מתלבש]\u0006 \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... מלביש ערומים\"\u0004 (כי היו רגילים לישון בלי לבוש). \u0003כי זקיף\u0004 \u0005[כאשר מזדקף]\u0006 \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... זוקף כפופים\". כי נחית לארעא\u0004 \u0005[כאשר יורד לארץ]\u0006 מן המיטה \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... רוקע הארץ על המים\",\u0004 כהודאה על שיש מתחת לרגליו קרקע יציבה לדרוך עליה. \u0003כי מסגי\u0004 \u0005[כאשר הולך]\u0006 \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... המכין מצעדי גבר\". כי סיים מסאניה\u0004 \u0005[כאשר נועל\u0006 את \u0005נעליו]\u0006 \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... שעשה לי כל צרכי\",\u0004 שהנעליים הן תוספת הכרחית לצרכי האדם. \u0003כי אסר המייניה\u0004 \u0005[כאשר חוגר\u0006 את \u0005חגורתו]\u0006 \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... אוזר ישראל בגבורה\". כי פריס סודרא על רישיה\u0004 \u0005[כאשר פורש\u0006 את \u0005הסודר על ראשו]\u0006 \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... עוטר ישראל בתפארה\".\u0004","\u0003כי מעטף\u0004 \u0005[כאשר מתעטף]\u0006 \u0003בציצית\u0004 (טלית מצוייצת) \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... אשר קדשנו במצותיו וצונו להתעטף בציצית\". כי מנח\u0004 \u0005[כאשר מניח]\u0006 \u0003תפילין אדרעיה\u0004 \u0005[על זרועו]\u0006 \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... אשר קדשנו במצותיו וצונו להניח תפילין\",\u0004 וכאשר הוא מניחן \u0003ארישיה\u0004 \u0005[על ראשו]\u0006 \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... אשר קדשנו במצותיו וצונו על מצות תפילין\". כי משי ידיה\u0004 \u0005[כאשר רוחץ ידיו]\u0006 \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003\"ברוך... אשר קדשנו במצותיו וצונו על נטילת ידים\". כי משי אפיה\u0004 \u0005[כאשר\u0006 הוא \u0005רוחץ\u0006 את \u0005פניו]\u0006 \u0003לימא\u0004 \u0005[יאמר]:\u0006 \u0003ברוך... המעביר חבלי שינה מעיני ותנומה מעפעפי. ויהי רצון מלפניך ה' אלהי, שתרגילני בתורתך, ודבקני במצותיך, ואל תביאני לא לידי חטא, ולא לידי עון, ולא לידי נסיון, ולא לידי בזיון. וכוף את יצרי להשתעבד לך. ורחקני מאדם רע, ומחבר רע. ודבקני ביצר טוב ובחבר טוב בעולמך. ותנני היום ובכל יום לחן ולחסד ולרחמים בעיניך ובעיני כל רואי, ותגמלני חסדים טובים. ברוך אתה ה' גומל חסדים טובים לעמו ישראל\".\u0004","שנינו במשנה ש\u0003חייב אדם לברך\u0004 על הרעה כשם שמברך על הטובה. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חייב לברך על הרעה כשם שמברך על הטובה\"? אילימא\u0004 \u0005[אם נאמר]\u0006 שמשמעות הדבר ש\u0003כשם שמברך על הטובה\u0004 בנוסח \u0003\"הטוב והמטיב\", כך מברך\u0004 גם \u0003על הרעה\u0004 בנוסח \u0003\"הטוב והמטיב\", והתנן\u0004 \u0005והרי שנינו\u0006 במשנתנו\u0005]\u0006 ש\u0003על בשורות טובות אומר \"הטוב והמטיב\"\u0004 ואילו \u0003על בשורות רעות אומר \"ברוך... דיין האמת\"!\u0004 אלא \u0003אמר רבא: לא נצרכה\u0004 הערה זו במשנה לענין נוסח הברכה, \u0003אלא לקבולינהו\u0004 \u0005[לקבל אותן]\u0006 \u0003בשמחה,\u0004 שגם את הבשורות הרעות יש לקבל באותה הרגשה שהוא מקבל את הטובות.","\u0003אמר רב אחא משום\u0004 (בשם) \u0003ר' לוי: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך — \u0003\"חסד ומשפט אשירה לך ה' אזמרה\"\u0004 (תהלים קא, א). ומפרש: \u0003אם\u0004 שיהא זה \u0003חסד\u0004 — \u0003אשירה, ואם משפט\u0004 (דין קשה) — \u0003אשירה,\u0004 שאודה לה' בשירה על הרעה כעל הטובה.","\u0003ר' שמואל בר נחמני אמר,\u0004 הראיה היא \u0003מהכא\u0004 \u0005[מכאן],\u0006 ממה שנאמר: \u0003\"בה' אהלל דבר באלהים אהלל דבר\"\u0004 (תהלים נו, יא), ומפרש: \u0003\"בה' אהלל דבר\"\u0004 — \u0003זו\u0004 הגילוי של מידת הרחמים, מדה טובה, \u0003\"באלהים אהלל דבר\"\u0004 — \u0003זו מדת פורענות,\u0004 שאף אם יביא עלי מדת פורענות — אף על פי כן אהלל.","\u0003ר' תנחום אמר:\u0004 הראיה היא \u0003מהכא\u0004 \u0005[מכאן],\u0006 ממה שנאמר: \u0003\"כוס ישועות אשא ובשם ה' אקרא\"\u0004 (שם קטז, יג), וגם \u0003\"צרה ויגון אמצא ובשם ה' אקרא\"\u0004 (שם ג–ד).","\u0003ורבנן אמרי, מהכא\u0004 \u0005[וחכמים אומרים\u0006 כי הראיה היא \u0005מכאן],\u0006 ממה שנאמר: \u0003\"ה' נתן וה' לקח יהי שם ה' מברך\"\u0004 (איוב א, כא).","\u0003אמר רב הונא\u0004 ש\u0003אמר רב משום\u0004 (בשם) \u0003ר' מאיר, וכן תנא משמיה\u0004 \u0005[שנויה\u0006 בריתא \u0005משמו]\u0006 של \u0003ר' עקיבא: לעולם יהא אדם רגיל לומר: \"כל דעביד רחמנא לטב עביד\"\u0004 \u0005[כל מה שעושה הקדוש ברוך הוא, לטוב\u0006 הוא \u0005עושה].\u0006","ומסופר, \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 שהיה ב\u0003ר' עקיבא דהוה קאזיל באורחא\u0004 \u0005[שהיה הולך בדרך].\u0006 \u0003מטא לההיא מתא, בעא אושפיזא\u0004 \u0005[הגיע לעיר אחת, ביקש מלון]\u0006 \u0003ולא יהבי ליה\u0004 \u0005[נתנו לו].\u0006 \u0003אמר: \"כל\u0004 מה \u0003דעביד רחמנא\u0004 — \u0003לטב\"\u0004 \u0005[שעושה ה'\u0006 — \u0005לטובה\u0006 עושה\u0005].\u0006 \u0003אזל ובת בדברא, והוה בהדיה תרנגולא וחמרא ושרגא\u0004 \u0005[הלך ולן בשדה, והיו עמו תרנגול וחמור ונר].\u0006 \u0003אתא זיקא כבייה לשרגא\u0004 \u0005[באה רוח\u0006 ו\u0005כבתה את הנר].\u0006 \u0003אתא שונרא אכליה לתרנגולא\u0004 \u0005[בא חתול\u0006 ו\u0005אכל את התרנגול].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אריה אכליה לחמרא\u0004 \u0005[\u0006ו\u0005אכל את החמור].\u0006 \u0003אמר: \"כל\u0004 מה \u0003דעביד רחמנא\u0004 — \u0003לטב\"\u0004 \u0005[שעושה הקדוש ברוך הוא\u0006 — \u0005לטובה\u0006 עושה\u0005].\u0006 \u0003ביה בליליא אתא גייסא, שבייה למתא\u0004 \u0005[בו בלילה בא גייס,\u0006 ו\u0005שבה את העיר],\u0006 והתברר שר' עקיבא שלא היה בעיר, ולא היה עמו לא נר דולק ולא תרנגול או חמור שיקימו רעש — הוא לבדו ניצל מהגייס. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לאו אמרי לכו\u0004 \u0005[וכי לא אמרתי לכם]\u0006 כי \u0003כל מה שעושה הקדוש ברוך הוא\u0004"],["\u0003הכל לטובה.\u0004","\u0003ו\u0004עוד \u0003אמר רב הונא אמר רב משום\u0004 (בשם) \u0003ר' מאיר: לעולם יהיו דבריו של אדם מועטין לפני הקדוש ברוך הוא, שנאמר: \"אל תבהל על פיך ולבך אל ימהר להוציא דבר לפני האלהים כי האלהים בשמים ואתה על הארץ על כן יהיו דבריך מעטים\"\u0004 (קהלת ה, א).","\u0003דרש רב נחמן בר רב חסדא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"וייצר ה' אלהים את האדם\"\u0004 (בראשית ב, ז) \u0003בשני יו\"דין?\u0004 — לרמז כי \u0003שני יצרים ברא הקדוש ברוך הוא, אחד יצר טוב ואחד יצר רע.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן בר יצחק: אלא מעתה, בהמה\u0004 ש\u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה \"וייצר\"\u0004 בשני יו\"דים האם \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה יצרא\u0004 \u0005[יצר]?\u0006 \u0003והא קא חזינן דמזקא ונשכא ובעטא\u0004 \u0005[והרי אנו רואים ש\u0006היא \u0005מזיקה ונושכת ובועטת]!\u0006 \u0003אלא\u0004 יש לדרוש את שני היו\"דים \u0003כר' שמעון בן פזי,\u0004 ש\u0003אמר ר' שמעון בן פזי\u0004 שהדבר מרמז על הקושי בחיי האדם \u0003\"אוי לי מיוצרי ואוי לי מיצרי\".\u0004 שאם הולך הוא אחר אחד מהם — אוי לו מן השני.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 ניתן לפרש כפל זו בלשון היצירה \u0003כ\u0004דברי \u0003ר' ירמיה בן אלעזר\u0004 ש\u0003אמר ר' ירמיה בן אלעזר: דו\u0004 \u0005[שני]\u0006 \u0003פרצופין ברא הקדוש ברוך הוא באדם הראשון,\u0004 שברא אותו מתחילה זכר ונקבה בגוף אחד, וכפי \u0003שנאמר: \"אחור וקדם צרתני\"\u0004 (תהלים קלט, ה), ש\" צרתני\" הוא לשון צורה (פרצוף), וכדוגמתו הוא ברא אחור וקדם, כלומר, שנים.","נאמר \u0003\"ויבן ה' אלהים את הצלע\u0004 אשר לקח מן האדם לאשה ויביאה אל האדם\" (בראשית ב, כב).","ובפירוש המלה \"צלע\" נחלקו \u0003רב ושמואל; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שפירושה \u0003פרצוף,\u0004 כלומר, שחוה היתה קודם צלע (במובן צד) של האדם. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שפירושה \u0003זנב\u0004 והוא מפרש לכן \"צלע\" — כאחת מן הצלעות שבחזה.","ודנים בדבר: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 כי פירושה \u0003פרצוף\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"אחור וקדם צרתני\". אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהיתה \u0003זנב, מאי\u0004 \u0005[מה]\u0006 אם כן משמעות \u0003\"אחור וקדם צרתני\"?\u0004 ומשיבים: אפשר לפרשו \u0003כ\u0004דברי \u0003ר' אמי,\u0004 שכן \u0003אמר ר' אמי: \"אחור\"\u0004 — שהאדם מאוחר \u0003למעשה בראשית,\u0004 שנברא בסופם. \u0003\"וקדם\"\u0004 — שהוקדם \u0003לפורענות.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שביארו שהוא \u0003אחור,\u0004 מאוחר, \u0003למעשה בראשית\u0004 — הרי זה משום ש\u0003לא אברי\u0004 \u0005[נברא]\u0006 \u0003עד מעלי שבתא\u0004 \u0005[ערב שבת],\u0006 \u0003אלא\u0004 מה שאמרנו כי \u0003\"וקדם\"\u0004 פירושו שהוקדם \u0003לפורענות, פורענות דמאי\u0004 \u0005[של מה]?\u0006 \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 כי הוקדם ל\u0003פורענות\u0004 של ה\u0003נחש, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003רבי אומר\u0004 בענין זה עצמו: \u0003ב\u0004נתינת \u0003גדולה מתחילין מן הגדול, ובקללה מתחילין מן הקטן.\u0004","ומקור לדברים: \u0003בגדולה מתחילין מן הגדול\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וידבר משה אל אהרן ואל אלעזר ואל איתמר בניו הנותרים קחו\u0004 את המנחה הנותרת...\" (ויקרא י,יב), משה שהוא הגדול, קודם. וזה ש\u0003בקללה מתחילין מן הקטן\u0004 — שכן \u0003בתחלה נתקלל\u0004 ה\u0003נחש, ולבסוף,\u0004 לאחר מכן, \u0003נתקללה חוה, ולבסוף נתקלל אדם\u0004 הראשון עצמו, והרי שהפורענות לא מן האדם התחילה!","\u0003אלא\u0004 המדובר ב\u0003פורענות\u0004 של ה\u0003מבול, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וימח את כל היקום אשר על פני האדמה מאדם ועד בהמה\u0004 עד רמש ועד עוף השמים\" (בראשית ז, כג), והרי שהפורענות היתה \u0003ברישא\u0004 \u0005[בתחילה]\u0006 ב\u0003אדם והדר\u0004 \u0005[ואחר כך]\u0006 ב\u0003בהמה\u0004 ובשאר היצורים.","ועוד בנושא הראשון, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 כי חוה היתה \u0003פרצוף\u0004 מתחילה, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"וייצר\" בשני יו\"דין\u0004 — שתי יצירות. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי היתה \u0003זנב, מאי\u0004 \u0005[מה]\u0006 אם כן הסיבה לכתיבת \u0003\"וייצר\"\u0004 בשני יו\"דים?","ומשיבים: הוא דורש כאן \u0003כ\u0004מו שאמר \u0003ר' שמעון בן פזי,\u0004 ש\u0003אמר ר' שמעון בן פזי:\u0004 הכוונה היא להדגשת ענין היות האדם אומר לעצמו בכל דבר \u0003\"אוי לי מיוצרי אוי לי מיצרי\".\u0004","ועוד: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 כי היתה חוה \u0003פרצוף, היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"זכר ונקבה בראם\", אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי היתה חוה \u0003זנב, מאי\u0004 \u0005[מה]\u0006 משמעות הכתוב \u0003\"זכר ונקבה בראם\"?\u0004 ומשיבים: הדבר יתפרש \u0003כ\u0004מו שאמר \u0003ר' אבהו.\u0004 ש\u0003ר' אבהו רמי\u0004 \u0005[השליך,\u0006 הראה סתירה בין הפסוקים\u0005]:\u0006 מצד אחד \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"זכר ונקבה בראם\", ו\u0004מצד אחר \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"כי בצלם אלהים עשה את האדם\"\u0004 (שם ט, ו) ומשמע שברא אותו יחידי! \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 תפרש את הסתירה? — אלא \u0003בתחלה עלה במחשבה\u0004 אצל ה' \u0003לבראת שנים, ולבסוף לא נברא\u0004 בפועל \u0003אלא אחד.\u0004","ועוד שואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 כי היתה חוה \u0003פרצוף, היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \"ויקח אחת מצלעותיו \u0003ויסגר בשר תחתנה\"\u0004 (בראשית ב, כא), שהוצרך לסגור את הצלע (הצד) שנעדרה, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי היתה חוה \u0003זנב, מאי\u0004 \u0005[מה]\u0006 משמעות \u0003\"ויסגר בשר תחתנה\"? אמר ר' ירמיה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב זביד ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב נחמן בר יצחק: לא נצרכה\u0004 לומר דבר זה \u0003אלא למקום חתך.\u0004 בלבד, שאותו היה צורך לסגור.","ומקשים גם לדעה השניה: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 כי היתה חוה \u0003זנב, היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"ויבן\u0004 ה' אלוהים את הצלע\" (שם, שם), שהיתה צריכה בנין מחודש, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי היתה חוה \u0003פרצוף\u0004 שלם, \u0003מאי\u0004 \u0005[מה]\u0006 משמעות \u0003\"ויבן\",\u0004 מה היה לבנות בה?","ומשיבים: דבר זה מובן על פי דרשתו של \u0003ר' שמעון בן מנסיא.\u0004 ש\u0003דרש ר' שמעון בן מנסיא: מאי דכתיב\u0004 \u0005[מה\u0006 פירוש פסוק זה \u0005שנאמר]\u0006 \u0003\"ויבן ה' את הצלע\"\u0004 — \u0003מלמד שקלעה הקדוש ברוך הוא לחוה\u0004 את שערותיה, \u0003ו\u0004אחר כך \u0003הביאה לאדם, שכן בכרכי הים קורין\u0004 (קוראים) \u0003לקליעתא \"בנייתא\"\u0004 \u0005[לקליעת\u0006 שערות \u0005\"בנין\"].\u0006","\u0003דבר אחר:\u0004 משמעות הכתוב \u0003\"ויבן\"\u0004 היא הסבר לגבי עצם תבניתה, וכפי ש\u0003אמר רב חסדא, ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים\u0006 כי \u0005בברייתא\u0006 היא \u0005שנויה]:\u0006 \u0003מלמד שבנאה הקדוש ברוך הוא לחוה כבנין אוצר, מה אוצר זה\u0004 נבנה \u0003קצר\u0004 (צר) \u0003מלמעלה ורחב מלמטה, כדי לקבל את הפירות\u0004 בתוכו מבלי להתמוטט, \u0003אף אשה\u0004 בנויה כן, \u0003קצרה מלמעלה ורחבה מלמטה, כדי לקבל את הולד.\u0004","על הכתוב \u0003\"ויביאה אל האדם\"\u0004 (שם, שם) \u0003אמר ר' ירמיה בן אלעזר:\u0004 כתוב זה \u0003מלמד שנעשה הקדוש ברוך הוא שושבין לאדם הראשון,\u0004 ו\u0003מכאן למדה\u0004 ה\u0003תורה דרך ארץ שיחזור גדול עם\u0004 ה\u0003קטן בשושבינות,\u0004 כלומר, נאה לגדול לעסוק עם קטן, \u0003ואל ירע לו\u0004 שמא אין זה לפי כבודו.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 כי היתה חוה \u0003\"פרצוף\", הי מינייהו סגי ברישא\u0004 \u0005[מי מהם הלך בראש]?\u0006 \u0003אמר רב נחמן בר יצחק: מסתברא דגברא סגי ברישא\u0004 \u0005[מסתבר שהגבר הלך בראש].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יהלך אדם אחורי אשה בדרך,\u0004 שכן הוא מתבונן בה כל הזמן. \u0003ואפילו אשתו נזדמנה לו על הגשר\u0004 — \u0003יסלקנה לצדדין,\u0004 כלומר, ימהר ללכת כדי שתהיה בצדו ולא לפניו. \u0003וכל העובר אחורי אשה בנהר\u0004 לראות את בשרה כשהיא מרימה בגדיה בעוברה במים — \u0003אין לו חלק לעולם הבא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המרצה\u0004 (סופר) \u0003מעות לאשה מידו לידה כדי להסתכל בה, אפילו יש בידו תורה ומעשים טובים כמשה רבינו\u0004 — \u0003לא ינקה מדינה של גיהנם.\u0004 ורמז לדבר — ממה \u0003שנאמר \"יד ליד לא ינקה רע\"\u0004 (משלי יא, כא), הנדרש: הנותן כסף מידו שלו לידה שלה, אפילו קיבל את התורה כמשה, מידו של ה' לידו שלו — \u0003לא ינקה מדינה של גיהנם\u0004 הנקרא \"רע\".","\u0003אמר רב נחמן:\u0004 מכאן יודעים אנו ש\u0003מנוח\u0004 אבי שמשון \u0003עם הארץ היה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וילך מנוח אחרי אשתו\"\u0004 (שופטים יג, יא).","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן בר יצחק: אלא מעתה\u0004 אם מבין אתה ביטוי זה כצורתו, מה תאמר על הכתוב \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003אלקנה, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"וילך אלקנה אחרי אשתו\", ו\u0004כן \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003אלישע, דכתיב\u0004 \u0005[שנאמר]\u0006 בו \u0003\"ויקם וילך אחריה\"\u0004 (מלכים ב', ד, ל), האם \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר כי הפירוש הוא שהלך \u0003אחריה ממש? אלא\u0004 ודאי עליך לפרש שמשמעות הביטוי היא שהלך \u0003אחרי דבריה ואחרי עצתה, הכא נמי\u0004 \u0005[כך גם כן]\u0006 במנוח אפשר להבין שהלך \u0003אחרי דבריה ואחרי עצתה,\u0004 עצת אשתו והדרכתה, ולא אחריה ממש.","\u0003אמר רב אשי: ולמאי דקאמר\u0004 \u0005[ולפי מה שאמר]\u0006 \u0003רב נחמן,\u0004 לפי שיטתו כי \u0003מנוח עם הארץ היה,\u0004 ויש לומר כי \u0003אפילו בי\u0004 \u0005[בבית]\u0006 ה\u0003רב נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קרא\u0004 (למד מקרא), שאף הילדים הלומדים מקרא בלבד מוצאים דבר זה כתוב, \u0003שנאמר: \"ותקם רבקה ונערתיה ותרכבנה על הגמלים ותלכנה אחרי האיש\"\u0004 (בראשית כד, סא) — אחריו דווקא, \u0003ולא לפני האיש.\u0004","ובענין זה של הליכה שאינה ראויה \u0003אמר ר' יוחנן:\u0004 מוטב לאדם שילך \u0003אחורי ארי ולא אחורי אשה, אחורי אשה ולא אחורי עבודה זרה,\u0004 שאז הוא נראה כמלווה עבודה זרה. \u0003אחורי עבודה זרה ולא אחורי בית הכנסת, בשעה שהצבור מתפללין\u0004 שהוא נראה כפורש מכלל ישראל ואינו רוצה להשתתף עמו בתפילה.","את ההלכה האחרונה סייגו בכמה סייגים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא דלא דרי מידי\u0004 \u0005[שאינו נושא\u0006 עמו \u0005דבר],\u0006 \u0003ואי דרי מידי\u0004 \u0005[ו\u0006אולם \u0005אם\u0006 הוא \u0005נושא\u0006 עמו \u0005דבר]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור, שהכל מבינים מדוע אינו נכנס לבית הכנסת. \u0003ו\u0004כן, \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא\u0004 באופן \u0003דליכא פתחא אחרינא\u0004 \u0005[שאין פתח אחר,\u0006 נוסף\u0005]\u0006 בבית הכנסת, \u0003אבל\u0004 אם \u0003איכא פתחא אחרינא\u0004 \u0005[יש פתח אחר]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 כל חשש. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 כן, \u0003אלא דלא רכיב חמרא\u0004 \u0005[כשאינו רוכב על החמור],\u0006 \u0003אבל\u0004 אם הוא \u0003רכיב חמרא\u0004 \u0005[רוכב על החמור]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 כל חשש. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 כן, \u0003אלא\u0004 באופן \u0003דלא מנח\u0004 \u0005[שאינו מניח]\u0006 \u0003תפילין, אבל\u0004 אם הוא \u0003מנח\u0004 \u0005[מניח]\u0006 \u0003תפילין\u0004 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 כל חשש.","\u0003אמר רב: יצר הרע דומה לזבוב ויושב בין שני מפתחי הלב, שנאמר: \"זבובי מות יבאיש יביע שמן רוקח\"\u0004 (קהלת י, א). \u0003ושמואל אמר:\u0004 יצר הרע \u0003כמין חטה הוא דומה, שנאמר: \"לפתח חטאת רובץ\"\u0004 (בראשית ד, ז) שדרש \"חטאת\" כמו חיטה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003שתי כליות יש בו באדם, אחת יועצתו לטובה ואחת יועצתו לרעה. ומסתברא\u0004 \u0005[ומסתבר]\u0006 לומר כי זו שיועצתו ל\u0003טובה\u0004 נמצאת \u0003לימינו ו\u0004זו שיועצתו ל\u0003רעה\u0004 נמצאת \u0003לשמאלו, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"לב חכם לימינו ולב כסיל לשמאלו\"\u0004 (קהלת י ב).","ואגב הזכרת הכליות, מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא בענין תפקידי האברים השונים: \u0003כליות יועצות, לב מבין, לשון מחתך\u0004 את הקולות היוצאים מן הפה, וה\u0003פה גומר\u0004 את עיצובם של הקולות, ה\u0003ושט מכניס ומוציא כל מיני מאכל,\u0004 ה\u0003קנה מוציא קול\u0004"],["וה\u0003ריאה שואבת כל מיני משקין,\u0004 ה\u0003כבד כועס,\u0004 וה\u0003מרה זורקת בו טפה\u0004 של מרה \u0003ומניחתו\u0004 על ידי כך מכעסו, ה\u0003טחול שוחק\u0004 ה\u0003קרקבן טוחן\u0004 את המאכל, וה\u0003קיבה ישנה,\u0004 ה\u0003אף נעור.\u0004 ואם שינו את תפקידיהם ש\u0003נעור הישן\u0004 או \u0003ישן הנעור\u0004 — הרי האדם \u0003נמוק והולך לו.\u0004 וכן \u0003תנא\u0004 \u0005[שנו]:\u0006 \u0003אם שניהם ישנים או שניהם נעורים\u0004 — \u0003מיד\u0004 האדם \u0003מת.\u0004","ועוד בענין יצר האדם, \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' יוסי הגלילי אומר:\u0004 את ה\u0003צדיקים\u0004 ה\u0003יצר\u0004 ה\u0003טוב שופטן, שנאמר: \"ולבי חלל בקרבי\"\u0004 (תהלים קט, כב), שהיצר הרע נעלם לגמרי מלבו. ה\u0003רשעים\u0004 ה\u0003יצר\u0004 ה\u0003רע שופטן, שנאמר: \"נאם פשע לרשע בקרב לבי אין פחד אלהים לנגד עיניו\"\u0004 (שם לו, ב). וה\u0003בינונים\u0004 — \u0003זה וזה,\u0004 היצר הטוב והיצר הרע \u0003שופטן, שנאמר: \"יעמד לימין אביון להושיע משפטי נפשו\"\u0004 (שם קט, לא), שיש אנשים שנשפטים על ידי שניים.","\u0003אמר רבה:\u0004 אנשים \u0003כגון אנו\u0004 הם ה\u0003בינונים. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 תלמידו ובן אחיו: אם כן, \u0003לא שביק מר חיי\u0004 \u0005[אין אדוני מניח חיים]\u0006 \u0003לכל בריה,\u0004 שאם אדם כמוך הוא בינוני, כיצד איפוא יעריכו את שאר בני האדם?","\u0003ואמר רבא: לא איברי עלמא\u0004 \u0005[נברא העולם]\u0006 \u0003אלא לרשיעי גמורי\u0004 \u0005[לרשעים גמורים]\u0006 \u0003או לצדיקי גמורי\u0004 \u0005[לצדיקים גמורים],\u0006 והשאר אינם חיים בשלמות בשום עולם. ועוד \u0003אמר רבא: לידע אינש בנפשיה\u0004 \u0005[יידע האדם בעצמו]\u0006 \u0003אם צדיק גמור הוא אם לאו\u0004 \u0005[לא],\u0006 שאם אינו צדיק גמור יידע שחייו יהיו חיי סבל. וכעין זה \u0003אמר רב: לא איברי עלמא\u0004 \u0005[נברא העולם]\u0006 \u0003אלא לאחאב בן עמרי\u0004 הרשע שאין לו חלק לעולם הבא \u0003ולר' חנינא בן דוסא.\u0004 ומבארים: \u0003לאחאב בן עמרי\u0004 — \u0003העולם הזה, ולר' חנינא בן דוסא\u0004 — \u0003העולם הבא.\u0004","שנינו במשנה את פירוש הכתוב \u0003\"ואהבת את ה' אלהיך\u0004 בכל לבבך ובכל נפשך ובכל מאודך\u0003\"\u0004 (דברים ו, ה). וכהמשך לכך \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: אם נאמר \"בכל נפשך\", למה נאמר \"בכל מאדך\"? ו\u0004להיפך, \u0003אם נאמר \"בכל מאדך\", למה נאמר \"בכל נפשך\"? אלא\u0004 משמעות הדבר ש\u0003אם יש לך אדם שגופו חביב עליו\u0004 יותר \u0003מממונו\u0004 — \u0003לכך נאמר \"בכל נפשך\",\u0004 שעליו לתת את נפשו על קידוש ה'. \u0003ואם יש לך אדם שממונו חביב עליו מגופו\u0004 — \u0003לכך נאמר \"בכל מאדך\",\u0004 שמובנו הוא — בכל רכושך. \u0003ר' עקיבא אומר: \"בכל נפשך\"\u0004 יש להבין: \u0003אפילו נוטל את נפשך.\u0004","ומסופר באריכות כיצד חי וקיים ר' עקיבא עצמו את הדברים הללו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פעם אחת\u0004 לאחר מרד בר כוכבא \u0003גזרה מלכות הרשעה\u0004 (רומי) \u0003שלא יעסקו ישראל בתורה. בא פפוס בן יהודה ומצאו\u0004 את \u0003ר' עקיבא שהיה מקהיל קהלות ברבים ועוסק בתורה. אמר ליה\u0004 \u0005[לו]\u0006 פפוס לר' עקיבא: \u0003עקיבא\u0004 וכי \u0003אי\u0004 (אין) \u0003אתה מתירא מפני\u0004 ה\u0003מלכות?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' עקיבא: \u0003אמשול לך משל, למה הדבר דומה\u0004 — \u0003לשועל שהיה מהלך על גב\u0004 (שפת) \u0003הנהר, וראה\u0004 את ה\u0003דגים שהיו מתקבצים\u0004 ובורחים \u0003ממקום למקום. אמר להם: מפני מה אתם בורחים? אמרו לו:\u0004 בורחים אנו \u0003מפני\u0004 ה\u0003רשתות שמביאין עלינו בני אדם. אמר להם:\u0004 שמא \u0003רצונכם שתעלו ליבשה, ונדור אני ואתם, כשם שדרו אבותי עם אבותיכם? אמרו לו\u0004 הדגים: וכי \u0003אתה הוא שאומרים עליך פקח שבחיות?! לא פקח אתה, אלא טפש אתה! ומה במקום חיותנו,\u0004 בתוך המים, \u0003אנו מתיראין, במקום מיתתנו\u0004 מחוץ למים — \u0003על אחת כמה וכמה.\u0004 והנמשל: \u0003אף אנחנו\u0004 היהודים \u0003עכשיו שאנו יושבים ועוסקים בתורה, שכתוב בה\u0004 ביחס לעצמה: \u0003\"כי הוא חייך וארך ימיך\"\u0004 (דברים ל, כ), \u0003כך\u0004 אנו מתיראים מהמלכות, \u0003אם אנו הולכים ומבטלים ממנה,\u0004 שזהו מקום ומצב מיתתנו — \u0003על אחת כמה וכמה!\u0004","\u0003אמרו: לא היו ימים מועטים,\u0004 שלא עבר זמן רב \u0003עד שתפסוהו\u0004 את \u0003ר' עקיבא וחבשוהו בבית האסורים, ותפסו\u0004 את \u0003פפוס בן יהודה וחבשוהו אצלו. אמר לו\u0004 ר' עקיבא לפפוס: \u0003פפוס, מי הביאך לכאן? אמר ליה\u0004 \u0005[לו]\u0006 פפוס: \u0003אשריך ר' עקיבא שנתפסת על דברי תורה. אוי לו לפפוס שנתפס על דברים בטלים.\u0004","ומסופר כי \u0003בשעה שהוציאו את ר' עקיבא להריגה זמן קריאת שמע היה, והיו סורקים את בשרו במסרקות של ברזל, והיה מקבל עליו עול מלכות שמים,\u0004 שקרא קריאת שמע באותה שעה. \u0003אמרו לו תלמידיו: רבינו, עד כאן?!\u0004 וכי גם בשעה זו מוצא אתה לקרוא את שמע? \u0003אמר להם: כל ימי הייתי מצטער על פסוק זה \"בכל נפשך\"\u0004 במשמעות \u0003אפילו נוטל את נשמתך.\u0004 ו\u0003אמרתי\u0004 לעצמי: \u0003מתי יבא לידי ואקיימנו, ועכשיו שבא לידי, לא אקיימנו?\u0004 ו\u0003היה מאריך ב\u0004מלה \u0003\"אחד\", עד שיצתה\u0004 \u0005[יצאה]\u0006 \u0003נשמתו ב\"אחד\". יצתה בת קול\u0004 מן השמים \u0003ואמרה: \"אשריך ר' עקיבא שיצאה נשמתך ב\"אחד\".\u0004","\u0003אמרו מלאכי השרת לפני הקדוש ברוך הוא:\u0004 וכי \u0003זו תורה וזו שכרה?\u0004 וכפי שנאמר \u0003\"ממתים ידך ה' ממתים\u0004 מחלד\u0003\"\u0004 (תהלים יז, יד), כלומר, ידך ה' הורגת וממיתה ואיננה מצילה! \u0003אמר להם\u0004 הקדוש ברוך הוא את סיומו של אותו פסוק: \u0003\"חלקם בחיים\"\u0004 (שם). ומכיון שכן \u0003יצתה בת קול ואמרה: \"אשריך ר' עקיבא שאתה מזומן לחיי העולם הבא\",\u0004 שחלקך הוא כבר בחיים נצחיים.","שנינו במשנה ש\u0003לא יקל אדם את ראשו כנגד שער המזרח\u0004 לפי \u0003שהוא מכוון כנגד בית קדשי הקדשים.\u0004 כדי לסייג את ההלכה הזאת \u0003אמר רב יהודה אמר רב: לא אמרו\u0004 לאסור מנהג בזיון \u0003אלא מן הצופים ולפנים,\u0004 כלומר, לכל צד בירושלים שהוא קרוב יותר למקדש מהר הצופים, \u0003ו\u0004כן זהו דווקא \u0003ברואה,\u0004 כשנראה מקום המקדש שם, \u0003איתמר נמי\u0004 \u0005[\u0006וכן \u0005גם כן נאמר]:\u0006 \u0003אמר ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: לא אמרו אלא מן הצופים ולפנים, וברואה ובשאין גדר\u0004 המפסיקה, \u0003ו\u0004רק \u0003בזמן שהשכינה שורה,\u0004 כשהבית בבניינו.","בהקשר לכך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנפנה\u0004 לצרכיו \u0003ביהודה, לא יפנה\u0004 כשהוא יושב בכיוון \u0003מזרח ומערב,\u0004 שאז הוא פונה כנגד ירושלים, \u0003אלא צפון ודרום. ו\u0004אילו \u0003בגליל\u0004 שהוא צפונה לירושלים \u0003לא יפנה אלא מזרח ומערב. ור' יוסי מתיר. שהיה ר' יוסי אומר: לא אסרו\u0004 כל ההגבלות הללו \u0003אלא ברואה, ובמקום שאין שם גדר, ובזמן שהשכינה שורה. וחכמים אוסרים.\u0004","ושואלים: דעת \u0003חכמים\u0004 אלה האוסרים \u0003היינו\u0004 \u0005[זוהי]\u0006 בדיוק דעת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שגם הוא אוסר! ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה לגבי \u0003צדדין.\u0004 במקום ביהודה שאינו ממש מזרחה או מערבה לירושלים, או בגליל שאינו מכוון צפונה לה, לדעת תנא קמא — אסור, ולדעת חכמים יהא מותר.","\u0003תניא אידך\u0004 \u0005[שנינו\u0006 בברייתא \u0005אחרת]:\u0006 \u0003הנפנה\u0004 לצרכיו \u0003ביהודה\u0004 — \u0003לא יפנה\u0004 לצד \u0003מזרח ומערב אלא\u0004 רק ל\u0003צפון ודרום. ובגליל,\u0004 לצד \u0003צפון ודרום\u0004 — \u0003אסור,\u0004 ולצד \u0003מזרח ומערב\u0004 — \u0003מותר. ור' יוסי מתיר. שהיה ר' יוסי אומר: לא אסרו אלא ברואה\u0004 את פני בית המקדש. \u0003ר' יהודה אומר: בזמן שבית המקדש קיים\u0004 — \u0003אסור, בזמן שאין בית המקדש קיים\u0004 — \u0003מותר.\u0004 ומוסיפים עוד ש\u0003ר' עקיבא אוסר בכל מקום\u0004 להפנות מזרח ומערב.","ומקשים: שיטת \u0003ר' עקיבא\u0004 הלא \u0003היינו\u0004 \u0005[זוהי]\u0006 בדיוק שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שאף הוא אוסר! והשיבו: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה לגבי \u0003חוץ לארץ,\u0004 שלדעת ר' עקיבא בכל מקום, ואפילו חוץ לארץ — אסור.","ומסופר כי \u0003רבה הוו שדיין ליה לבני\u0004 \u0005[היו מונחות אצלו\u0006 בבית הכסא \u0005הלבנים]\u0006 שהיה נפנה עליהם בין \u0003מזרח ומערב. אזל\u0004 \u0005[הלך]\u0006 \u0003אביי שדנהו\u0004 \u0005[\u0006ו\u0005השליכן]\u0006 לצד \u0003צפון ודרום\u0004 לדעת אם מקפיד רבה על הכיוון, או שהניחן כך במקרה, \u0003על\u0004 \u0005[נכנס]\u0006 \u0003רבה תרצנהו\u0004 \u0005[תקנן].\u0006 \u0003אמר: מאן האי דקא מצער לי\u0004 \u0005[מי הוא זה שמצער אותי]?\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כ\u0004שיטת \u0003ר' עקיבא סבירא לי\u0004 \u0005[סבור אני]\u0006 ש\u0003אמר: בכל מקום אסור.\u0004"]]};
